INSERT INTO `agendas` (`id`, `title`, `event_date`, `event_time`, `excerpt`, `description`, `cover_url`, `is_visible`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 'Workshop Penguatan Keterampilan Parenting', '22 November 2023', '08.00 WIB', 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mambaul Ulum (IIM) Surakarta sukses menyelenggarakan Workshop Penguatan Keterampilan Parenting pada Rabu, 22 November 2023....', 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mambaul Ulum (IIM) Surakarta sukses menyelenggarakan Workshop Penguatan Keterampilan Parenting pada Rabu, 22 November 2023. Acara yang berlangsung di Aula Kampus IIM Surakarta ini menghadirkan dua narasumber kompeten, yakni Siti Mariyah, S.Pd, Kepala TK Perwanida VIII Wonogiri, dan Anita Wardani, M.Pd, dosen PIAUD IIM Surakarta.\n\nWorkshop ini dimoderatori oleh Annafi’ Nurul Ilmi Azizah, M.Pd, dosen PIAUD IIM Surakarta. Dalam sambutannya, Ketua Prodi PIAUD IIM Surakarta menyampaikan bahwa kegiatan ini bertujuan untuk membekali mahasiswa dan peserta lainnya dengan wawasan dan keterampilan praktis dalam mendukung peran orang tua sebagai pendidik utama bagi anak usia dini.\n\nSesi pertama diisi oleh Siti Mariyah, S.Pd, yang berbagi pengalaman tentang praktik parenting efektif di lingkungan sekolah dan keluarga. Beliau menekankan pentingnya komunikasi positif antara orang tua dan anak untuk membangun kedekatan emosional serta mengembangkan karakter anak.\n\nSementara itu, pada sesi kedua, Anita Wardani, M.Pd memberikan materi mengenai peran pendidik dalam mendukung penguatan keterampilan parenting melalui kolaborasi antara sekolah dan keluarga. “Pendidikan anak usia dini tidak hanya tanggung jawab guru di sekolah, tetapi juga membutuhkan peran aktif orang tua dalam memberikan pengalaman belajar yang menyenangkan dan bermakna di rumah,” ujarnya.\n\nAcara ini berlangsung interaktif, dengan peserta yang terdiri dari mahasiswa, guru PAUD, dan orang tua aktif berdiskusi serta berbagi pengalaman. Workshop ini diharapkan mampu memberikan wawasan baru dan keterampilan praktis bagi peserta dalam menjalankan peran sebagai pendidik dan orang tua yang efektif.\n\nKegiatan ini ditutup dengan penyerahan sertifikat penghargaan kepada narasumber dan sesi foto bersama. Peserta mengapresiasi penyelenggaraan workshop ini sebagai langkah nyata Prodi PIAUD IIM Surakarta dalam mendukung peningkatan kompetensi parenting di era modern.', '/api/v1/media/0b3ccc52-5954-4ba2-9a37-713a4a96f85d', 1, 0, '2026-11-24 02:10:37', '2026-11-24 02:15:33'),
(2, 'Visiting Lecture untuk mata kuliah Metodologi Studi Islam', '4 Desember 2023', '13.00 WIB', 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mambaul Ulum (IIM) Surakarta menggelar Visiting Lecture untuk mata kuliah Metodologi Studi Islam pada Senin, 4 Desember 2023...', 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mambaul Ulum (IIM) Surakarta menggelar Visiting Lecture untuk mata kuliah Metodologi Studi Islam pada Senin, 4 Desember 2023 secara online. Kegiatan ini berlangsung dengan menghadirkan dua narasumber utama, yakni Adi Wijaya, M.Pd, dosen Program Studi Pendidikan Agama Islam Universitas Maarif Lampung, dan Mukhlis Fathurohman, M.SI, dosen pengampu mata kuliah Metodologi Studi Islam di IIM Surakarta.\n\nAcara dibuka oleh Nur Hidayah, M.Si, Dekan Fakultas Tarbiyah IIM Surakarta, yang juga bertindak sebagai keynote speaker. Dalam sambutannya, beliau menekankan pentingnya penguasaan metodologi studi Islam sebagai landasan dalam memahami dan mengembangkan ilmu keislaman secara sistematis dan kontekstual.\n\nPada sesi pertama, Adi Wijaya, M.Pd menyampaikan materi tentang pendekatan-pendekatan dalam studi Islam, seperti pendekatan normatif, historis, dan sosiologis. Beliau juga menekankan perlunya memahami Islam dalam perspektif yang inklusif untuk menjawab tantangan globalisasi.\n\nSesi kedua dilanjutkan oleh Mukhlis Fathurohman, M.SI, yang membahas lebih mendalam tentang penerapan metodologi studi Islam dalam konteks pendidikan anak usia dini. “Sebagai calon pendidik, penting bagi mahasiswa untuk memahami bagaimana ajaran Islam dapat diterapkan secara kontekstual dalam mendidik anak usia dini, sehingga mereka dapat tumbuh dengan nilai-nilai Islam yang relevan dengan zamannya,” jelasnya.\n\nKegiatan ini mendapat antusiasme tinggi dari para peserta, terutama mahasiswa PIAUD, yang aktif berdiskusi dan bertanya. Acara ditutup dengan sesi tanya jawab yang interaktif, di mana para narasumber memberikan solusi praktis atas berbagai pertanyaan terkait penerapan metodologi studi Islam dalam pendidikan.\n\nVisiting lecture ini diharapkan dapat memberikan wawasan baru dan memperkuat kompetensi mahasiswa dalam memahami serta mengimplementasikan metodologi studi Islam di dunia pendidikan.', '/api/v1/media/458c0b1d-532e-42c0-a8b2-d9f44052581a', 1, 0, '2026-11-24 02:14:23', '2026-11-24 02:15:37'),
(3, 'Visiting Lecture Mata Kuliah Perkembangan Nilai Agama & Moral Anak Usia Dini', '6 Desember 2023', '13.30 WIB', 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mambaul Ulum (IIM) Surakarta kembali menyelenggarakan Visiting Lecture pada Rabu, 6 Desember 2023 bertempat di Aula Kampus IIM...', 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mambaul Ulum (IIM) Surakarta kembali menyelenggarakan Visiting Lecture pada Rabu, 6 Desember 2023 bertempat di Aula Kampus IIM Surakarta jam 13.30- selesai untuk mata kuliah Perkembangan Nilai Agama dan Moral Anak Usia Dini. Acara ini menghadirkan tiga narasumber kompeten, yaitu Rina Wibowo, M.Pd, Kepala PAUD RA Chairunissa Sukoharjo, Annafi’ Nurul ‘Ilmi Azizah, M.Pd, dosen pengampu mata kuliah, dan Anita Wardani, M.Pd, dosen PIAUD IIM Surakarta.\n\nKegiatan ini dimoderatori oleh Elina Intan Apriliani, S.Pd, dosen PIAUD IIM Surakarta. Dalam sambutannya, Ketua Prodi PIAUD menyampaikan apresiasi atas kehadiran narasumber yang diharapkan mampu memberikan wawasan baru terkait pendekatan dan strategi dalam menanamkan nilai agama dan moral pada anak usia dini.\n\nRina Wibowo, M.Pd, dalam sesi pertama, memaparkan tentang praktik terbaik dalam mengintegrasikan nilai agama dan moral di lembaga PAUD. Beliau berbagi pengalaman mengenai pendekatan berbasis karakter yang diterapkan di PAUD RA Chairunissa Sukoharjo.\n\nSesi kedua dilanjutkan oleh Annafi’ Nurul ‘Ilmi Azizah, M.Pd, yang membahas pentingnya memahami tahapan perkembangan anak usia dini untuk menyusun strategi pendidikan agama dan moral yang sesuai. Beliau menekankan bahwa penanaman nilai harus dilakukan secara konsisten dan kreatif agar anak-anak dapat memahami serta menerapkan nilai tersebut dalam kehidupan sehari-hari.\n\nAnita Wardani, M.Pd, sebagai narasumber ketiga, memberikan penjelasan mendalam tentang metode inovatif dalam pengajaran nilai agama dan moral di kelas. “Kita perlu memanfaatkan berbagai media pembelajaran, termasuk teknologi, untuk menjadikan proses pembelajaran nilai lebih menarik dan efektif bagi anak usia dini,” ujarnya.\n\nAcara ini diikuti dengan antusias oleh mahasiswa PIAUD, yang aktif berdiskusi dan mengajukan pertanyaan terkait tantangan dan peluang dalam pengembangan nilai agama dan moral pada anak usia dini.', '/api/v1/media/26861c9f-d307-4571-89fa-c7ce141d6fd8', 1, 0, '2026-11-24 02:15:25', '2026-11-24 02:15:25'),
(4, 'Visiting Lecture Mata Kuliah Bahasa Arab untuk Anak Usia Dini', '17 Desember 2023', '12.30 WIB', 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mambaul Ulum (IIM) Surakarta sukses menggelar Visiting Lecture untuk mata kuliah Bahasa Arab untuk Anak Usia Dini secara online...', 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mambaul Ulum (IIM) Surakarta sukses menggelar Visiting Lecture untuk mata kuliah Bahasa Arab untuk Anak Usia Dini secara online pada Kamis, 17 Desember 2023. Acara ini menghadirkan dua narasumber utama, yakni Jaurohatun Nafisah, M.Pd, dosen Pendidikan Bahasa Arab Universitas Maarif Lampung, dan Dudi Budi Astoko, M.Pd., dosen mata kuliah Pendidikan Bahasa Arab IIM Surakarta.\n\nAcara dibuka oleh keynote speaker Dra. Hj. Nur Hidayah, M.SI, Dekan Fakultas Tarbiyah IIM Surakarta, yang dalam sambutannya menyampaikan pentingnya pengenalan Bahasa Arab sejak usia dini sebagai bagian dari pembentukan karakter dan pengembangan keterampilan bahasa yang berorientasi pada nilai-nilai Islam.\n\nJaurohatun Nafisah, M.Pd, dalam sesi pertama, membahas tentang metode kreatif pengajaran Bahasa Arab untuk anak usia dini. Beliau menekankan perlunya pendekatan yang menyenangkan dan berbasis permainan agar anak-anak lebih mudah memahami dan mencintai Bahasa Arab. “Menggunakan lagu, cerita, dan media visual sangat efektif dalam menarik minat anak-anak terhadap Bahasa Arab,” jelasnya.\n\nSesi kedua dilanjutkan oleh Dudi Budi Astoko, M.Pd yang memaparkan penerapan strategi pembelajaran Bahasa Arab di lingkungan pendidikan formal dan informal. Beliau menyoroti pentingnya peran guru dalam menciptakan suasana belajar yang kondusif dan interaktif. “Bahasa Arab untuk anak usia dini harus diajarkan secara kontekstual agar anak-anak dapat mengaitkannya dengan kehidupan sehari-hari,” ujarnya.\n\nKegiatan ini diikuti dengan antusias oleh mahasiswa PIAUD IIM Surakarta, yang memanfaatkan sesi tanya jawab untuk menggali lebih dalam terkait tantangan dan solusi dalam pengajaran Bahasa Arab untuk anak usia dini.\n\nAcara ini diakhiri dengan ucapan terima kasih kepada para narasumber dan penutupan resmi oleh moderator. Visiting lecture ini diharapkan dapat memberikan wawasan dan inspirasi baru kepada mahasiswa dalam mengembangkan kemampuan mereka sebagai pendidik Bahasa Arab yang kompeten dan inovatif.', '/api/v1/media/978f9a8c-cd47-499e-b737-b7f7914d82ce', 1, 0, '2026-11-24 02:20:33', '2026-11-24 02:20:33'),
(5, 'Visiting Lecture : Dasar-Dasar Pendidikan Islam untuk Anak Usia Dini', '14 Maret 2024', '13.00 WIB', 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mambaul Ulum (IIM) Surakarta mengadakan kegiatan visiting lecture dengan tema “Dasar-Dasar Pendidikan Islam untuk Anak Usia...', 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mambaul Ulum (IIM) Surakarta mengadakan kegiatan visiting lecture dengan tema “Dasar-Dasar Pendidikan Islam untuk Anak Usia Dini”. Acara ini berlangsung pada hari Kamis, 14 Maret 2024, bertempat di Aula IIM Surakarta.\n\nKegiatan ini menghadirkan dua narasumber yang ahli di bidangnya. Narasumber pertama adalah Nurul Hudati, S.Pd., Kepala Sekolah TK Aisyiyah Bulak Sukoharjo, yang berbagi pengalaman praktis tentang implementasi pendidikan Islam pada anak usia dini di lembaga pendidikan. Narasumber kedua, Elina Intan Apriliani, S.Pd., M.Pd., dosen mata kuliah Dasar-Dasar Pendidikan Anak Usia Dini di IIM Surakarta, memberikan paparan mendalam mengenai konsep dasar dan pendekatan pendidikan Islam untuk anak usia dini.\n\nAcara ini dimoderatori oleh Dekan Fakultas Tarbiyah IIM Surakarta, Dra. Hj. Nur Hidayah, M.Si., yang memandu jalannya diskusi dengan interaktif dan dinamis.\n\nDalam sambutannya, Ketua Prodi PIAUD menyampaikan harapan bahwa kegiatan ini dapat memberikan wawasan baru bagi mahasiswa dalam memahami pentingnya pendidikan Islam sejak usia dini, sekaligus memperkaya perspektif akademik dan praktis di bidang tersebut.\n\nPara peserta yang terdiri dari mahasiswa, dosen, dan praktisi pendidikan anak usia dini sangat antusias mengikuti kegiatan ini. Diskusi yang berlangsung di sesi tanya jawab menunjukkan ketertarikan peserta terhadap topik yang dibahas.\n\nDengan adanya kegiatan seperti ini, Prodi PIAUD IIM Surakarta terus berkomitmen untuk menghadirkan pembelajaran yang relevan dan berkualitas bagi para mahasiswa, sekaligus berkontribusi dalam pengembangan pendidikan Islam di Indonesia.', '/api/v1/media/d348c91a-b245-49a1-aeed-78dc4369dbc2', 1, 0, '2026-11-24 02:21:45', '2026-11-24 02:21:45'),
(6, 'Visiting Lecture : Membangun Karakter Anak Usia Dini melalui Pendidikan Moral & Etika', '19 April 2024', '08.00 WIB', 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mambaul Ulum (IIM) Surakarta sukses menyelenggarakan visiting lecture secara daring dengan tema “Membangun Karakter Anak Usia...', 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mambaul Ulum (IIM) Surakarta sukses menyelenggarakan visiting lecture secara daring dengan tema “Membangun Karakter Anak Usia Dini melalui Pendidikan Moral dan Etika”. Kegiatan ini diadakan pada Jumat, 19 April 2024, melalui platform online dan dihadiri oleh mahasiswa, dosen, serta praktisi pendidikan dari berbagai daerah.\n\nAcara ini diawali dengan sambutan dari keynote speaker, Dekan Fakultas Tarbiyah IIM Surakarta, Dra. Hj. Nur Hidayah, M.Si., yang menekankan pentingnya pendidikan moral dan etika dalam membentuk karakter anak sejak usia dini.\n\nHadir sebagai narasumber pertama, Siti Rahayu, S.E., Kepala Sekolah RA Amanah Ummah Laweyan, memaparkan pengalaman praktisnya dalam mengintegrasikan pendidikan moral dan etika di lingkungan sekolah. Narasumber kedua, Anita Wardani, M.Pd., dosen Prodi Pendidikan Anak Usia Dini IIM Surakarta, memberikan wawasan teoretis mengenai konsep pendidikan karakter yang berbasis nilai-nilai Islam untuk anak usia dini.\n\nDiskusi yang dimoderatori oleh tim akademik Prodi PIAUD berlangsung interaktif, dengan peserta aktif bertanya dan berbagi pengalaman seputar tantangan dalam penerapan pendidikan moral dan etika.\n\nKetua Prodi PIAUD IIM Surakarta menyampaikan apresiasinya atas antusiasme peserta dalam kegiatan ini. “Melalui visiting lecture ini, kami berharap mahasiswa dan praktisi pendidikan dapat memperkaya pemahaman mereka tentang cara membangun karakter anak usia dini secara efektif dan relevan dengan perkembangan zaman,” ujarnya.\n\nAcara ini merupakan bagian dari upaya Prodi PIAUD IIM Surakarta dalam memberikan pengalaman pembelajaran yang aplikatif dan inovatif bagi mahasiswa, sekaligus mendukung pengembangan pendidikan Islam yang berkarakter di Indonesia.', '/api/v1/media/498c17aa-73b6-42e8-87d5-1743bbc2d011', 1, 0, '2026-11-24 02:22:52', '2026-11-24 02:22:52'),
(7, 'Visiting Lecture :  Inovasi Metode Interaktif untuk Meningkatkan Literasi dan Numerasi Anak Usia Dini', '27 April 2024', '10.00 WIB', 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mambaul Ulum (IIM) Surakarta kembali mengadakan visiting lecture secara daring dengan tema “Inovasi Metode Interaktif untuk...', 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mambaul Ulum (IIM) Surakarta kembali mengadakan visiting lecture secara daring dengan tema “Inovasi Metode Interaktif untuk Meningkatkan Literasi dan Numerasi Anak Usia Dini”. Acara ini berlangsung pada Sabtu, 27 April 2024, melalui platform online dan diikuti oleh mahasiswa, dosen, serta praktisi pendidikan dari berbagai wilayah.\n\nKegiatan ini dibuka oleh keynote speaker, Dekan Fakultas Tarbiyah IIM Surakarta, Dra. Hj. Nur Hidayah, M.Si., yang dalam sambutannya menyoroti pentingnya inovasi dalam metode pengajaran untuk meningkatkan kemampuan literasi dan numerasi anak usia dini, yang menjadi dasar keberhasilan pendidikan di jenjang berikutnya.\n\nNarasumber pertama, Susiloningsih, S.Pd., Kepala Sekolah BA Aisyiyah Babadan, memaparkan praktik-praktik inovatif yang telah diterapkan di sekolahnya untuk meningkatkan kemampuan literasi dan numerasi anak usia dini. Narasumber kedua, Annafi’ Nurul ‘Ilmi Azizah, M.Pd., dosen Prodi Pendidikan Islam Anak Usia Dini IIM Surakarta, memberikan perspektif akademik mengenai strategi pengembangan metode interaktif berbasis pendekatan islami dan perkembangan anak.\n\nDiskusi ini dipandu oleh moderator Elina Intan Apriliani, S.Pd., M.Pd., yang memastikan jalannya acara berlangsung dinamis dan interaktif. Peserta diajak untuk aktif berdiskusi dan berbagi pengalaman, menciptakan suasana pembelajaran yang kolaboratif.\n\nKetua Prodi PIAUD IIM Surakarta menyampaikan bahwa kegiatan ini merupakan salah satu upaya Prodi PIAUD untuk membekali mahasiswa dengan pengetahuan dan keterampilan terkini di bidang pendidikan anak usia dini. “Kami berharap melalui kegiatan ini, mahasiswa dapat mengimplementasikan inovasi-inovasi pembelajaran yang relevan dengan kebutuhan anak usia dini di era modern,” ujarnya.\n\nDengan semangat meningkatkan kualitas pendidikan anak usia dini, Prodi PIAUD IIM Surakarta terus berkomitmen untuk menghadirkan kegiatan akademik yang bermanfaat dan aplikatif bagi para mahasiswa dan praktisi pendidikan.', '/api/v1/media/80f95bd6-4e13-454d-806a-60a673dc0cb7', 1, 0, '2026-11-24 03:18:23', '2026-11-24 03:18:23'),
(8, 'Visiting Lecture Mata Kuliah Perkembangan Kognitif Anak Usia Dini', '18 Mei 2024', '15.30 WIB', 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mambaul Ulum (IIM) Surakarta kembali menyelenggarakan visiting lecture secara daring. Kegiatan ini merupakan bagian dari mata...', 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mambaul Ulum (IIM) Surakarta kembali menyelenggarakan visiting lecture secara daring. Kegiatan ini merupakan bagian dari mata kuliah Perkembangan Kognitif Anak Usia Dini dan diadakan pada Sabtu, 18 Mei 2024.\n\nAcara ini diawali dengan sambutan dari keynote speaker, Dekan Fakultas Tarbiyah IIM Surakarta, Dra. Hj. Nur Hidayah, M.Si. Dalam sambutannya, beliau menekankan pentingnya pemahaman tentang perkembangan kognitif anak usia dini sebagai landasan untuk merancang metode pembelajaran yang efektif.\n\nSebagai narasumber pertama, Jazariyah, M.Pd., Kepala Program Studi PIAUD IAIN Syekh Nurjati Cirebon, memberikan paparan tentang pendekatan inovatif dalam mendukung perkembangan kognitif anak usia dini berdasarkan hasil penelitian dan praktik terbaik di lapangan.\n\nNarasumber kedua, Annafi’ Nurul ‘Ilmi Azizah, M.Pd., dosen Prodi PIAUD IIM Surakarta, melengkapi diskusi dengan memberikan pandangan akademik terkait teori perkembangan kognitif anak usia dini serta penerapannya dalam pendidikan Islam.\n\nKegiatan ini berlangsung secara interaktif dengan antusiasme tinggi dari para peserta, yang terdiri dari mahasiswa, dosen, dan praktisi pendidikan. Diskusi yang kaya wawasan menciptakan suasana pembelajaran yang kolaboratif dan aplikatif.\n\nKetua Prodi PIAUD IIM Surakarta menyampaikan bahwa visiting lecture ini bertujuan untuk memperluas wawasan mahasiswa dalam memahami perkembangan kognitif anak usia dini, baik dari sisi teoretis maupun praktis. “Kami berharap kegiatan ini dapat memberikan kontribusi nyata dalam pengembangan kompetensi mahasiswa, terutama dalam mendukung tumbuh kembang anak usia dini secara optimal,” ungkapnya.\n\nDengan komitmen untuk terus meningkatkan kualitas pembelajaran, Prodi PIAUD IIM Surakarta bertekad menghadirkan program-program akademik yang relevan dan bermanfaat bagi dunia pendidikan anak usia dini di Indonesia.', '/api/v1/media/247d1fbe-b6a4-43ec-b77c-33f7a801d19c', 1, 0, '2026-11-24 03:21:30', '2026-11-24 03:21:30'),
(9, 'Visiting Lecture Mata Kuliah Perkembangan Fisik Motorik Anak Usia Dini', '18 Mei 2024', '13.00 WIB', 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mambaul Ulum Surakarta (IIM Surakarta) mengadakan acara Visiting Lecture dalam mata kuliah Perkembangan Fisik Motorik Anak Usia...', 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mambaul Ulum Surakarta (IIM Surakarta) mengadakan acara Visiting Lecture dalam mata kuliah Perkembangan Fisik Motorik Anak Usia Dini secara daring. Kegiatan ini bertujuan untuk memberikan wawasan lebih mendalam kepada mahasiswa mengenai perkembangan fisik dan motorik anak usia dini.\n\nAcara yang diselenggarakan pada tanggal 18 Mei 2024 ini menghadirkan narasumber yang berkompeten di bidangnya. Narasumber pertama adalah Dra. Hj. Muji Rahayu, M.Pd, seorang dosen PIAUD dari IAI DDI Polewali Mandar, Sumatera Barat, yang memberikan materi tentang pentingnya pemahaman perkembangan fisik dan motorik pada anak usia dini.\n\nSebagai keynote speaker, acara ini juga menghadirkan Dekan Fakultas Tarbiyah IIM Surakarta, Dra. Hj. Nur Hidayah, M.Si, yang menyampaikan pentingnya kolaborasi dalam pendidikan anak usia dini serta pengaruh perkembangan fisik terhadap aspek lainnya dalam pertumbuhan anak.\n\nNarasumber kedua adalah Elina Intan Apriliani, S.Pd., M.Pd, dosen Prodi Pendidikan Anak Usia Dini IIM Surakarta, yang membahas strategi dan pendekatan dalam mendukung perkembangan motorik anak usia dini dengan metode yang tepat dan efektif.\n\nKegiatan ini diharapkan dapat memberikan pemahaman yang lebih luas kepada mahasiswa mengenai konsep dan praktik perkembangan fisik motorik anak usia dini, serta memperkaya pengetahuan mereka dalam menghadapi tantangan pendidikan anak di era modern.\n\nDengan adanya kegiatan seperti ini, Prodi PIAUD IIM Surakarta berharap dapat terus memberikan kontribusi positif dalam pengembangan pendidikan anak usia dini yang berkualitas.', '/api/v1/media/f30c4949-a050-498f-8a4e-79c88e989b6a', 1, 0, '2026-11-24 03:22:46', '2026-11-24 03:22:46'),
(10, 'Visiting Lecture Mata Kuliah Bahasa Inggris Anak Usia Dini', '22 Mei 2024', '14.30 WIB', 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mambaul Ulum Surakarta (IIM Surakarta) kembali menyelenggarakan Visiting Lecture secara daring dalam mata kuliah Bahasa Inggris...', 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mambaul Ulum Surakarta (IIM Surakarta) kembali menyelenggarakan Visiting Lecture secara daring dalam mata kuliah Bahasa Inggris Anak Usia Dini. Kegiatan ini bertujuan untuk memperkaya pengetahuan mahasiswa mengenai pentingnya pengajaran bahasa Inggris sejak dini dalam pembentukan keterampilan bahasa anak.\n\nAcara yang diadakan pada 22 Mei 2024 ini menghadirkan narasumber yang sangat berkompeten di bidangnya. Narasumber pertama adalah Jumrah, M.Pd, seorang dosen PIAUD dari UIN Mataram, yang membahas berbagai pendekatan dan teknik dalam mengajarkan bahasa Inggris kepada anak usia dini dengan cara yang menyenangkan dan efektif.\n\nSebagai keynote speaker, acara ini juga menghadirkan Dekan Fakultas Tarbiyah IIM Surakarta, Dra. Hj. Nur Hidayah, M.Si, yang menyampaikan pentingnya peran bahasa asing dalam perkembangan kognitif dan sosial anak, serta bagaimana pendidikan bahasa Inggris dapat mendukung kemampuan komunikasi mereka di masa depan.\n\nNarasumber kedua adalah Roihatul Firdaus, M.Hum, dosen Prodi Pendidikan Anak Usia Dini IIM Surakarta, yang memberikan materi terkait dengan strategi dan metode pembelajaran bahasa Inggris yang sesuai dengan karakteristik anak usia dini, serta pentingnya integrasi bahasa Inggris dalam kehidupan sehari-hari anak.\n\nMelalui kegiatan ini, Prodi PIAUD IIM Surakarta berharap mahasiswa dapat memahami dan mempraktikkan berbagai metode pengajaran bahasa Inggris yang efektif untuk anak usia dini, serta dapat menerapkan ilmu yang diperoleh untuk mendukung perkembangan bahasa anak secara optimal.\n\nDengan penyelenggaraan acara seperti ini, diharapkan dapat memperkuat komitmen Prodi PIAUD IIM Surakarta dalam menciptakan tenaga pendidik yang kompeten dan siap menghadapi tantangan pendidikan di era global.', '/api/v1/media/466e5634-b895-4351-b9a2-3f918629bdc4', 1, 0, '2026-11-24 03:24:43', '2026-11-24 03:24:43'),
(11, 'Visiting Lecture Mata Kuliah Perkembangan Bahasa dan Literasi Anak Usia', '14 Juni 2024', '16.00 WIB', 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mambaul Ulum Surakarta (IIM Surakarta) kembali mengadakan Visiting Lecture secara daring dalam mata kuliah Perkembangan Bahasa...', 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mambaul Ulum Surakarta (IIM Surakarta) kembali mengadakan Visiting Lecture secara daring dalam mata kuliah Perkembangan Bahasa dan Literasi Anak Usia Dini. Acara ini diselenggarakan pada tanggal 14 Juni 2024 dan bertujuan untuk memberikan wawasan mendalam kepada mahasiswa mengenai pentingnya perkembangan bahasa dan literasi sejak usia dini dalam pembentukan keterampilan anak.\n\nAcara ini menghadirkan narasumber yang ahli di bidangnya. Narasumber pertama adalah Nur Hafidz, M.Pd, dosen PIAUD dari UNU Purwokerto, yang membahas berbagai aspek perkembangan bahasa anak usia dini, serta strategi dan pendekatan yang tepat untuk merangsang kemampuan bahasa anak secara efektif.\n\nSebagai keynote speaker, acara ini juga menghadirkan Dekan Fakultas Tarbiyah IIM Surakarta, Dra. Hj. Nur Hidayah, M.Si, yang memberikan pemaparan mengenai pentingnya literasi dalam pendidikan anak usia dini, serta bagaimana perkembangan bahasa menjadi landasan utama dalam pengembangan keterampilan lainnya.\n\nNarasumber kedua adalah Anita Wardani, M.Pd, dosen mata kuliah Perkembangan Bahasa dan Literasi Anak Usia Dini Prodi Pendidikan Anak Usia Dini IIM Surakarta. Beliau membagikan pengetahuan tentang teknik dan metode pengajaran yang dapat digunakan untuk meningkatkan keterampilan literasi anak, serta pentingnya peran orang tua dan pendidik dalam mendukung perkembangan bahasa anak sejak dini.\n\nKegiatan ini diharapkan dapat memperkaya pengetahuan mahasiswa dalam memahami dan mengimplementasikan berbagai strategi pembelajaran yang mendukung perkembangan bahasa dan literasi anak usia dini, serta memperkuat peran pendidik dalam mempersiapkan anak untuk masa depan yang lebih baik.\n\nDengan diselenggarakannya acara seperti ini, Prodi PIAUD IIM Surakarta terus berkomitmen untuk menghasilkan tenaga pendidik yang berkualitas dan mampu menghadapi tantangan pendidikan di era global, khususnya dalam mendukung perkembangan bahasa dan literasi anak sejak usia dini.', '/api/v1/media/f8a0b67d-f744-43a2-a89d-6d7503c9a719', 1, 0, '2026-11-24 03:27:31', '2026-11-24 03:27:39'),
(12, 'Lomba Alat Peraga Edukatif (APE) PIAUD IIM Surakarta', '29 Agustus 2024', NULL, 'Lomba Alat Peraga Edukatif Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) di Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta telah sukses diselenggarakan pada tanggal 29 Agustus 2024....', 'Lomba Alat Peraga Edukatif Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) di Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta telah sukses diselenggarakan pada tanggal 29 Agustus 2024. Kegiatan ini merupakan bagian dari proses seleksi Penerimaan Mahasiswa Baru untuk prodi PIAUD dan diadakan di bawah naungan Wakil Rektor 3.\n\nKegiatan ini mendapat pendampingan dari struktural Prodi PIAUD, yaitu Ibu Elina Intan Apriliani, S.Pd., M.Pd., Annafi’ Nurul ‘Ilmi Azizah, S.Pd., M.Pd., dan Anita Wardani, S.Pd., M.Pd. Acara dibuka oleh Bapak Mukhlis Fathurrohman, S.Ag., MSI., selaku Wakil Rektor 3, dan mendapat sambutan hangat dari Ibu Dra. Hj. Nur Hidayah, MSI., Dekan Fakultas Tarbiyah.\n\nPada acara lomba ini kami melibatkan para juri dari pihak luar yaitu Ibu Swantyka Ilham Prahesti, M.Pd. (Kaprodi PIAUD UNW), Fitria Maharani, M.Pd. (Dosen PAUD UNIVET Bantara Sukoharjo), dan Nur’aini Rahayu, S.Pd.I., M.Pd. (Assesor PAUD). Lomba ini bertujuan untuk memfasilitasi kreativitas dan inovasi dalam pengembangan alat peraga edukatif untuk pendidikan anak usia dini. Proses acara berjalan dengan lancar dari pembuatan alat peraga sampai dengan presentasi alat peraga yang dihasilkan oleh para anggota kelompok dan tentu para pemenang lomba mendapatkan penghargaan berupa thropy, sertifikat, dana pembinaan, serta subsidi biaya semester bagi pendaftar Prodi PIAUD.', '/api/v1/media/bbf8b257-c3b0-4b71-be94-a65b269e1bc4', 1, 0, '2026-11-24 03:30:52', '2026-11-24 03:30:52'),
(13, 'Visiting Lecture : Pendidikan Karakter Anak Usia Dini', '29 November 2024', '13.00 WIB', 'Institut Islam Mambaul Ulum Surakarta sukses mengadakan acara visiting lecture bertema “Pendidikan Karakter Anak Usia Dini” secara daring. Kegiatan ini merupakan bagian dari upaya institusi untuk...', 'Institut Islam Mambaul Ulum Surakarta sukses mengadakan acara visiting lecture bertema “Pendidikan Karakter Anak Usia Dini” secara daring. Kegiatan ini merupakan bagian dari upaya institusi untuk memperkuat wawasan akademik mahasiswa, khususnya pada mata kuliah pendidikan karakter anak usia dini.\n\nAcara yang diadakan pada Jumat, 29 November 2024 ini menghadirkan tiga tokoh ahli sebagai pembicara. Narasumber pertama, Mimit Pakasi, SH., S.Psi., M.Psi., memberikan wawasan mendalam mengenai pendekatan psikologi dalam membentuk karakter anak usia dini. Narasumber kedua, Elina Intan Apriliani, S.Pd., M.Pd., membahas strategi pembelajaran berbasis karakter yang efektif untuk diterapkan di lingkungan pendidikan.\n\nSebagai pembuka acara, Dr. Muhammad Jafar Nashir, M.Ag., selaku keynote speaker, memberikan pandangan strategis mengenai pentingnya pendidikan karakter dalam membangun generasi unggul yang berlandaskan nilai-nilai Islam. Dalam sambutannya, beliau menekankan bahwa pendidikan karakter anak usia dini adalah fondasi penting untuk membentuk kepribadian yang kuat dan bermoral di masa depan.\n\nKegiatan ini diikuti oleh ratusan peserta, termasuk mahasiswa, dosen, dan praktisi pendidikan dari berbagai daerah. Melalui diskusi interaktif, peserta mendapatkan wawasan baru tentang cara mengintegrasikan nilai-nilai moral dan etika dalam pendidikan anak usia dini, terutama di era digital saat ini.\n\nPihak Institut Islam Mambaul Ulum Surakarta berharap bahwa acara ini dapat memberikan kontribusi nyata dalam peningkatan kualitas pendidikan, khususnya dalam pembentukan karakter anak usia dini. “Kami berharap mahasiswa dapat menerapkan ilmu yang mereka peroleh untuk menjadi pendidik yang inspiratif dan inovatif,” ujar salah satu panitia.\n\nAcara visiting lecture ini merupakan bagian dari rangkaian program akademik unggulan yang terus diupayakan oleh Institut Islam Mambaul Ulum Surakarta untuk mendukung perkembangan pendidikan nasional.', '/api/v1/media/9e00bcee-3d42-4165-826e-414e863fdac4', 1, 0, '2026-11-24 03:33:18', '2026-11-24 03:33:18'),
(14, 'Visiting Lecture  Mata Kuliah Kesehatan dan Gizi Anak Usia Dini', '30 November 2024', '16.00 WIB', 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mambaul Ulum Surakarta (IIM Surakarta) menyelenggarakan Visiting Lecture secara daring dalam mata kuliah Kesehatan dan Gizi...', 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mambaul Ulum Surakarta (IIM Surakarta) menyelenggarakan Visiting Lecture secara daring dalam mata kuliah Kesehatan dan Gizi Anak Usia Dini pada tanggal 30 November 2024. Acara ini bertujuan untuk memberikan wawasan kepada mahasiswa mengenai pentingnya perhatian terhadap aspek kesehatan dan gizi dalam perkembangan anak usia dini.\n\nAcara ini menghadirkan narasumber yang sangat berkompeten di bidangnya. Narasumber pertama adalah Apt. Aruny Amali Syahida, M.Pd., M.Psi, Kepala Sekolah RA Al Amin Karanganyar, yang membahas peran penting kesehatan dan gizi dalam mendukung tumbuh kembang anak, serta memberikan pemahaman tentang pola makan yang sehat dan pentingnya gizi yang seimbang bagi anak usia dini.\n\nSebagai keynote speaker, Dekan Fakultas Tarbiyah IIM Surakarta, Dra. Hj. Nur Hidayah, M.Si, memberikan pemaparan mengenai keterkaitan antara kesehatan, gizi, dan perkembangan anak usia dini, serta bagaimana para pendidik dan orang tua dapat berperan dalam menjaga kesehatan dan memberikan asupan gizi yang optimal bagi anak.\n\nNarasumber kedua adalah Annafi’ Nurul ‘Ilmi Azizah, dosen Prodi Pendidikan Anak Usia Dini IIM Surakarta, yang berbagi pengetahuan mengenai pentingnya pendidikan gizi dalam kurikulum pendidikan anak usia dini dan bagaimana cara mengedukasi anak-anak tentang pola hidup sehat sejak usia dini.\n\nMelalui kegiatan ini, Prodi PIAUD IIM Surakarta berharap mahasiswa dapat memahami dengan lebih mendalam pentingnya kesehatan dan gizi dalam perkembangan anak usia dini, serta dapat menerapkan ilmu yang diperoleh untuk mendukung kesejahteraan anak-anak di lingkungan mereka.\n\nDengan diselenggarakannya kegiatan seperti ini, Prodi PIAUD IIM Surakarta berkomitmen untuk terus memberikan kontribusi positif dalam pengembangan pendidikan anak usia dini yang berkualitas, serta mempersiapkan tenaga pendidik yang siap mengatasi tantangan di dunia pendidikan.', '/api/v1/media/b63277c6-65f4-4646-8cf7-e1c88289b86a', 1, 0, '2026-11-24 03:34:02', '2026-11-24 03:34:02'),
(15, 'Praktisi Tamu Mata Kuliah Seni Budaya & Prakarya', '16 April 2025', '13.00 WIB', 'Program Studi Pendidikan Guru Madrasah Ibtidaiyah (PGMI) IIM Surakarta menyelenggarakan kegiatan praktisi tamu dalam mata kuliah Seni Budaya dan Prakarya yang diampu oleh Alfian Eko R, M.Pd.I,...', 'Program Studi Pendidikan Guru Madrasah Ibtidaiyah (PGMI) IIM Surakarta menyelenggarakan kegiatan praktisi tamu dalam mata kuliah Seni Budaya dan Prakarya yang diampu oleh Alfian Eko R, M.Pd.I, CETP. Kegiatan ini menghadirkan Santo Setiawan, seorang pianis tuna netra yang telah berpengalaman dalam dunia musik Islami, sebagai narasumber utama. Bertempat di Laboratorium Audio IIM Surakarta, acara berlangsung pada pukul 13.00 hingga 14.30 WIB dan diikuti oleh seluruh mahasiswa IIM Surakarta lintas program studi.\n\nDalam sesi ini, Santo membawakan materi mengenai karakter suara dalam tangga nada serta praktik menyanyikan lagu-lagu Islami bersama. Materi yang disampaikan relevan dengan kajian seni musik yang bernuansa keislaman dan disesuaikan dengan karakteristik serta perkembangan anak Madrasah Ibtidaiyah (MI). Mahasiswa diajak untuk mengenali struktur dasar melodi yang sederhana, memahami unsur-unsur musikal dalam lagu-lagu Islami, serta membangun kreativitas dalam menyampaikan pesan-pesan moral dan spiritual melalui seni suara. Kegiatan ini tidak hanya memperkaya wawasan akademik mahasiswa, tetapi juga memberikan inspirasi nyata tentang semangat berkarya di tengah keterbatasan fisik, sebagaimana ditunjukkan oleh narasumber.\n\nSesi ini berlangsung interaktif dan penuh antusiasme. Mahasiswa tampak aktif bertanya dan berdiskusi mengenai cara menyusun pembelajaran seni musik di tingkat MI, termasuk strategi memilih lagu Islami yang edukatif dan sesuai usia. Praktik menyanyi bersama diiringi piano menjadi momen yang memperkuat pemahaman mahasiswa terhadap aplikasi langsung materi perkuliahan dalam konteks pendidikan dasar.\n\nKegiatan ini merupakan bagian dari upaya IIM Surakarta dalam menjembatani teori dan praktik melalui kolaborasi dengan para praktisi lapangan. Dengan menghadirkan sosok inspiratif seperti Santo Setiawan, mahasiswa diharapkan tidak hanya memahami aspek teknis seni musik, tetapi juga memiliki perspektif inklusif dan apresiatif terhadap keberagaman potensi manusia dalam dunia pendidikan dan seni.', '/api/v1/media/1e5e7e19-a083-4132-ab57-4be57a62f131', 1, 0, '2026-11-24 03:35:04', '2026-11-24 03:35:04'),
(16, 'Visiting Lecture Mata Kuliah Perencanaan Pembelajaran PAUD', '5 Mei 2025', '14.30 WIB', 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mamba’ul ‘Ulum Surakarta (IIM Surakarta) menyelenggarakan kegiatan Dosen Tamu dalam rangka penguatan materi pada mata kuliah...', 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mamba’ul ‘Ulum Surakarta (IIM Surakarta) menyelenggarakan kegiatan Dosen Tamu dalam rangka penguatan materi pada mata kuliah Perencanaan Pembelajaran PAUD. Kegiatan ini menghadirkan narasumber Issaura Dwi Selvi, M.Pd., Dosen PIAUD STAIN Sultan Abdurrahman Kepulauan Riau, yang mengangkat tema menarik dan relevan, yaitu “Perencanaan Pembelajaran PAUD Berbasis Kurikulum Merdeka dan Montessori.”\n\nDekan Tarbiyah IIM Surakarta, Dr. H. Muhammad Ja’far Nashir, S.Ag., M.Ag., membuka acara dan menyampaikan apresiasi kepada pemateri atas kontribusinya, serta kepada mahasiswa yang mengikuti kegiatan dengan penuh semangat. “Kegiatan dosen tamu ini merupakan bentuk sinergi antara dunia akademik, yang sangat penting untuk membekali mahasiswa sebagai calon pendidik PAUD yang profesional dan adaptif terhadap kebijakan pendidikan nasional,” ujarnya.\n\nAcara yang diikuti oleh seluruh mahasiswa PIAUD IIM Surakarta ini diselenggarakan secara online melalui Zoom Meeting. Kegiatan ini bertujuan untuk memberikan pemahaman lebih dalam mengenai perencanaan pembelajaran PAUD yang kontekstual dan adaptif terhadap perkembangan zaman, khususnya penerapan Kurikulum Merdeka yang saat ini menjadi acuan utama pendidikan nasional.\n\nDalam pemaparannya, Issaura Dwi Selvi, M.Pd. menyampaikan bahwa Kurikulum Merdeka dan pendekatan Montessori memiliki benang merah yang sama, yaitu memberikan ruang seluas-luasnya kepada anak untuk tumbuh sesuai dengan kodrat dan tahap perkembangannya. Ia menekankan pentingnya kebebasan belajar, lingkungan yang mendukung eksplorasi, serta peran guru sebagai fasilitator yang memahami karakteristik anak usia dini.\n\n“Montessori bukan hanya soal alat peraga, tapi filosofi mendalam tentang bagaimana anak belajar secara alami. Ketika digabungkan dengan prinsip Kurikulum Merdeka, akan tercipta pembelajaran yang lebih bermakna dan berpihak pada anak,” tutur beliau dalam sesi diskusi.\n\nPara mahasiswa tampak antusias dan aktif terlibat dalam diskusi, dan tanya jawab. Salah satu mahasiswa, Astutik, bertanya kepada pembicara contoh kegiatan montessory untuk anak usia 3-4 tahun. Selain itu, Sulastri menanyakan tentang penilaian yang bisa digunakan. Kegiatan ini juga menjadi ajang untuk memperluas wawasan mahasiswa terhadap praktik pembelajaran PAUD yang inovatif dan aplikatif di lapangan.\n\n“Melalui kegiatan ini, diharapkan mahasiswa PIAUD IIM Surakarta semakin memahami pentingnya perencanaan pembelajaran yang holistik, fleksibel, dan sesuai dengan kebutuhan serta potensi anak usia dini dalam semangat Merdeka Belajar” ujar Annafi’ Nurul ‘Ilmi Azizah, M.Pd. Dosen Perencanaan Pembelajaran PAUD.', '/api/v1/media/d3cebf87-c9d8-4a06-be6c-5aeaa4fa257a', 1, 0, '2026-11-24 03:35:55', '2026-11-24 03:35:55'),
(17, 'Visiting Lecture  Mata Kuliah Pengembangan Alat Permainan Edukatif (APE) AUD  : Keamanan dan Keselamatan dalam Penggunaan APE pada Anak Usia Dini', '7 Mei 2025', '12.30 WIB', 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta menyelenggarakan kegiatan kuliah tamu bersama dengan Prodi PIAUD Sekolah Tinggi Agama Islam...', 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta menyelenggarakan kegiatan kuliah tamu bersama dengan Prodi PIAUD Sekolah Tinggi Agama Islam Miftahul Ulum (STAIM) Magetan. Kegiatan ini merupakan bagian dari perkuliahan mata kuliah Pengembangan Alat Permainan Edukatif (APE) AUD yang mengangkat tema “Keamanan dan Keselamatan dalam Penggunaan APE pada Anak Usia Dini.”\n\nKuliah tamu yang berlangsung pada Rabu, 7 Mei 2025 ini menghadirkan akademisi dan praktisi pendidikan anak usia dini yang kompeten di bidangnya. Bertindak sebagai Keynote Speaker, Dr. Muhammad Ja’far Nashir, M.Ag., menyampaikan pentingnya pemahaman komprehensif tentang aspek keamanan dan keselamatan dalam penyediaan serta pemanfaatan APE di lingkungan PAUD.\n\nKegiatan ini juga menghadirkan dua narasumber utama, yakni Juli Rohmat, M.Pd., yang membahas strategi pemilihan APE yang aman dan sesuai dengan tahap perkembangan anak, serta Anita Wardani, M.Pd., yang mengulas prosedur keselamatan dalam penggunaan APE di dalam dan luar kelas.\n\nKaprodi PIAUD IIM Surakarta dalam sambutannya menyampaikan bahwa kolaborasi ini bertujuan memperluas wawasan mahasiswa tentang penerapan praktis dan teoretis APE yang ramah anak, sekaligus memperkuat jejaring antarperguruan tinggi. “Kami berharap kegiatan ini mampu memberikan kontribusi nyata dalam pengembangan kompetensi calon pendidik PAUD, terutama dalam hal menciptakan lingkungan bermain yang aman dan mendidik,” ujarnya.\n\nKegiatan berlangsung interaktif dan mendapatkan antusiasme tinggi dari mahasiswa kedua institusi. Kuliah tamu ini sekaligus menjadi sarana berbagi pengalaman antarprodi dalam mengembangkan kualitas pendidikan anak usia dini di Indonesia.', '/api/v1/media/1499e338-67d3-4c98-8946-abe9c826551a', 1, 0, '2026-11-24 03:37:50', '2026-11-24 03:37:50'),
(18, 'Visiting Lecture : Kupas Pembelajaran Seni Tari untuk Anak Usia Dini', '20 Mei 2025', '14.30 WIB', 'Fakultas Tarbiyah Prodi Pendidikan Islam Aanak Usia Dini mengundang Anda untuk bergabung ke rapat Zoom yang terjadwal. Topik: Dosen Tamu Mata Kuliah Pendidikan Seni dengan tema Pembelajaran Seni...', 'Fakultas Tarbiyah Prodi Pendidikan Islam Aanak Usia Dini mengundang Anda untuk bergabung ke rapat Zoom yang terjadwal.\n\nTopik: Dosen Tamu Mata Kuliah Pendidikan Seni dengan tema Pembelajaran Seni Tari Anak Usia Dini.\n\nKeynote speaker:\nDr. HMJ Nashir, S.Ag., M.Ag\n(Dekan Fakultas Tarbiyah)\nPemateri:\nAyu Vinlandari Wahyudi, M.Pd\n(Dosen PIAUD UIN Siber Syekh Nurjati Cirebon)\nPemateri:\nElina Intan Apriliani, M.Pd\n(Dosen Prodi PIAUD IIM Surakarta)\n\nWaktu: 20 Mei 2025 02:00 PM Jakarta\nBergabung ke Rapat Zoom\nhttps://us06web.zoom.us/j/85130645925?pwd=8mOig2EibcQvMIBsBrAk8BFuiIcstL.1\n\nID Rapat: 851 3064 5925\nKode Sandi: 860076', '/api/v1/media/907952b6-447f-46d9-a06f-18aa56ed8359', 1, 0, '2026-11-24 03:39:48', '2026-11-24 03:39:48'),
(19, 'Visiting Lecture : Administrasi Pendidikan dalam Praktiknya di Sekolah', '18 Juni 2025', '13.00 WIB', 'Dalam rangka memperkuat kompetensi mahasiswa di bidang administrasi pendidikan, Program Studi Pendidikan Agama Islam (PAI), Fakultas Tarbiyah, Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta...', 'Dalam rangka memperkuat kompetensi mahasiswa di bidang administrasi pendidikan, Program Studi Pendidikan Agama Islam (PAI), Fakultas Tarbiyah, Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta menyelenggarakan kegiatan Kuliah Tamu bertema “Administrasi Pendidikan dalam Praktiknya di Sekolah” pada Rabu, 18 Juni 2025 secara daring melalui Zoom Meeting.\n\nKegiatan ini menghadirkan narasumber istimewa, Prof. Dr. Muh. Hizbul Muflihin, M.Pd., Guru Besar Bidang Administrasi Pendidikan dari UIN SAIZU Purwokerto, yang telah lama dikenal sebagai akademisi sekaligus praktisi pendidikan dengan pengalaman luas dalam pengelolaan institusi pendidikan.\n\nDidampingi oleh dosen pengampu mata kuliah, Septian Nur Ika Trisnawati, M.Pd., CLSP, kuliah tamu ini diikuti oleh mahasiswa Prodi PAI semester akhir yang sedang menempuh mata kuliah Administrasi Pendidikan. Kegiatan berlangsung pukul 13.00 hingga 14.30 WIB, dan diikuti dengan antusias oleh peserta.\n\nDalam sesi penyampaian materi, Prof. Hizbul Muflihin mengulas secara mendalam berbagai aspek penting administrasi pendidikan yang aplikatif, di antaranya:\nPerencanaan dan pengelolaan kurikulum tahunan dan semester, Administrasi kesiswaan, keuangan, sarana prasarana, dan personalia, Pendekatan manajerial dalam mencapai tujuan pendidikan, Peran kepala sekolah dan dinamika kepemimpinan di sekolah, Sistem administrasi konseling siswa dan layanan pendukung lainnya.\n\nBeliau juga menegaskan bahwa keberhasilan penyelenggaraan pendidikan tidak hanya ditentukan oleh aspek pengajaran, namun juga oleh sistem administrasi yang terstruktur, efisien, dan partisipatif.\n\nMenurut Septian Nur Ika Trisnawati, kuliah tamu ini menjadi sarana strategis dalam menjembatani teori dan praktik bagi mahasiswa. “Mahasiswa tidak hanya belajar dari buku atau perkuliahan, tetapi juga menyerap pengalaman nyata dari narasumber yang kompeten di lapangan,” ujarnya.\n\nKegiatan ini diharapkan menjadi bekal berharga bagi mahasiswa dalam memahami dunia kerja pendidikan, khususnya bagi mereka yang kelak akan menjadi pendidik atau tenaga kependidikan profesional.\n\nDengan terselenggaranya kuliah tamu ini, IIM Surakarta menegaskan komitmennya dalam memberikan pendidikan yang tidak hanya teoritis, tetapi juga kontekstual dan aplikatif, guna mencetak lulusan yang adaptif terhadap dinamika pendidikan abad ke-21.', '/api/v1/media/7acc6e6a-31f0-4868-9cd8-99e809acbdda', 1, 0, '2026-11-24 03:40:59', '2026-11-24 03:41:24'),
(20, 'Visiting Lecture : Dari Kaidah ke Tadabbur, Menemukan Rasa Bahasa Al-Quran', '24 Oktober 2025', '08.00 WIB', 'Sebanyak kurang lebih 70 mahasiswa antusias mengikuti kuliah tamu dengan tema “Dari Kaidah ke Tadabbur, Menemukan Rasa Bahasa Al-Quran” yang diselenggarakan oleh Jurusan Pendidikan Agama Islam...', 'Sebanyak kurang lebih 70 mahasiswa antusias mengikuti kuliah tamu dengan tema “Dari Kaidah ke Tadabbur, Menemukan Rasa Bahasa Al-Quran” yang diselenggarakan oleh Jurusan Pendidikan Agama Islam (PAI) Fakultas Tarbiyah, Institut Islam Mambaul Ulum Surakarta (IIM Surakarta) pada Sabtu (25/10/2025). Kegiatan ini merupakan sesi kuliah tamu untuk mata kuliah Qawaid Al-Lughah Al-Arabiyyah (Kaidah-Kaidah Bahasa Arab) yang diampu oleh Andita Aprilia Fridayanti, M.Pd dosen Bahasa Arab IIM surakarta. Acara ini bertujuan untuk mentransformasikan pemahaman mahasiswa dari sekadar menguasai kaidah gramatikal bahasa Arab (nahwu-sharaf) menuju kemampuan untuk menangkap keindahan makna dan “rasa bahasa” yang terkandung dalam Al-Quran melalui pendekatan tadabbur (perenungan mendalam). Kuliah tamu ini menghadirkan Fajar Hidayat, M.Pd., selaku Kaprodi Pendidikan Bahasa Arab STIQ Isy Karima Karanganyar, sebagai pemateri tunggal. Acara yang diampu oleh dosen pengampu mata kuliah Qawaid Al-Lughah Al-Arabiyyah ini berhasil menarik minat besar dari para mahasiswa.\n\nKegiatan berlangsung pada hari Sabtu, 25 Oktober 2025, pukul 08.00 hingga 10.00 WIB, dilaksanakan secara online. Tema yang diangkat untuk menjawab tantangan pembelajaran bahasa Arab yang sering kali hanya berfokus pada aspek teknis kaidah, namun belum menyentuh pada aspek apresiasi terhadap keagungan bahasa Al-Quran. Penguasaan kaidah seharusnya menjadi kunci untuk membuka makna dan pesan moral dalam ayat-ayat Al-Qur’an,” ujar Fajar Hidayat dalam pemaparannya. Beliau juga mencontohkan secara interaktif bagaimana satu kaidah dapat mengungkap keindahan makna ayat.\n\nDalam pemaparannya, Fajar Hidayat, M.Pd., mendemonstrasikan secara langsung bagaimana sebuah kaidah bahasa Arab yang dikuasai dapat menjadi “kunci” untuk membuka kedalaman makna dan pesan moral dalam sebuah ayat Al-Quran. Melalui contoh-contoh praktis, ia mengajak mahasiswa untuk tidak berhenti pada terjemahan harfiah, tetapi melangkah lebih jauh kepada tahap perenungan (tadabbur) yang akan memperkaya spiritualitas dan pemahaman keagamaan. Kegiatan yang diikuti oleh sekitar 70 mahasiswa dari Institut Islam Mambaul Ulum Surakarta dan STIQ Isy Karima ini berjalan dengan lancar dan dinamis, ditandai dengan sesi tanya jawab yang aktif. Acara ini diharapkan dapat menjadi inspirasi bagi pengembangan metode pembelajaran bahasa Arab, khususnya yang berbasis pada teks Al-Quran, di kedua institusi tersebut.', '/api/v1/media/42c99169-5216-4cc4-a173-5c8592469d51', 1, 0, '2026-11-24 03:53:48', '2026-11-24 03:53:48');
INSERT INTO `agendas` (`id`, `title`, `event_date`, `event_time`, `excerpt`, `description`, `cover_url`, `is_visible`, `sort_order`, `created_at`, `updated_at`) VALUES
(21, 'Seminar Nasional : Penguatan Perencanaan Pendidikan untuk Mewujudkan Sekolah Unggul dan Berdaya Saing', '6 Desember 2025', '13.00 WIB', 'Institut Islam Mambaul Ulum Surakarta (IIM Surakarta) kembali menunjukkan komitmennya dalam peningkatan mutu pendidikan melalui Seminar Nasional Pendidikan Agama Islam (PAI), yang digelar pada...', 'Institut Islam Mambaul Ulum Surakarta (IIM Surakarta) kembali menunjukkan komitmennya dalam peningkatan mutu pendidikan melalui Seminar Nasional Pendidikan Agama Islam (PAI), yang digelar pada Jumat, 5 Desember 2025, secara daring melalui Zoom Meeting. Kegiatan ini mengangkat tema “Penguatan Perencanaan Pendidikan untuk Mewujudkan Sekolah Unggul dan Berdaya Saing”, yang relevan dengan kebutuhan sekolah di era modern.\n\nSeminar menghadirkan narasumber berkompeten dari berbagai perguruan tinggi, antara lain: Prof. Dr. M. Hizbul Muflihin, M.Pd. (UIN Prof. KH. Saifuddin Zuhri Purwokerto), Dr. H. Ja’far Nashir, M.Ag. (IIM Surakarta), dan Nurus Amzana, M.Pd.I. (UIN Al-Azhaar Lubuklinggau). Kegiatan ini dimoderatori oleh Septian Nur Ika Trisnawati, M.Pd. dari IIM Surakarta.\n\nAcara dimulai dengan pemaparan mendalam oleh Dr. Ja’far Nashir, yang menekankan pentingnya landasan filosofis dan urgensi perencanaan pendidikan sebagai fondasi utama dalam membangun sekolah berbasis mutu. Dalam paparannya, Dr. Ja’far menyoroti bahwa perencanaan pendidikan tidak sekadar menyusun program dan target, tetapi juga membentuk budaya akademik yang konsisten, mengarahkan seluruh pemangku kepentingan, dan memastikan kualitas pembelajaran yang berkelanjutan.\n\nSelanjutnya, Nurus Amzana menghadirkan perspektif praktis melalui materi tentang analisis internal dan eksternal sekolah. Ia menjelaskan bagaimana identifikasi kekuatan, kelemahan, peluang, dan ancaman (SWOT) menjadi dasar dalam menyusun dokumen strategis sekolah yang realistis dan responsif terhadap perubahan lingkungan pendidikan. Peserta diberikan contoh konkret bagaimana analisis tersebut dapat diterjemahkan menjadi langkah-langkah strategis yang meningkatkan mutu sekolah, baik dari sisi manajemen, kurikulum, maupun pengembangan sumber daya manusia.\n\nMateri terakhir disampaikan oleh Prof. M. Hizbul Muflihin, yang memandu peserta memahami konsep perancangan dokumen strategis sekolah secara komprehensif. Ia membahas secara rinci penyusunan visi, misi, strategi, tujuan, hingga indikator mutu yang terukur. Dengan pendekatan ini, peserta tidak hanya memperoleh pemahaman teoritis, tetapi juga panduan praktis untuk implementasi di sekolah masing-masing, sehingga setiap dokumen strategis dapat menjadi alat yang efektif dalam perencanaan, pengawasan, dan evaluasi mutu pendidikan.\n\nSeminar ini diikuti oleh mahasiswa dan masyarakat umum yang antusias untuk memperluas wawasan tentang manajemen pendidikan yang efektif dan berdaya saing. Kegiatan ini tidak hanya menekankan teori, tetapi juga memberikan contoh nyata strategi perencanaan sekolah unggul, sehingga dapat langsung diterapkan dalam praktik pendidikan sehari-hari.\n\nMelalui kegiatan ini, IIM Surakarta menegaskan perannya sebagai pusat pengembangan pendidikan yang mampu mempersiapkan tenaga pendidik dan mahasiswa untuk menghadapi tantangan sekolah masa depan dengan inovatif, profesional, dan berbasis mutu.', '/api/v1/media/6f31379f-55f6-43d5-a62f-5e930c70ff93', 1, 0, '2026-11-24 03:57:45', '2026-11-24 03:57:45'),
(22, 'Guest Lecture : Relasi & Fungsi: Konsep Dasar Matematika Bagi Calon Guru MI/SD', '3 Juni 2026', '14.30 WIB', 'Guna mempertegas kesiapan akademis mahasiswa dalam menguasai bidang eksakta, Program Studi Pendidikan Guru Madrasah Ibtidaiyah (PGMI) Faculty of Tarbiyah Institut Islam Mamba’ul Ulum Surakarta...', 'Guna mempertegas kesiapan akademis mahasiswa dalam menguasai bidang eksakta, Program Studi Pendidikan Guru Madrasah Ibtidaiyah (PGMI) Faculty of Tarbiyah Institut Islam Mamba’ul Ulum Surakarta sukses menggelar agenda Guest Lecture (Kuliah Tamu). Kegiatan perkuliahan khusus untuk mata kuliah Konsep Dasar Matematika MI/SD ini dilaksanakan secara daring dan diikuti dengan sangat antusias oleh 98 mahasiswa peserta.\n\nKuliah tamu ini diselenggarakan dengan mengangkat tema krusial, yaitu “Relasi & Fungsi: Konsep Dasar Matematika Bagi Calon Guru MI/SD”. Pemilihan topik ini dilatarbelakapi oleh pentingnya penguasaan materi abstrak seperti relasi dan fungsi agar dapat diajarkan secara sederhana, konkret, dan menyenangkan oleh para calon guru kepada anak-anak usia dasar di madrasah atau sekolah.\n\nUntuk membedah konsep tersebut secara mendalam, panitia menghadirkan dosen pakar eksternal, Arini Ulfah Hidayati, M.Pd., akademisi terkemuka dari STIT Bustanul ‘Ulum Lampung Tengah, sebagai narasumber utama. Kehadiran pemateri lintas pulau ini memberikan perspektif baru yang segar bagi para mahasiswa dalam memahami strategi penyampaian materi matematika.\n\nKegiatan perkuliahan daring ini dilangsungkan melalui platform Zoom Meeting Online dimulai tepat pukul 14.30 WIB. Sebanyak 98 mahasiswa yang menjadi peserta masuk ke dalam ruang zoom.\n\nSelama jalannya acara, atmosfer akademik terasa sangat hidup. Setelah narasumber selesai memaparkan materi mengenai struktur relasi dan fungsi, kegiatan langsung dilanjutkan dengan sesi interaktif berupa tanya jawab dan pemecahan studi kasus bersama. Melalui pelaksanaan Guest Lecture ini, Prodi PGMI berharap dapat terus melahirkan generasi pendidik yang kompeten, cerdas, dan siap mengabdi demi kemajuan pendidikan dasar di Indonesia.', '/api/v1/media/b47b7f71-c5f7-445e-bc96-7336bdb03429', 1, 0, '2026-11-24 04:01:09', '2026-11-24 04:01:15'),
(23, 'Guest Lecture : Menyusun Rencana Manajemen Strategis Lembaga PAUD', '8 Juni 2026', '13.00 WIB', 'Suasana ruang Zoom Meeting pada Senin siang, 8 Juni 2026, terasa begitu hidup dan penuh semangat. Sebanyak 93 mahasiswa dari dua institusi Pendidikan ternama, Institut Islam Mambaul Ulum (IIM)...', 'Suasana ruang Zoom Meeting pada Senin siang, 8 Juni 2026, terasa begitu hidup dan penuh semangat. Sebanyak 93 mahasiswa dari dua institusi Pendidikan ternama, Institut Islam Mambaul Ulum (IIM) Surakarta dan STAI Al-Musaddadiyah Garut, berkumpul dalam satu wadah virtual untuk mengikuti kegiatan Kuliah Tamu yang sangat spesial.\n\nAcara yang diselenggarakan oleh Fakultas Tarbiyah ini mengangkat tema yang krusial bagi masa depan pendidikan anak usia dini, yakni “Menyusun Rencana Manajemen Strategis Lembaga PAUD”. Menghadirkan praktisi sekaligus akademisi berpengalaman, Siti Aliyah, M.Pd.I., kuliah tamu ini bukan sekadar pertemuan akademik biasa, melainkan ajang berbagi ilmu dan pengalaman yang sangat berharga.\n\nWajah Baru Manajemen Pendidikan Dalam pemaparannya, Siti Aliyah, M.Pd.I., menekankan pentingnya manajemen yang terukur bagi lembaga pendidikan. “PAUD bukan sekadar tempat bermain anak. Untuk menciptakan generasi emas, kita memerlukan visi yang tajam, manajemen yang rapi, dan strategi yang tepat sasaran,” ungkap Siti Aliyah di hadapan puluhan mahasiswa yang tampak antusias mengikuti jalannya materi. Beliau membedah langkah-langkah praktis dalam menyusun rencana strategis—mulai dari analisis SWOT sederhana hingga cara menetapkan tujuan jangka pendek dan panjang lembaga. Materi disampaikan dengan gaya yang ringan, santai, namun sarat makna, sehingga membuat materi yang terkesan ‘berat’ menjadi sangat mudah dipahami oleh mahasiswa.“Membangun lembaga PAUD yang unggul membutuhkan kombinasi antara niat yang tulus dan manajerial yang profesional. Itulah kunci sukses yang ingin kita tanamkan pada calon-calon pendidik masa depan,” tambahnya.\n\nSinergi Lintas Wilayah\n\nKehadiran 93 mahasiswa yang berasal dari latar belakang budaya berbeda, yakni Surakarta dan Garut, justru menjadi kekuatan tersendiri. Melalui forum ini, terjadi pertukaran gagasan mengenai tantangan mengelola PAUD di daerah masing-masing. Diskusi yang terbangun sangat dinamis, di mana mahasiswa tidak segan-segan bertanya\n\ntentang implementasi strategi yang efektif di lapangan. Salah satu mahasiswa peserta menyatakan kegembiraannya, “Kuliah tamu ini sangat membuka wawasan saya. Ternyata menyusun rencana strategis tidak serumit yang dibayangkan jika kita memahami langkah-langkah dasarnya. Terima kasih IIM Surakarta dan Ibu Siti Aliyah atas ilmunya!” Mengapa Ini Penting?\n\nKegiatan ini merupakan bagian dari komitmen IIM Surakarta dalam menciptakan ekosistem pembelajaran yang kolaboratif dan berskala luas. Dengan menggandeng STAI Al-Musaddadiyah Garut, diharapkan mahasiswa tidak hanya terpaku pada teori di bangku\n\nkuliah, tetapi juga mendapatkan perspektif nyata dari praktisi pendidikan di lapangan. Kuliah tamu ini ditutup dengan sesi tanya jawab yang cukup panjang, menandakan\n\nbesarnya rasa ingin tahu mahasiswa. Semangat “Bismillah Membangun Generasi Rahmatan Lil’alamin Menuju World Class Islamic Institut” menjadi spirit yang mendasari\n\nterselenggaranya kegiatan sukses ini. Bagi para mahasiswa yang belum sempat hadir, materi mengenai penyusunan rencana strategis ini diharapkan menjadi pijakan awal bagi mereka untuk terus mengasah kemampuan manajerial. Dengan bekal ilmu yang mumpuni, diharapkan lahir pemimpin- pemimpin lembaga PAUD yang mampu membawa perubahan positif bagi pendidikan anak usia dini di Indonesia.', '/api/v1/media/450a426d-f4e9-488b-88c9-e75a1fae120d', 1, 0, '2026-11-24 04:01:56', '2026-11-24 04:01:56'),
(24, 'Guest Lecture : Pendidikan Seni untuk Anak Usia Dini', '9 Juni 2026', '13.00 WIB', 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Fakultas Tarbiyah Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta sukses menyelenggarakan kegiatan Guest Lecture dengan tema “Pendidikan Seni...', 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Fakultas Tarbiyah Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta sukses menyelenggarakan kegiatan Guest Lecture dengan tema “Pendidikan Seni untuk Anak Usia Dini” pada Selasa, 9 Juni 2026. Kegiatan yang dilaksanakan secara daring melalui Zoom Meeting ini dimulai pukul 13.00 WIB dan diikuti oleh mahasiswa PIAUD serta peserta dari berbagai kalangan akademisi dan praktisi pendidikan anak usia dini.\n\nKegiatan dibuka dengan sambutan sekaligus opening speech oleh Elina Intan Apriliani, S.Pd., M.Pd., selaku dosen pengampu mata kuliah Pendidikan Seni. Dalam sambutannya, beliau menyampaikan bahwa pendidikan seni memiliki peran penting dalam mengoptimalkan perkembangan anak usia dini, terutama dalam aspek kreativitas, ekspresi diri, keterampilan motorik, sosial emosional, dan kemampuan berpikir kritis.\n\nSelanjutnya, Iffah Mukhlisah, M.Pd., selaku Ketua Program Studi PIAUD IIM Surakarta, hadir sebagai keynote speaker. Beliau menegaskan bahwa pembelajaran seni pada anak usia dini perlu dirancang secara menyenangkan, kontekstual, dan berpusat pada kebutuhan serta karakteristik perkembangan anak.\n\nSebagai narasumber utama, Marwah Triyati, M.Pd. dari IAI Rakeyan Santang Karawang memaparkan materi mengenai konsep, urgensi, serta implementasi pendidikan seni bagi anak usia dini. Dalam pemaparannya, beliau menjelaskan bahwa seni bukan sekadar aktivitas menggambar, bernyanyi, menari, atau bermain peran, tetapi merupakan media pembelajaran yang efektif untuk mengembangkan potensi anak secara holistik.\n\nBeliau juga menekankan pentingnya peran pendidik dalam menciptakan lingkungan belajar yang kreatif dan memberikan ruang bagi anak untuk bereksplorasi, berekspresi, serta mengembangkan imajinasi sesuai dengan tahap perkembangannya.\n\nKegiatan berlangsung interaktif dengan sesi tanya jawab yang diikuti secara antusias oleh para peserta. Berbagai pertanyaan dan diskusi mengenai strategi pembelajaran seni, pengembangan media kreatif, serta implementasi seni dalam kurikulum pendidikan anak usia dini menjadi bukti tingginya minat peserta terhadap tema yang diangkat.\n\nMelalui kegiatan Guest Lecture ini, Program Studi PIAUD Fakultas Tarbiyah IIM Surakarta berharap dapat memperluas wawasan dan meningkatkan kompetensi mahasiswa dalam memahami pentingnya pendidikan seni sebagai bagian integral dari pembelajaran anak usia dini.\n\nKegiatan ini juga menjadi salah satu bentuk komitmen Prodi PIAUD IIM Surakarta dalam menghadirkan pengalaman belajar yang inovatif dan kolaboratif melalui keterlibatan akademisi dan praktisi dari berbagai institusi.', '/api/v1/media/257ffc1d-6834-460a-9b4f-ef02294c7e39', 1, 0, '2026-11-24 04:02:35', '2026-11-24 04:02:35'),
(25, 'Transformasi Dunia Pendidikan Islam Di Tengah Pandemi Covid-19', '29 Juli 2020', '09.00 WIB', 'Narasumber: 1. Prof. Dr. Harun Joko Prasetyo, M.Pd (Guru Besar/ Dekan FKPI UMS) 2. Dr. H. Muh. Samsuri, M.Si ( Ketua PDM Karanganyar/ Praktisi Pendidikan Moderator: 1. Drs. H. Wiharso, M.M 2....', 'Narasumber:\n1. Prof. Dr. Harun Joko Prasetyo, M.Pd (Guru Besar/ Dekan FKPI UMS)\n2. Dr. H. Muh. Samsuri, M.Si ( Ketua PDM Karanganyar/ Praktisi Pendidikan\n\nModerator:\n1. Drs. H. Wiharso, M.M\n2. Lintang Seira Putri, S.Psi, M.A\n3. Dra. Alik Chusna, M.Pd', '/api/v1/media/f4dad535-e4db-431f-b904-7e6f0554816c', 1, 0, '2026-11-24 04:10:17', '2026-11-24 04:10:17'),
(26, 'Visiting Lecture : Pendekatan Pengajaran Adaptif dan Kolaboratif: Strategi Inovatif dalam Mempersiapkan Guru Masa Depan', '16 Oktober 2024', '10.00 WIB', 'kembali membuka peluang bagi mahasiswa untuk memperluas wawasan dengan menghadirkan kuliah tamu bertema “Pendekatan Pengajaran Adaptif dan Kolaboratif: Strategi Inovatif dalam Mempersiapkan Guru...', 'kembali membuka peluang bagi mahasiswa untuk memperluas wawasan dengan menghadirkan kuliah tamu bertema “Pendekatan Pengajaran Adaptif dan Kolaboratif: Strategi Inovatif dalam Mempersiapkan Guru Masa Depan”. \n\nKuliah tamu ini dilaksanakan pada Rabu (16/10/2024) di Ruang Zoom, disambut hangat oleh Kepala Prodi Pendidikan Guru Madrasah Ibtidaiyah Lailla Hidayatul Amin, S.Pd., M.Pd.I,, dengan menghadirkan pemateri Dr. Kharis Syuhud Mujahada, M.Pd dari Sekolah Tinggi Agama Islam Terpadu  (STAIT) Yogyakarta dan didampingi oleh Praptiningsih, M.Pd.I.sebagai dosen pengampu mata kuliah Strategi Belajar Mengajar di Prodi Pendidikan Guru Madrasah Ibtidaiyah IIM Surakarta.\n\nKuliah tamu dihadiri oleh mahasiswa Program Studi PGMI IIM Surakarta dan Sekolah Tinggi Agama Islam Terpadu (STAIT) Yogyakarta serta Mahasiswa diluar Program Studi PGMI IIM Surakarta.', '/api/v1/media/b6ac865b-dbdc-47b3-9a6b-4b39f0319b2e', 1, 0, '2026-11-24 06:32:31', '2026-11-24 06:32:31'),
(27, 'Visiting Lecture : Strategi Guru dalam Menyusun Bahan Ajar Bahasa Arab yang Ideal dan Sistematis untuk MI', '30 April 2025', '16.00 WIB', 'Fakultas Tarbiyah Program Studi Pendidikan Guru Madrasah Ibtidaiyah (PGMI) Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta sukses menggelar kegiatan Kuliah Dosen Tamu pada Rabu, 30 April 2025....', 'Fakultas Tarbiyah Program Studi Pendidikan Guru Madrasah Ibtidaiyah (PGMI) Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta sukses menggelar kegiatan Kuliah Dosen Tamu pada Rabu, 30 April 2025. Kegiatan ini mengangkat tema “Strategi Guru dalam Menyusun Bahan Ajar Bahasa Arab yang Ideal dan Sistematis untuk MI” dan berlangsung di Ruang 3.09, Kampus IIM Surakarta, mulai pukul 16.00 WIB hingga selesai.\n\nKuliah tamu ini menghadirkan dua narasumber berkompeten di bidangnya, yakni Lady Eka Rahmawati, Lc., M.Th.I, dosen dari STIM Surakarta, serta Dudi Budi Astoko, S.Pd.I., M.Pd, dosen tetap IIM Surakarta. Keduanya menyampaikan materi yang relevan dan aplikatif bagi para mahasiswa calon guru MI, khususnya dalam pengembangan bahan ajar Bahasa Arab yang efektif dan sesuai kebutuhan siswa.\n\nDalam pemaparannya, Lady Eka Rahmawati menekankan pentingnya pemahaman karakteristik peserta didik di tingkat MI dalam proses penyusunan bahan ajar. Ia juga menjelaskan beberapa pendekatan dan teknik penyusunan bahan ajar yang komunikatif, kontekstual, dan berbasis kebutuhan belajar siswa.\n\nSementara itu, Dudi Budi Astoko menyoroti pentingnya sistematika penyusunan bahan ajar yang selaras dengan kurikulum serta tujuan pembelajaran Bahasa Arab di madrasah. Ia juga memberikan contoh-contoh praktis dan strategi penyusunan bahan ajar yang dapat langsung diimplementasikan oleh mahasiswa saat praktik mengajar.\n\nKegiatan ini disambut antusias oleh mahasiswa PGMI yang hadir. Selain menambah wawasan, kuliah dosen tamu ini juga menjadi ajang diskusi yang memperkaya pemahaman mahasiswa terkait peran strategis guru dalam merancang bahan ajar Bahasa Arab yang berkualitas.\n\nMelalui kegiatan ini, Prodi PGMI IIM Surakarta berharap mahasiswa mampu mengembangkan kompetensi pedagogis mereka secara lebih matang, serta siap menghadapi tantangan di dunia pendidikan dasar Islam, khususnya dalam pengajaran Bahasa Arab yang kreatif dan terstruktur.', '/api/v1/media/786f6b94-1eac-42a5-9935-4447e03a9d87', 1, 0, '2026-11-24 06:33:41', '2026-11-24 06:33:41'),
(28, 'Visiting Lecture : The Social Learning for Elementary School Students', '26 Mei 2025', '16.00 WIB', 'Program Studi Pendidikan Guru Madrasah Ibtidaiyah (PGMI) Fakultas Tarbiyah Institut Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta kembali menggelar kegiatan kuliah dosen tamu sebagai bagian dari...', 'Program Studi Pendidikan Guru Madrasah Ibtidaiyah (PGMI) Fakultas Tarbiyah Institut Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta kembali menggelar kegiatan kuliah dosen tamu sebagai bagian dari upaya peningkatan wawasan dan kompetensi mahasiswa. Kegiatan ini dilaksanakan secara daring melalui Zoom Meeting pada hari Senin, 26 Mei 2025 pukul 16.00 – 17.30 WIB.\n\nKuliah tamu kali ini mengangkat tema “The Social Learning for Elementary School Students”, dengan menghadirkan narasumber utama Ahyansyah, S.Pd., M.Pd., yang saat ini menjabat sebagai Ketua Program Studi PGSD Universitas Nggusuwaru (UNSWA). Dalam pemaparannya, beliau menyampaikan pentingnya pembelajaran sosial (social learning) dalam membentuk karakter dan keterampilan sosial peserta didik di jenjang sekolah dasar.\n\nDosen pengampu mata kuliah, M. Risdamuddin, M.Pd., turut hadir dan memberikan pengantar serta moderasi selama kegiatan berlangsung. Para mahasiswa antusias mengikuti sesi ini, terlihat dari diskusi interaktif yang terjadi selama kuliah berlangsung.\n\nKegiatan ini merupakan bagian dari komitmen PGMI IIM Surakarta untuk terus menghadirkan pengalaman belajar yang kontekstual dan berwawasan luas, serta memperluas jejaring akademik dengan institusi pendidikan tinggi lainnya.', '/api/v1/media/556fb6ab-aafd-4da7-8b72-6b2b0071d66a', 1, 0, '2026-11-24 06:34:26', '2026-11-24 06:34:26'),
(29, 'Guest Lecture : Membangun Jiwa Kreatif Melalui Pengembangan APE Berbasis Kebutuhan Anak', '5 Juni 2026', '13.00 WIB', 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Fakultas Tarbiyah Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta kembali menyelenggarakan kegiatan Guest Lecture sebagai bagian dari penguatan...', 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Fakultas Tarbiyah Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta kembali menyelenggarakan kegiatan Guest Lecture sebagai bagian dari penguatan kompetensi akademik mahasiswa. Kegiatan yang dilaksanakan secara daring melalui Zoom Meeting pada Jumat, 5 Juni 2026 pukul 13.00 WIB ini mengangkat tema “Membangun Jiwa Kreatif Melalui Pengembangan APE Berbasis Kebutuhan Anak.”\n\nKegiatan dibuka dengan sambutan dan opening speech oleh Elina Intan Apriliani, S.Pd., M.Pd., selaku dosen pengampu mata kuliah Pengembangan Alat Permainan Edukatif (APE). Dalam sambutannya, beliau menyampaikan bahwa pengembangan APE merupakan salah satu kompetensi penting yang harus dimiliki oleh calon pendidik anak usia dini.\n\n“Alat Permainan Edukatif tidak hanya berfungsi sebagai media bermain, tetapi juga menjadi sarana untuk mengoptimalkan seluruh aspek perkembangan anak. Oleh karena itu, mahasiswa PIAUD perlu memiliki kemampuan untuk merancang APE yang kreatif, inovatif, dan sesuai dengan kebutuhan serta karakteristik perkembangan anak,” ungkapnya.\n\nSelanjutnya, Iffah Mukhlisah, M.Pd., selaku Ketua Program Studi PIAUD IIM Surakarta, hadir sebagai keynote speaker. Dalam arahannya, beliau menyampaikan apresiasi atas terselenggaranya kegiatan Guest Lecture yang menghadirkan praktisi dan akademisi dari berbagai perguruan tinggi sebagai upaya memperkaya wawasan mahasiswa.\n\nBeliau menegaskan bahwa pengembangan APE berbasis kebutuhan anak menjadi salah satu strategi pembelajaran yang relevan dalam menciptakan pengalaman belajar yang bermakna, menyenangkan, dan berpusat pada anak.\n\nSebagai narasumber utama, Susan Nurhayati, S.Pd.I., M.Pd. dari IAILM Suryalaya Tasikmalaya, Jawa Barat, memaparkan berbagai konsep dan praktik pengembangan APE yang sesuai dengan tahapan perkembangan anak usia dini. Dalam pemaparannya, beliau menjelaskan bahwa APE yang efektif harus dirancang berdasarkan kebutuhan, minat, kemampuan, dan karakteristik unik setiap anak.\n\nMenurutnya, kreativitas pendidik sangat diperlukan dalam mengembangkan media pembelajaran yang tidak hanya menarik, tetapi juga mampu menstimulasi perkembangan kognitif, bahasa, motorik, sosial emosional, nilai agama dan moral, serta seni pada anak usia dini.\n\n“Pengembangan APE tidak harus selalu menggunakan bahan yang mahal. Pendidik dapat memanfaatkan bahan-bahan sederhana dan lingkungan sekitar menjadi media belajar yang inovatif dan bermakna bagi anak,” jelasnya.\n\nKegiatan berlangsung interaktif dengan antusiasme tinggi dari para mahasiswa yang aktif berdiskusi dan mengajukan pertanyaan terkait proses perancangan, pemilihan bahan, hingga implementasi APE dalam pembelajaran di lembaga PAUD.\n\nMelalui kegiatan ini, mahasiswa diharapkan mampu mengembangkan kreativitas dan keterampilan dalam merancang APE yang sesuai dengan kebutuhan anak serta dapat mengimplementasikannya dalam praktik pembelajaran di masa mendatang.\n\nKegiatan Guest Lecture ini merupakan wujud komitmen Program Studi PIAUD Fakultas Tarbiyah IIM Surakarta dalam menghadirkan pembelajaran yang inovatif, kolaboratif, dan berorientasi pada peningkatan kualitas calon pendidik anak usia dini.', '/api/v1/media/e98d4758-c972-40cf-931b-31fa40e5d6b2', 1, 0, '2026-11-24 06:37:31', '2026-11-24 06:37:31'),
(30, 'Guest Lecture : Merancang Pembelajaran Berlandaskan Asesmen untuk Anak Usia Dini', '15 Juni 2026', '14.300 WIB', 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Fakultas Tarbiyah menyelenggarakan kegiatan Dosen Tamu secara daring melalui Zoom Meeting pada pukul 14.30 WIB. Kegiatan ini mengangkat tema...', 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Fakultas Tarbiyah menyelenggarakan kegiatan Dosen Tamu secara daring melalui Zoom Meeting pada pukul 14.30 WIB. Kegiatan ini mengangkat tema “Merancang Pembelajaran Berlandaskan Asesmen untuk Anak Usia Dini” dan diikuti oleh mahasiswa PIAUD sebagai bagian dari penguatan kompetensi pada mata kuliah Perencanaan Pembelajaran AUD.\n\nKegiatan diawali dengan sambutan dari Iffah Mukhlisah, M.Pd., Kaprodi PIAUD IIM Surakarta, yang menyampaikan pentingnya kemampuan calon pendidik anak usia dini dalam merancang pembelajaran yang berangkat dari hasil asesmen perkembangan anak. Beliau menegaskan bahwa asesmen merupakan fondasi penting dalam memahami kebutuhan, potensi, dan karakteristik setiap anak sehingga pembelajaran yang dirancang dapat lebih tepat sasaran dan bermakna.\n\nSelanjutnya, Annafi’ Nurul ‘Ilmi Azizah, S.Pd., M.Pd., selaku dosen pengampu Mata Kuliah Perencanaan Pembelajaran AUD, memberikan pengantar mata kuliah sekaligus menjelaskan relevansi kegiatan dosen tamu dengan capaian pembelajaran mata kuliah. Beliau menyampaikan bahwa mahasiswa perlu memahami keterkaitan antara asesmen dan perencanaan pembelajaran agar mampu menyusun program pembelajaran yang sesuai dengan kebutuhan perkembangan anak usia dini.\n\nMateri utama disampaikan oleh Andepi Daryana, M.Pd. dari STAI Siliwangi Garut. Dalam pemaparannya, beliau menjelaskan konsep pembelajaran berlandaskan asesmen, mulai dari proses pengumpulan data perkembangan anak, analisis hasil asesmen, hingga pemanfaatan informasi tersebut dalam penyusunan tujuan, strategi, media, dan evaluasi pembelajaran. Pemateri juga memberikan berbagai contoh penerapan asesmen autentik yang dapat digunakan oleh guru PAUD dalam praktik pembelajaran sehari-hari.\n\nKegiatan berlangsung dengan antusias dan interaktif. Mahasiswa aktif mengajukan pertanyaan serta berdiskusi mengenai berbagai tantangan dalam pelaksanaan asesmen dan penyusunan pembelajaran yang berpusat pada anak. Melalui kegiatan ini, diharapkan mahasiswa memperoleh pemahaman yang lebih mendalam mengenai pentingnya asesmen sebagai dasar dalam merancang pembelajaran yang efektif, menyenangkan, dan sesuai dengan karakteristik anak usia dini.\n\nKegiatan dosen tamu ini menjadi salah satu bentuk komitmen Program Studi PIAUD Fakultas Tarbiyah dalam menghadirkan pengalaman belajar yang berkualitas melalui kolaborasi akademik dengan berbagai praktisi dan akademisi di bidang pendidikan anak usia dini.', '/api/v1/media/d5e4b4cd-b20b-455a-a928-d9b6d9b265df', 1, 0, '2026-11-24 06:38:09', '2026-11-24 06:38:09'),
(31, 'Guest Lecture : Penyusunan dokumen Kurikulum AUD', '3 November 2026', '13.00 WIB', '\"Fakultas Tarbiyah mengundang Anda untuk bergabung ke rapat Zoom yang terjadwal. Topik: Penyusunan dokumen Kurikulum AUD Waktu: 3 Nov 2026 01:00 PM Jakarta Bergabung ke Rapat Zoom...', '\"Fakultas Tarbiyah mengundang Anda untuk bergabung ke rapat Zoom yang terjadwal.\n\nTopik: Penyusunan dokumen Kurikulum AUD\nWaktu: 3 Nov 2026 01:00 PM Jakarta\n\nBergabung ke Rapat Zoom\nhttps://zoom.us/j/97913998677?pwd=I6RXHCsZa2GH4rRgg6fuqBz5HZUb15.1\n\nBergabung dan buat catatan\nhttps://zoom.us/j/97913998677?pwd=I6RXHCsZa2GH4rRgg6fuqBz5HZUb15.1&mynotes=on\n\nTautan obrolan rapat\nhttps://zoom.us/launch/jc/97913998677\n\nID Rapat: 979 1399 8677\nKode Sandi: iimpiaud\n\n---\n\nSekali ketuk pada ponsel\n+12532050468,,97913998677#,,,,*31623323# Amerika Serikat\n+12532158782,,97913998677#,,,,*31623323# Amerika Serikat (Tacoma)\n\n\n---\n\nBergabung dengan SIP\n• 97913998677@zoomcrc.com\n\nInstruksi untuk bergabung\nhttps://zoom.us/meetings/97913998677/invitations?signature=BHYkOcQMpz26zYWdf97GkU6006SCz7JeFs4F3XoOkys\"', '/api/v1/media/75806994-e9af-402a-8bdc-fbba48416411', 1, 0, '2026-11-24 06:42:59', '2026-11-24 07:03:51'),
(32, 'Guest Lecture : Hubungan Model, Strategi, Metode & Media Pembelajaran', '18 November 2026', '14.30 WIB', '\"Fakultas Tarbiyah mengundang Anda untuk bergabung ke rapat Zoom yang terjadwal. Topik: Hubungan model, strategi, metode dan media pembelajaran. Waktu: 18 Nov 2026 02:30 PM Jakarta Bergabung ke...', '\"Fakultas Tarbiyah mengundang Anda untuk bergabung ke rapat Zoom yang terjadwal.\n\nTopik: Hubungan model, strategi, metode dan media pembelajaran.\nWaktu: 18 Nov 2026 02:30 PM Jakarta\n\nBergabung ke Rapat Zoom\nhttps://zoom.us/j/94066412952?pwd=kgOmlaohPJPL7k2EB2Qv00TghQQiXE.1\n\nBergabung dan buat catatan\nhttps://zoom.us/j/94066412952?pwd=kgOmlaohPJPL7k2EB2Qv00TghQQiXE.1&mynotes=on\n\nTautan obrolan rapat\nhttps://zoom.us/launch/jc/94066412952\n\nID Rapat: 940 6641 2952\nKode Sandi: iimpai\n\n---\n\nSekali ketuk pada ponsel\n+12532158782,,94066412952#,,,,*816619# Amerika Serikat (Tacoma)\n+13017158592,,94066412952#,,,,*816619# Amerika Serikat (Washington DC)\n\n\n---\n\nBergabung dengan SIP\n• 94066412952@zoomcrc.com\n\nInstruksi untuk bergabung\nhttps://zoom.us/meetings/94066412952/invitations?signature=y-VK1YYQyLkyFZQxy-j7B8o2iVLhfMSyN1KxvYfEm6g', '/api/v1/media/c7b22dd9-b0a9-41b1-b359-928e3c194b84', 1, 0, '2026-11-24 07:08:46', '2026-11-24 07:25:46'),
(33, 'Guest Lecture : Otoritas Hadis dalam Islam: Antara Kesahihan Riwayat dan Kehujjahan sebagai Sumber Ajaran', '16 November 2026', '19.30 WIB', '\"Fakultas Tarbiyah mengundang Anda untuk bergabung ke rapat Zoom yang terjadwal. Topik: Otoritas Hadis dalam Islam: Antara Kesahihan Riwayat dan Kehujjahan sebagai Sumber Ajaran Waktu: 16 Nov 2026...', '\"Fakultas Tarbiyah mengundang Anda untuk bergabung ke rapat Zoom yang terjadwal.\n\nTopik: Otoritas Hadis dalam Islam: Antara Kesahihan Riwayat dan Kehujjahan sebagai Sumber Ajaran\nWaktu: 16 Nov 2026 08:30 PM Jakarta\n\nBergabung ke Rapat Zoom\nhttps://zoom.us/j/99922413708?pwd=SodRfsTvbtZQSHllGKL5SpK5cE0iXz.1\n\nBergabung dan buat catatan\nhttps://zoom.us/j/99922413708?pwd=SodRfsTvbtZQSHllGKL5SpK5cE0iXz.1&mynotes=on\n\nTautan obrolan rapat\nhttps://zoom.us/launch/jc/99922413708\n\nID Rapat: 999 2241 3708\nKode Sandi: iimpgmi\n\n---\n\nSekali ketuk pada ponsel\n+13462487799,,99922413708#,,,,*7517657# Amerika Serikat (Houston)\n+13602095623,,99922413708#,,,,*7517657# Amerika Serikat\n\n\n---\n\nBergabung dengan SIP\n• 99922413708@zoomcrc.com\n\nInstruksi untuk bergabung\nhttps://zoom.us/meetings/99922413708/invitations?signature=NZycCdz7nZ8AEygzKC9gkd2dZj3r3kTdOcvPaBuQ0P8\n\n\"', '/api/v1/media/29920c17-24d9-4ba7-98f1-76688e22cff3', 1, 0, '2026-11-24 07:09:41', '2026-11-24 07:25:41');

