INSERT INTO `testimonials` (`id`, `name`, `job_title`, `category_id`, `quote`, `full_content`, `rating`, `avatar_url`, `gallery_urls`, `slideshow_position`, `is_visible`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 'Review Kurikulum', '10 November 2021', 1, 'Institut Islam Mamba’ul ‘Ulum Surakarta menyelenggarakan workshop review kurikulum yang fokus pada dua pembahasan', 'Amrani Syariah Hotel Solo, Institut Islam Mamba’ul ‘Ulum Surakarta menyelenggarakan workshop review kurikulum yang fokus pada dua pembahasan. Pertama, penyusunan Visi Misi Fakultas dan Institut. Kedua, melaksanakan review perubahan pada beberapa Mata Kuliah.\n\nDalam arahannya, Dr. H. Muh. Kurniawan BW, S.Ag, SH, MH. Wakil Rektor 1 bidang akademik dan Yayasan Institut menyampaikan bahwa penyusunan dokumen kurikulum IIM Surakarta saat ini menemukan momentumnya dengan kebijakan baru yang telah diterapkan, yaitu Permendikbud no 3 tahun 2020, tentang standar nasional pendidikan tinggi (SNPT) yang juga mengamanahkan implementasi kampus merdeka dan merdeka belajar. Dalam implementasinya kurikulum ini dapat dipersiapkan secara bertahap, namun intisari struktur kurikulumnya sudah kita sepakati terlebih dahulu.  Forum kali ini diharapkan menyepakati pedoman pengembangan kurikulum sebagai dokumen induk di kampus kita.\n\nKetua Yayasan Institut Islam Surakarta – Dr. Hj. Chusniatun, M.Ag. menjelaskan bahwa, pembahasan review kurikulum IIM Surakarta sangat penting guna menguatkan mutu proses pembelajaran agar selalu actual. Demikian pula review rencana pembelajaran semester (RPS). Kampus kita, harus selalu rensponsif dalam menghadapi perubahan agar lulusan kita dapat melampaui SNPT dan memuaskan pelanggan, yaitu masyarakat.\n\nDr. Joko Subando, M.Pd, wakil rektor 1 IIM Surakarta, secara langsung memberikan masukan-masukan bagi penyempurnaan pandungan pengembangan kurikulum dari aspek, implementasi visi dan misi IIM Surakarta, serta values dalam kurikulum. Termasuk juga pilihan dalam subyek program studi yang mengambil mata kuliah pada program studi se kampus dan lembaga lain di luar perguruan tinggi.\n\nRektor Dr. H. Muh. Kurniawan BW, S.Ag, SH, MH. menekankan strategisnya implementasi model-model integrasi ilmu di dalam rencana pembelajaran semester (RPS). Pendekatan interkoneksi antar bidang ilmu, antar mata kuliah harus tertera di dalam RPS. Demikian pula, metodologinya agar integrasi Islam, sains dan kearifan lokal, dapat terimplementasi dengan baik dalam proses pembelajaran. Demikian pula, integrasi hasil penelitian dan pengabdian kepada masyarakat yang dilakukan oleh dosen, harus tersurat di dalam daftar rujukan RPS. Workshop pada hari Rabu diakhiri dengan penandatanganan SK Visi Misi dan Berita Acara setiap Fakultas dan Institut Islam Mamba’ul ‘Ulum Surakarta.', 5, '/api/v1/media/dda235d1-ea39-40a1-9ae7-b6c0959b15b4', '[\"/api/v1/media/caafae8f-e979-4a6c-82bb-79b2a953f942\",\"/api/v1/media/4b0480e2-1390-424a-bcef-416aa572c357\",\"/api/v1/media/bc06cc01-a75b-4717-ae4a-d893d848681a\",\"/api/v1/media/838ce3c3-925a-4711-9d1d-d1a3436c2ecd\"]', 'top', 1, 0, '2026-11-23 09:38:52', '2026-11-23 09:38:52'),
(2, 'MoU dengan Yayasan Al-Falah Sragen', '16 Juli 2022', 5, 'Penandatanganan MoU antara Institut Islam Mamba’ul Ulum Surakarta dan Yayasan Al-Falah Kabupaten Sragen terkait kerjasama yang meliputi beberapa bidang', 'Penandatanganan MoU antara Institut Islam Mamba’ul Ulum Surakarta dan Yayasan Al-Falah Kabupaten Sragen terkait kerjasama yang meliputi beberapa bidang. Acara tersebut dihadiri beberapa perwakilan dari kedua lembaga baik Institut Mamba’ul Ulum Surakarta maupun Yayasan Al-Falah Kabupaten Sragen. Dari IIM Surakarta hadir Mukhlis Fathurrohman, S.Ag., MSI. selaku Wakil Rektor III dan ditemani oleh Kepala Audit Mutu Internal Aditya Fajri Kurnia P., S.Sy. sedangkan dari Yayasan Al-Falah Sragen diwakili oleh Suparlan S.Pd. selaku ketua Yayasan yang ditemani Muhammad Isnaini, S.T. selaku Ketua Bidang Ekonomi.\n\nAdapun bidang kerjasama yang dimaksud dalam MoU tersebut antara lain: Pertama, terkait Pengembangan Standar Mutu; Kedua, Audit Mutu Internal; Ketiga, Akreditasi Program Studi dan Akreditasi Institusi Perguruan Tinggi (AIPT); Keempat, Kegiatan lain yang Relevan.\n\nMenurut Wakil Rektor III Mukhlis Fathurrohman, S.Ag., MSI., silaturrahmi yang berfokus pada interkasi sosial ini memegang peranan penting dalam keberhasilan membangun hubungan yang baik dengan siapapun.\n\n“IIM Surakarta ingin memfasilitasi para dewan Asatidz untuk meningkatkan kompetensi di bidang pendidikan dalam artian untuk melanjutkan ke jenjang Strata 1 maupun Strata 2. Untuk Mahasantri di Yayasan Al-Falah kami harap fokuds di program tahfidz setelah selesai kami harap bisa lanjut ke jenjang S1 baik Fakultas Tarbiyah, Syariah, maupun Dakwah dalam rangka untuk memperkuat keilmuan yang dimiliki serta legalitas kesarjanaan.” Ujar Wakil Rektor III tersebut.\n\nRencanannya kerja sama tersebut akan berlaku selama 3 tahun sejak ditandatangani dan dapat diperbaharui kembali jika disepakati bersama.', 5, '/api/v1/media/ad58fc0c-2b04-4f85-a379-06d11f83710d', '[\"/api/v1/media/fca470da-1023-4a27-8ed3-a36f822b0eef\"]', 'bottom', 1, 0, '2026-11-23 09:41:34', '2026-11-23 09:41:34'),
(3, 'Dosen IIM Surakarta Ikuti Pelatihan Klinik Pendampingan Program Studi PTKI yang Diselenggarakan oleh Kemenag RI', '14 Desember 2022', 1, 'Dekan Fakultas Tarbiyah dan Kaprodi PGMI mengikuti kegiatan Klinik Pendampingan Prodi PTKI yang diselenggarakan oleh Kemenag RI dan diikuti oleh beberapa perwakilan dari Kopertais Wilayah IV (Jawa Timur) dan Kopertais Wilayah X (Jawa Tengah)', 'Dua dosen IIM Surakarta, yakni Dra. Hj. Nur Hidayah, M.S.I (Dekan Fakultas Tarbiyah) dan Lailla Hidayatul Amin, S.Pd., M.Pd.I (Kaprodi PGMI) mengikuti kegiatan Klinik Pendampingan Prodi PTKI yang diselenggarakan oleh Kemenag RI dan diikuti oleh beberapa perwakilan dari Kopertais Wilayah IV (Jawa Timur) dan Kopertais Wilayah X (Jawa Tengah) bertempat di Hotel Grand Mercure Wonocolo Surabaya-Jatim pada tanggal 08-10 Desember 2022.\n\nFokus kegiatan klinik ini adalah untuk melakukan pendampingan penyusunan Instrumen Akreditasi Program Studi (APS) yang akan submit untuk asesmen APS ke Lembaga Akreditasi Mandiri Kependidikan (LAMDIK) dan Lembaga Akreditasi Mandiri Ekonomi Manajemen Bisnis dan Akuntansi (LAMEMBA).\n\nDalam kesempatan tersebut, Kemanag RI menggandeng Best-Q Institute sebagai pendamping pada kegiatan yang dilaksanakan selama 3 hari tersebut. Kegiatan dimulai dengan pembukaan yang dipandu oleh Ibu Hj. Zidal Huda, S.Ag., M.H, kemudian dilanjutkan dengan game yang dipandu oleh Bapak Yusuf Nalim (salah satu team Best Q Institute).\n\nKegiatan dilanjutkan secara panel yang terdiri dari kelas LAMDIK 1 didampingi oleh Dr. H. Fajri Ismail, M.Pd.I, LAMDIK 2 didampingi Dr. Muh Nashirudin, S.Ag., M.Ag dan LAMEMBA oleh Dr. Helmi Syaifuddin, M.Fil. Disitulah kemudian materi secara mendalam diberikan oleh Best-Q Institute.\n\nPoint penting lain yang disampaikan oleh Yusuf Nalim, pada kelas LAMDIK 1 adalah “Dalam Menyusun DED harus disesuaikan dengan pedoman dan matrik penilaian (usahakan penuhi tagihan skor 4). Gunakan 5W 1H dalam penyusunan data kualitatif”. Ujarnya.\n\nDalam kesempatan tersebut, dilakukan pula simulasi penilaian Instrumen Akreditasi sehingga peserta mendapat gambaran bagaimana proses penilaiannya dan berapa perkiraan nilai yang diperoleh dari Instrumen akreditasi baik nilai Kuantitatif maupun kualitatifnya.\n\nSelanjutnya, Fajri Ismail memberikan penguatan “Maksimalkan data kuantitatif, karena memiliki prosentase sebesar 53,65%, sisanya data kualitatif dengan prosentase 46,35%. Perlu memperhatikan kriteria yang mamiliki bobot tinggi, yaitu kriteria 9 (luaran) sebesar 33% dan kriteria 6 (Pendidikan) sebesar 13%”.\n\nPersiapan akreditasi yang sangat penting adalah harus dibentuk teamwork baik dari pihak yayasan, pimpinan, UPPS, tendik, DTPS, mahasiswa, stakeholder, mitra, user. Hal tersebut menjadi point penting atas ketercapaian predikat Akreditasi Prodi Unggul kemudian diimbangi dengan do’a.\n\nKlinik pendampingan akreditasi program studi berjalan dengan lancar dan cukup sekali dirasakan kebermanfaatannya bagi masing-masing Program Studi. Pengalaman dan ilmu dari kegiatan tersebut membuka wawasan dalam mempersiapkan akreditasi, juga menjadi penyemangat dan penyempurna data akreditasi. Diharapkan akan ada kegiatan pendampingan yang berkelanjutan menuju Kampus PTKI yang Unggul. Hadir dalam kesempatan itu, Perwakilan dari Kemenag RI, Kopertais IV Jawa Timur, Kopertais X Jawa Tengah, Dr. Helmi Syaifuddin, M.Fil.I, CRMP, Yusuf Nalim, S.Si, M.Si, Indrawati, S.S, M.Pd, CRA, CRP, Dr. Muh. Nashirudin, S.Ag., M.Ag, Dr. H. Fajri Ismail, M.Pd.I, perwakilan Kaprodi, LPM, LPPM, Dekan dan Team penyusun Instrumen Akreditasi dari beberapa perguruan tinggi.', 5, '/api/v1/media/54953d21-0d50-400a-b190-019a25067f73', NULL, 'bottom', 1, 0, '2026-11-23 09:44:05', '2026-11-23 09:44:05'),
(4, 'Kepedulian Kita Menghadirkan Senyum Mereka', '2 Mei 2023', 1, 'PGMI BERBAGI Jilid V', 'Bakti sosial atau lebih dikenal dengan baksos ini merupakan suatu kegiatan wujud dari kepedulian atau rasa kemanusiaan terhadap sesama. Dimana dengan adanya kegiatan ini kita dapat merekatkan rasa kekerabatan kita terhadap orang lain. Kegiatan ini dilakukan untuk memberikan manfaat dan tujuan-tujuan tertentu.\n\nPada hari Senin tanggal 10 April 2023 di Himpunan Mahasiswa Program Studi Pendidikan Guru Madrasah Ibtidaiyah (HMPS PGMI) dari Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta mengadakan santunan untuk adik-adik panti asuhan serta melakukan buka bersama dalam acara bakti sosial. Kegiatan ini merupakan event tahunan HMPS PGMI IIM Surakarta untuk mewujudkan kepedulian terhadap sesama manusia. PGMI BERBAGI Jilid V dengan tema Kepedulian kita menghadirkan senyum mereka ini diselenggarakan dengan mengadakan kegiatan bakti sosial pada pukul 15.00–21.00 WIB.\n\nDalam kunjungan baksos ini diisi dengan beberapa rangkaian acara yang dipandu oleh panitia acara PGMI Berbagi dengan urutan kegiatan pertama yaitu sambutan dari pengurus Yayasan Jannatul Firdaus, dilanjutkan sambutan dari Kaprodi PGMI Ibu Lailla Hidayatul Amin S.Pd., M.Pd.I, dan dilanjutkan sesi membacakan sholawat nabi bersama-sama. Tidak hanya itu, Tim HMPS PGMI juga mengadakan sesi mendongeng untuk menghibur adik-adik yang ada di Panti Asuhan. Gelak tawa pun tidak dapat kami bendung oleh tingkah lucu dari adek-adek. Kebahagian yang sangat luar biasa saat kami bisa menghibur anak-anak yatim.\n\nDalam sambutanya Ibu Ani selaku perwakilan dari Pengurus yayasan Jannatul Firdaus mengucapakan banyak terimakasih kepada HMPS PGMI dan kampus IIM Surakarta yang mau meluangkan waktu untuk bersilaturahmi ke Yayasan Jannatul Firdaus.\n\nPada acara baksos, HMPS PGMI dan sponsor yang bekerjasama dalam agenda ini juga menyerahkan sumbangan berupa uang, sembako, dan alat tulis, membantu memperlancar aktivitas para penghuni panti dan melalui pemberian ini, HMPS PGMI berharap dapat membantu meningkatkan semangat para penghuni panti dalam melakukan aktivitas sehari-hari terutama untuk aktivitas sekolah mereka.\nSafa Salwa (Ketua Pelaksana kegiatan PGMI BERBAGI Jilid V).', 5, '/api/v1/media/7d2a4e01-b16e-4613-b72a-bb2048de497a', '[\"/api/v1/media/413f8973-084d-4c12-aee6-55779f2797c0\"]', 'bottom', 1, 0, '2026-11-23 09:46:33', '2026-11-23 09:46:33'),
(5, 'Muslimah Istiqomah di Zaman Penuh Fitnah', '20 Mei 2023', 8, 'Seminar kemuslimahan atau lebih sering kami sebut dengan semusim merupakan salah satu program kerja tahunan dari bidang Nisa’iyyah Lembaga Dakwah Kampus An-Naml (LDK An-Naml) Institut Islam...', 'Seminar kemuslimahan atau lebih sering kami sebut dengan semusim merupakan salah satu program kerja tahunan dari bidang Nisa’iyyah Lembaga Dakwah Kampus An-Naml (LDK An-Naml) Institut Islam Mamba’ul ‘Ulum Surakarta (IIM Surakarta). Seminar ini bertujuan untuk mempererat ukhuwah antarmuslimah khususnya di wilayah solo raya dan sekitarnya. Selain itu, seminar ini juga diselenggarakan untuk mencapai tujuan-tujuan tertentu.\n\nPada hari Kamis tanggal 18 Mei 2023 seminar kemuslimahan LDK An-Naml IIM Surakarta diselenggarakan dalam bentuk talkshow dengan dua moderator dan satu pembicara. Seminar kali ini mengangkat tema tentang “Muslimah Istiqomah di Zaman Penuh Fitnah.” Konsep dari tema seminar tersebut adalah difokuskan untuk wanita muslimah dengan tujuan penguatan iman menghadapi fitnah di zaman sekarang agar para akhwat tetap teguh memegang aturan Allah dan tidak tergoda dengan gemilaunya dunia.\n\nSeminar kemuslimahan LDK An-Naml IIM Surakarta berlangsung dari pukul 09.00 WIB sampai 11.45 WIB dan bertempat di Aula IIM Surakarta. Seminar ini diisi dengan berbagai rangkaian acara yang dipandu oleh moderator kece yaitu kak Azizah dan kak Piu. Pada awal acara, kak Azizah bersama kak Piu membuka acara dan mulai menyapa para peserta. Setelah selesai sapa menyapa peserta, moderator mempersilakan qori’ untuk naik ke atas panggung membacakan tilawah Al-Qur’an. Peserta tampak begitu menghayati bacaan Al-Qur’an yang dilantunkan oleh qori’.\n\nAcara yang berikutnya adalah sambutan- sambutan. Sambutan yang pertama adalah dari ketua pelaksana semusim, dilanjutkan sambutan dari ketua bidang Nisa’iyyah, dan diakhiri oleh sambutan dari Ibu Lailla Hidayatul Amin, S.Pd., M.Pd.I, selaku wakil dekan fakultas tarbiyah IIM Surakarta. Rangkaian sambutan membuat para peserta tampak jenuh dan mulai mengantuk. Oleh karena itu, moderator yang tak kehabisan ide akhirnya mengajak para peserta untuk berdiri dan mengikuti ice breaking. Suasana yang tadinya jenuh berubah menjadi cair. Para peserta pun tampak bahagia dan bersemangat untuk kembali mengikuti rangkaian acara.\n\nSebelum memasuki inti acara yaitu talkshow, moderator terlebih dahulu membacakan Curriculum Vitae (CV) dari pembicara. Pembicara talkshow kali ini adalah Ustadzah Tri Budiana, S.Pd., atau yang lebih akrab disapa dengan Bu Nana. Talkshow berlangsung dengan sangat interaktif karena moderator aktif memberikan pertanyaan dan Bu Nana begitu antusias menyodorkan fakta kebobrokan dunia berikut dengan solusinya. Bu Nana juga sangat aktif melempar pertanyaan kepada peserta, sehingga mampu melatih mental dan memberikan kesempatan kepada para peserta untuk berani mengemukakan pendapatnya. Tak ketinggalan tentunya, panitia memberikan doorprize sebagai wujud apresiasi kepada para peserta yang telah berani menyampaikan pendapatnya.\n\nTak terasa, sesi talkshow telah berakhir dan tentunya memunculkan banyak tanya di kepala. Lalu, moderator membuka sesi Question and Answer (QnA) kepada para peserta yang ingin bertanya dan sharing-sharing terkait materi yang telah disampaikan. Sesi QnA merupakan tanda bahwa acara sudah tiba di penghujungnya. Setelah sesi QnA selesai, moderator memohon pamit undur diri dan menutup acara dengan hamdalah dan salam. Seminar kemuslimahan ditutup dengan foto bersama antara pembicara, peserta dan panitia sebagai arsip dokumentasi agar nantinya mampu menjadi kenangan yang diingat sampai hari tua.', 5, '/api/v1/media/abfed19f-37fb-4d23-ac6c-23364b71afba', NULL, 'bottom', 1, 0, '2026-11-23 09:47:21', '2026-11-24 01:23:10'),
(6, 'Pembekalan PPL : Peningkatan Kompetensi Pembelajaran Guru dan Calon Guru', '24 Juli 2023', 1, 'Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta menyelenggarakan kegiatan pembekalan Praktik Pengalaman Lapangan (PPL) dengan tema “Peningkatan Kompetensi Pembelajaran bagi Guru dan Calon Guru', 'Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta menyelenggarakan kegiatan pembekalan Praktik Pengalaman Lapangan (PPL) dengan tema “Peningkatan Kompetensi Pembelajaran bagi Guru dan Calon Guru”.\n\nKegiatan ini diadakan oleh Fakultas Tarbiyah di Kampus IIM Surakarta dan melibatkan 25 lembaga pendidikan dari tingkat sekolah dasar (SD) hingga sekolah menengah atas (SMA) di wilayah Soloraya. IIM mengundang seluruh pamong sekolah yang terlibat serta dua perwakilan mahasiswa dari setiap kelompok PPL.\n\nBeberapa sekolah yang berpartisipasi dalam kegiatan ini antara lain: MTs Al Islam Jamsaren, SMPIT Insan Mulia Surakarta, MA Al Islam Jamsaren, SMP Muhammadiyah 5 Surakarta, dan SMA Al Firdaus Surakarta. Selain itu, terdapat juga MTs N 1 Sukoharjo, SMA Al Islam 1 Surakarta, MAN 2 Surakarta, SMK M 2 Sukoharjo, dan SMP M 8 Sukoharjo, serta beberapa sekolah lainnya.\n\nPembukaan kegiatan pembekalan ini dipimpin oleh Rektor IIM Surakarta, H. Muh Kurniawan B.W., yang menekankan pentingnya menjaga nama almamater, diri sendiri, keluarga, dan sekolah selama pelaksanaan PPL. Adab dan etika dalam pelaksanaan PPL diharapkan tetap dijaga dengan baik.\n\nSelama acara pembekalan, peserta mendapatkan pengantar dan mekanisme PPL dari Ketua Program Studi (Kaprodi) Pendidikan Agama Islam IIM Surakarta yang juga menjadi Ketua Panitia PPL, H. M. J. Nashir, serta informasi mengenai pengelolaan pembiayaan atau keuangan selama PPL yang disampaikan oleh Edy Muslimin. Joko Subando membahas teknik penyusunan laporan PPL dan luaran, sedangkan Slamet Budiyono membawakan materi tentang kurikulum operasional satuan pendidikan (KOSP) sebagai penerapan Kurikulum Merdeka Belajar di sekolah. Lanjar Utami juga menyampaikan strategi pembelajaran kreatif dan inovatif pada Kurikulum Merdeka.\n\nSetelah pembukaan oleh Rektor IIM Surakarta, H. Muh Kurniawan B.W., kegiatan pembekalan dilanjutkan dengan pemaparan materi oleh para narasumber. H. M. J. Nashir, selaku Ketua Program Studi (Kaprodi) Pendidikan Agama Islam IIM Surakarta dan Ketua Panitia PPL, memberikan pengantar dan menjelaskan mekanisme PPL kepada para peserta. Informasi tersebut mencakup langkah-langkah pelaksanaan PPL, peran dan tanggung jawab mahasiswa, serta ekspektasi dari pihak lembaga pendidikan mitra.\n\nEdy Muslimin memberikan wawasan tentang teknik pengelolaan pembiayaan atau keuangan selama PPL. Informasi ini penting bagi mahasiswa agar dapat mengatur dan menggunakan dana dengan bijaksana selama masa pelaksanaan PPL, agar kegiatan berjalan lancar dan sesuai dengan rencana.\n\nSelanjutnya, Joko Subando memberikan panduan tentang teknik penyusunan laporan PPL dan luaran. Penyusunan laporan yang baik akan membantu dalam memantau dan mengevaluasi perkembangan mahasiswa selama PPL, serta memberikan informasi yang berguna bagi pengembangan program PPL di masa mendatang.\n\nSlamet Budiyono membahas kurikulum operasional satuan pendidikan (KOSP) sebagai penerapan Kurikulum Merdeka Belajar di sekolah. Kurikulum Merdeka Belajar merupakan inisiatif pemerintah Indonesia untuk memberikan kebebasan kepada sekolah dalam merancang kurikulum yang lebih relevan dengan kebutuhan siswa dan lingkungan sekolah.\n\nLanjar Utami menyampaikan strategi pembelajaran kreatif dan inovatif pada Kurikulum Merdeka. Penyampaian materi ini bertujuan untuk menginspirasi para calon guru agar dapat mengembangkan metode pembelajaran yang menarik, interaktif, dan sesuai dengan kebutuhan generasi muda saat ini.\n\nMelalui kegiatan pembekalan ini, diharapkan para mahasiswa yang akan menjalani PPL dapat memahami pentingnya peran mereka sebagai calon guru dalam meningkatkan kompetensi pembelajaran. Selain itu, dengan kolaborasi antara IIM Surakarta dan lembaga pendidikan setempat, diharapkan PPL dapat berjalan dengan efektif dan memberikan manfaat yang nyata bagi mahasiswa serta lembaga pendidikan mitra. Dengan pendekatan pembelajaran yang kreatif dan inovatif, diharapkan proses PPL ini akan semakin memperkaya pengetahuan dan pengalaman mahasiswa sebagai calon guru masa depan.', 5, '/api/v1/media/6b5491fe-bfaa-4a77-aa1e-ea63449107c9', '[\"/api/v1/media/bedd4340-52dd-4097-8fac-13cc3d8c4145\",\"/api/v1/media/40d38286-ee1e-4a73-a4e0-1922c7d30ac8\",\"/api/v1/media/116c1f81-7dec-4c87-9622-0bbeb06988ca\",\"/api/v1/media/f4f0be0f-994f-4652-9b67-10b30813f9c7\",\"/api/v1/media/58e9d793-bcb8-46b0-bb41-ff721b909307\"]', 'bottom', 1, 0, '2026-11-23 09:49:03', '2026-11-23 09:49:03'),
(7, 'Kaprodi PGMI IIM Surakarta Hadiri Musyawarah Kerja Nasional PD-PGMI Ke-9 dan International Conference SICEE', '2 Agustus 2023', 1, 'Civitas akademika IIM Surakarta mengirimkan delegasi untuk mengikuti Asosiasi Dosen PD- PGMI pada Musyawarah Kerja Nasional (MUKERNAS) ke-9 dan International Conference dengan tema “Curriculum Transformation: Kurikulum Merdeka for Facing the Era of Society 5.0” Tahun 2023 di IAIN Syekh Nurjati Cirebon', 'Civitas akademika IIM Surakarta mengirimkan delegasi untuk mengikuti Asosiasi Dosen PD- PGMI pada Musyawarah Kerja Nasional (MUKERNAS) ke-9 dan International Conference dengan tema “Curriculum Transformation: Kurikulum Merdeka for Facing the Era of Society 5.0” Tahun 2023 di IAIN Syekh Nurjati Cirebon.\n\nAcara tersebut mempertemukan para profesional pendidikan, akademisi, dan praktisi dari berbagai negara, yang telah berbagi pengalaman dan pengetahuan mereka dalam mengembangkan program yang disesuaikan dengan kebutuhan zaman. Dalam ajang tingkat nasional ini, Prodi PGMI IIM Surakarta menjalin kerjasama dengan beberapa perguruan tinggi se-Indonesia.\n\nDekan Fakultas Tarbiyah IIM Surakarta, Dra. Hj. Nur Hidayah, M.S.I, memberikan apresiasi kepada Prodi PGMI IIM Surakarta karena telah mengikuti rangkaian kegiatan Musyawarah Kerja Nasional dan Internasional Conference bersama 80 peserta dari berbagai PTKIN dan PTKIS.\n\nMukernas PD-PGMI Indonesia merupakan acara tahunan yang mengangkat isu-isu terkini dalam pendidikan guru di Indonesia, khususnya di tingkat Madrasah Ibtidaiyah. Pada acara tersebut, delegasi program studi PGMI dari seluruh Indonesia berkumpul untuk mengevaluasi, menyusun strategi, dan mensukseskan implementasi Merdeka Belajar-Kampus Merdeka khususnya terkait Profil Lulusan dan CPL serta membahas Body of Knowledge Program Studi PGMI.\n\nSelaku Kaprodi PGMI IIM Surakarta, Ibu Lailla Hidayatul Amin, M.Pd.I . menyampaikan bahwa kegiatan ini sangat bermanfaat bagi pengembangan lembaga khususnya program studi PGMI karena out put dari kegiatan ini merupakan hasil musyawarah bersama terkait Body of Knowledge dan CPL program studi PGMI baik jenjang Sarjana, Pasca Sarjana dan Doktor.\n\nDengan partisipasi aktif kaprodi PGMI pada Mukernas PD-PGMI Indonesia dan SICEE, diharapkan terjadi sinergi antara lembaga pendidikan yang fokus pada peningkatan kualitas pendidikan guru dan kurikulum yang mandiri untuk mencapai tujuan pendidikan yang telah ditetapkan. lebih lengkap, inovatif dan up-to-date.', 5, '/api/v1/media/fa03d2d4-cde7-49f5-a815-57b73d463e44', '[\"/api/v1/media/539df2cd-761c-4895-bd28-565ac13c8f7d\",\"/api/v1/media/9bba96db-b5cc-4673-90f1-5cea716d0948\",\"/api/v1/media/77a2abf7-225c-413e-b8d7-ff524b4c6f2d\",\"/api/v1/media/abf00054-e907-4d07-8122-490ca34fa58a\",\"/api/v1/media/55728b03-9c3b-45a9-a6d5-44272ed9570c\",\"/api/v1/media/3d6b27b4-59c3-41ff-af8f-83153edd387a\"]', 'bottom', 1, 0, '2026-11-23 09:51:31', '2026-11-23 09:51:31'),
(8, 'Mahasiswa PGMI IIM Surakarta mengikuti Musyawarah Wilayah III WIJAYATIRTA (IMPI) Ikatan Mahasiswa PGMI Indonesia yang Ke', '8 Agustus 2023', 1, 'PGMI Institut Islam Mamba’ul ‘Ulum Surakarta mengirimkan delegasi untuk menghadiri agenda Musyawarah Wilayah III WIJAYATIRTA (IMPI) Ikatan Mahasiswa PGMI Indonesia yang Ke-7. Bertempat di IAIN...', 'PGMI Institut Islam Mamba’ul ‘Ulum Surakarta mengirimkan delegasi untuk menghadiri agenda Musyawarah Wilayah III WIJAYATIRTA (IMPI) Ikatan Mahasiswa PGMI Indonesia yang Ke-7. Bertempat di IAIN Kudus (4-6/8/2023) kegiatan tersebut mengusung Tema “Internalisasi dan Kolaborasi Menuju Mahasiswa PGMI yang Unggul di era Super Smart Society 5.0”. WIJAYATIRTA Terdiri dari PGMI se -Jawa Tengah, DIY, Jawa Timur, Bali, NTT dan NTB yang dihadiri oleh 28 kampus yang memiliki Prodi PGMI seluruh Indonesia.\n\nUcapan selamat datang yang hangat diberikan oleh Rektor IAIN Kudus yang langsung menyambut dan membuka agenda IMPI Musyawarah Wilayah III Wijayatirta.\n\nProf. Dr. H. Abdurrohman Kasdi, Lc., M.Si. menyampaikan bahwa aktifis mahasiswa khususnya PGMI harus menjadi model perubahan dalam pendidikan khususnya di Madrasah Ibtidaiyah.\n\n“Sesuai dengan Mars PGMI aktifis mahasiswa khususnya PGMI harus semangat, ceria dan mampu menghadirkan pendidikan yang menyenangkan.” ucapnya.\nHj. Retno Susilowati, M.Pd sebagai Ketua Program Studi PGMI IAIN Kudus juga memberikan penghargaan yang luar biasa untuk para aktifis mahasiswa yang turut hadir di PGMI IAIN Kudus. Beliau berharap semoga dari Kudus memberikan semangat baru untuk para aktifis pendidikan yang akan merubah arah pandang pendidikan kedepan.\n\n“Semoga PGMI solid menjadi satu kesatuan, antara Dosen, Stake holder, dan Mahasiswa dan maju bersama menghadirkan calon – calon Guru yang profesional, mensukseskan cita-cita bangsa untuk mengembangkan pendidikan yang bermartabat.” pungkasnya.\n\nAdapun perwakilan dari kota Surakarta berasal dari HMPS PGMI IIM Surakarta yaitu Abdul Khaidir Halim dan Marshanda Tasya Kamila (keduanya adalah mahasiswa semester 3) yang merupakan ketua umum dan wakil ketua periode tahun 2023/2024. Semoga kedepan selalu ada perwakilan HMPS PGMI IIM Surakarta yang dikirim sebagai delegasi dengan harapan akan selalu terjalin komunikasi dan mendapat update informasi terkait kegiatan organisasi mahasiswa.', 5, '/api/v1/media/fe731d7d-137b-4e93-9764-67defdc8d3f5', '[\"/api/v1/media/f490fa63-dd95-4236-8042-4a910afc64fc\",\"/api/v1/media/1d8fc29d-ee3b-4d16-a4b1-bce557080938\",\"/api/v1/media/4a3cb355-f40b-433f-be8d-d24a8714904e\",\"/api/v1/media/bb88826c-38a5-4a90-bdc0-a4cae718cf20\"]', 'middle', 1, 0, '2026-11-24 01:22:28', '2026-11-24 01:22:28'),
(9, 'Studi Banding HMPS-PAI ke UIN Raden Mas Said Surakarta', '12 Oktober 2023', 2, 'Studi banding merupakan satu kegiatan yang penting dilakukan sebagai upaya peningkatan kualitas pendidikan dan sarana prasarana di institusi Pendidikan. Pada tanggal 12 Oktober 2023 kemarin,...', 'Studi banding merupakan satu kegiatan yang penting dilakukan sebagai upaya peningkatan kualitas pendidikan dan sarana prasarana di institusi Pendidikan. Pada tanggal 12 Oktober 2023 kemarin, Alhamdulillah, kami dari Himpunan Mahasiswa Program Studi PAI (HMPS PAI) Institut Islam Mamba’ul ‘Ulum Surakarta, telah mengikuti ”Studi Banding HMPS-PAI”. Kegiatan ini dilakukan di Universitas Raden Mas Said Surakarta.\n\nAcara studi banding ini diikuti oleh 4 HMPS dari masing-masing universitas, diantaranya HMPS-PAI Institut Islam Mamba’ul ‘Ulum Surakarta, kemudian HMP-PAI Universitas Muhammadiyah Surakarta, kemudian HMPS-PAI Universitas Islam Negeri Raden Mas Said Surakarta dan terakhir dari HMJ PAI Universitas Wahid Hasyim Semarang. Tujuan dari kunjungan ini adalah untuk menambah wawasan dan pengetahuan yang nantinya bisa diterapkan demi peningkatan mutu, dan perbaikan system.\n\nKegiatan Studi Banding ini berlangsung pada pagi hari, pada jam 07.00 WIB, acara dimulai dengan Pembukaan, pembacaan ayat suci al-qur’an dan menyanyikan lagu Indonesia Raya, kemudian sambutan dari ketua umum masing-masing HMPS-PAI dari tiap universitas dan Koordinator Progam Studi PAI UIN Surakarta, Bapak Kholis Firmansyah S.H.I., M.S.I., kemudian pada jam 09.00 WIB, masing-masing HMPS-PAI menyampaikan program kerja mereka, masing-masing ketua umum ataupun perwakilan dari tiap-tiap HMPS-PAI menjelaskan secara garis besar, program apa saja yang akan dilakukan oleh organisasinya selama 1 periode kedepan. Tak lupa, untuk memberikan angin segar kepada peserta Studi Banding, ada penampilan menarik dari HMPS-PAI UIN Raden Mas Said Surakarta.\n\nKegiatan studi banding kemudian dilanjutkan pada jam 11.00 WIB yakni acara inti kegiatan studi banding, setiap perwakilan divisi dari masing-masing HMPS-PAI memaparkan, menjelaskan progam kerja mereka masing-masing. Dan kegiatan Studi Banding HMPS-PAI ini berakhir pada pukul 13.00 WIB.\n\nNantinya diharapkan, dari kegiatan Studi Banding HMPS-PAI ini adalah lebih menguatkan jaringan kerjasama antar kedua belah pihak terutama dalam peningkatan mutu. Selain itu juga dapat menjadi bahan evaluasi ataupun kesempatan mengembangkan inovasi untuk program kerja mendatang.', 5, '/api/v1/media/d2d2857f-3099-43c6-b88b-fb2fa8bdf79b', '[\"/api/v1/media/6ba0b01c-7ccd-4792-a26c-01d49fc03f06\",\"/api/v1/media/bd385800-aecd-49a1-a8d8-df7072c93b05\"]', 'middle', 1, 0, '2026-11-24 01:29:08', '2026-11-24 01:29:08'),
(11, 'Prodi PIAUD IIM Surakarta Gelar Workshop “Perkembangan Nilai Agama dan Moral Anak Usia Dini” untuk Guru PAUD se-Solo Ray', '6 Desember 2023', 1, 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta kembali mengadakan kegiatan inspiratif berupa Workshop Perkembangan Nilai Agama dan Moral Anak...', 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta kembali mengadakan kegiatan inspiratif berupa Workshop Perkembangan Nilai Agama dan Moral Anak Usia Dini. Acara ini berlangsung pada tanggal  06 November 2023, dan menghadirkan narasumber berkompeten di bidang pendidikan anak usia dini, Leli Fertiliana Dea, M.Pd.\n\nWorkshop yang bertempat di kampus IIM Surakarta ini dihadiri oleh puluhan guru PAUD dari berbagai lembaga pendidikan di Solo Raya. Kegiatan ini bertujuan memberikan pemahaman mendalam serta strategi praktis kepada para guru dalam mengembangkan nilai-nilai agama dan moral pada anak usia dini.\n\nDalam pemaparannya, Leli Fertiliana Dea, M.Pd. menjelaskan bahwa pembentukan nilai agama dan moral pada anak usia dini adalah proses yang sangat penting untuk membangun karakter dan fondasi kehidupan mereka di masa depan. “Usia dini adalah masa emas bagi anak untuk menyerap nilai-nilai kebaikan. Guru memiliki peran besar dalam menanamkan nilai-nilai agama dan moral, melalui teladan dan pendekatan yang sesuai dengan usia anak,” ujarnya.\n\nAcara ini juga dirancang interaktif dengan sesi diskusi dan praktik langsung. Para peserta diajak untuk berdiskusi tentang tantangan yang sering dihadapi dalam mengajarkan nilai agama dan moral, serta mencoba berbagai metode kreatif yang dapat diterapkan di kelas. Salah satu metode yang diperkenalkan adalah pendekatan berbasis cerita dan permainan edukatif yang sesuai dengan perkembangan anak.\n\nKetua Prodi PIAUD IIM Surakarta, Elina Intan Apriliani, S.Pd., M.Pd dalam sambutannya menyampaikan pentingnya peran guru PAUD sebagai garda terdepan dalam pendidikan karakter anak. “Kami berharap workshop ini dapat memberikan bekal yang bermanfaat bagi para guru untuk membangun generasi yang tidak hanya cerdas, tetapi juga berakhlak mulia,” katanya.\n\nAntusiasme peserta terlihat sepanjang acara, terutama pada sesi tanya jawab yang memberikan ruang bagi guru untuk berbagi pengalaman dan bertukar gagasan. Para peserta juga menyampaikan apresiasi terhadap materi yang disampaikan, yang dinilai relevan dan aplikatif dalam praktik sehari-hari.\n\nAcara ditutup dengan penyerahan sertifikat kepada seluruh peserta serta sesi foto bersama narasumber. Workshop ini tidak hanya memberikan ilmu baru bagi para guru, tetapi juga mempererat hubungan antara lembaga pendidikan PAUD di Solo Raya.\n\nDengan suksesnya penyelenggaraan workshop ini, Prodi PIAUD IIM Surakarta semakin menegaskan komitmennya dalam mendukung pengembangan pendidikan anak usia dini berbasis nilai agama dan moral.', 5, '/api/v1/media/d2828647-343c-4311-beb0-f74855ed9e24', NULL, 'bottom', 1, 0, '2026-11-24 02:19:17', '2026-11-24 02:19:17'),
(12, 'Perkuat Pendidikan Anak Usia Dini : Tantangan dan Harapan dari Seminar Nasional & RAT PPIAUD 2024', '3 Mei 2024', 1, 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mamba’ul Ulum Surakarta mengikuti kegiatan Seminar Nasional & Rapat Anggota Tahunan IV PPIAUD Indonesia 2024 yang dilaksanakan...', 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mamba’ul Ulum Surakarta mengikuti kegiatan Seminar Nasional & Rapat Anggota Tahunan IV PPIAUD Indonesia 2024 yang dilaksanakan di Hotel Aryaduta Kota Makassar, 01-03 Mei 2024. Institut Islam Mamba’ul Ulum Surakarta mendelegasikan Ketua Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mamba’ul Ulum, Elina Intan Apriliani untuk mengikuti kegiatan tersebut sebagai salah satu bentuk kewajiban anggota untuk mengukuti RAT PPIAUD 2024.\n\nKegiatan ini merupakan agenda Tahunan IV PPIAUD Indonesia 2024 yang menjadi momen penting bagi Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mamba’ul Ulum Surakarta dan anggota PPIAUD lainnya di seluruh Indonesia. \n\nPerkumpulan Pendidikan Islam Anak Usia Dini atau disingkat PPIAUD merupakan Asosiasi Keilmuan bidang Pendidikan Islam Anak Usia Dini. Organisasi ini telah berbadan hukum berdasarkan Keputusan Menteri Hukum dan Hak Asasi Manusia Republik Indonesia Nomor AHU-0006387.AH.01.07.Tahun 2021 tentang Pengesahan Pendirian Perkumpulan Pendidikan Islam Anak Usia Dini. \n\nSaat ini, jumlah program studi yang tergabung dalam PPIAUD Indonesia sebanyak 164 Program Studi se Indonesia dan ikut hadir dalam kegiatan ini Tahun 2024 ini, RAT PPIAUD Indonesia dilaksanakan selama 3 hari, dimana selain rapat aggota tahunan, juga dilaksanakan seminar nasional bersempena hari Pendidikan Nasional dengan tema “Indonesia Hebat : Meninjau Ulang Peta Jalan Pembangunan Anak Usia Dini Indonesia”. Pada kegiatan seminar, terdapat beberapa narasumber yang mengisi materi, yaitu : Ketua Asosiasi PPIAUD (Dr. NurHamzah, M.Pd.), Direktur Diktis Kemenag RI (Prof. Dr. H. Ahmad ZainulHamdi, M.Ag.), Rektor UIN Alauddin Makassar(Prof. Hamdan Juhannis, Ph.D.), Kadis. Pendidikan danKebudayaan Kabupaten BoltimSulawesi Utara (Yusri DamapoliS.Pd., M.M.) & Prof. Dr. Sigit Purnama, M.Pd. (Kaprodi PIAUD UIN Sunan Kalijaga).\n\nRapat Anggota Tahunan IV Tahun 2024 merupakan kesempatan yang sangat penting untuk menyatukan persepsi dan kesadaran bersama tentang pentingnya berinvestasi dalam pendidikan anak usia dini. \n\nDengan menyamakan persepsi dan kesadaran bersama, para pemangku kepentingan dapat bekerja sama untuk menciptakan lingkungan pendidikan yang mendukung, menyediakan sumber daya yang memadai, dan mengembangkan program-program yang berkualitas untuk anak-anak usia dini.\n\nHarapan besar dalam kegiatan ini adalah untuk menguatkan komitmen peningkatan kesejahteraan AUD melalui pendidikan AUD berkualitas, memantapkan dan menguatkan Perkumpulan Pendidikan Islam Anak Usia Dini sebagai asosiasi keilmuan, menghasilkan Capaian Pembelajaran Lulusan (CPL), BoK dan Bahan Kajian Program Studi Pendidikan Islam Anak Usia Dini S1 yang sudah direvisi, menghasilkan rencana program kerja Perkumpulan Pendidikan Islam Anak Usia Dini tahun 2024, menambah jaringan kerja sama antar Program Studi PIAUD dan lembaga luar negeri serta memunculkan ide, gagasan, pemikiran, dan rekomendasi pengembangan Pendidikan Islam Anak Usia Dini.', 5, '/api/v1/media/d9ced910-2da5-44e7-b944-808c6ab8795d', NULL, 'bottom', 1, 0, '2026-11-24 03:19:06', '2026-11-24 03:19:06'),
(13, 'Pemanfaatan Teknologi Digital dalam Penulisan Karya Sastra dan Artikel Ilmiah dalam Rangka Menuju MBKM', '6 Juni 2024', 1, 'terlaksana Seminar kolaborasi MBKM dengan Tema “Pemanfaatan Teknologi Digital dalam Penulisan Karya Sastra dan Artikel Ilmiah” . Kegiatan ini dihadiri oleh Prof. Dr. H. Fauzi Muharom, M.Ag selaku...', 'terlaksana Seminar kolaborasi MBKM dengan Tema “Pemanfaatan Teknologi Digital dalam Penulisan Karya Sastra dan Artikel Ilmiah” . Kegiatan ini dihadiri oleh Prof. Dr. H. Fauzi Muharom, M.Ag selaku Dekan FIT UIN Raden Mas Said Surakarta beserta jajarannya, Dra. Hj. Nur Hidayah, M.S.I. selaku Dekan Fakultas Tarbiyah IIM Surakarta, Kustiarini, M.Pd. (Koordinator Prodi PGMI FIT UIN Raden Mas Said Surakarta) Dr. Hamdan Husein Batubara, M.Pd.I (Sekprodi PGMI UIN Walisongo Semarang), Lailla Hidayatul Amin, M.Pd.I (Kaprodi IIM Surakarta), serta Dosen dan Mahasiswa yang didelegasikan dalam kegiatan seminar kolaborasi.\n\nSeminar Kolaborasi MBKM ini merupakan bentuk realisasi dari MoU antar Fakultas Tarbiyah nstitut Islam Mamba’ul ‘Ulum Surakarta, Fakultas Ilmu Tarbiyah UIN Raden Mas Said Surakarta dan Prodi PGMI UIN Walisongo dalam rangka meningkatkan mutu dan memperkuat kerjasama kelembagaan. Kegiatan berlangsung di Aula PPG FIT UIN Raden Mas Said dengan narasumber di antaranya: Ilzamha Hadijah Rusdan, M.Sc. (UIN Raden Mas Said Surakarta), Achmad Muchamad Kamil, M.Pd. (UIN Walisongo Semarang), dan Alfian Eko Rochmawan, M.Pd.I (IIM Surakarta).\n\nTema yang diangkat sangat relevan dengan kebutuhan mahasiswa dan dapat diaplikasikan dalam menyelesaikan tugas akhir. Di mana teknologi digital hari ini memainkan peran yang signifikan dalam memajukan dunia. Melalui kolaborasi seminar ini, diskusi hingga pemaparan presentasi dapat dipahami peserta betapa pentingnya pemanfaatan teknologi digital dalam menciptakan karya sastra dan artikel ilmiah yang inovatif dan berkualitas. Besar membawa harapan dapat memberikan wawasan baru dan inspirasi bagi dosen dan mahasiswa untuk mengembangkan karyanya dengan memanfaatkan teknologi digital secara optimal.', 5, '/api/v1/media/e5109fb9-76f9-450a-a44f-2108f9ba2f5b', '[\"/api/v1/media/d29d9408-cb20-4e7b-a07a-7b1205a6214c\"]', 'bottom', 1, 0, '2026-11-24 03:26:10', '2026-11-24 03:26:10'),
(14, 'Workshop Redesain Kurikulum Program Studi Pendidikan Islam Anak Usia Dini Berbasis Outcome-Based Education (OBE)', '11 Juli 2024', 1, 'Universitas Islam Nusantara Sunan Kalijaga Yogyakarta sukses menggelar Workshop Redesain Kurikulum Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) berbasis Outcome-Based Education (OBE) pada...', 'Universitas Islam Nusantara Sunan Kalijaga Yogyakarta sukses menggelar Workshop Redesain Kurikulum Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) berbasis Outcome-Based Education (OBE) pada tanggal 11-12 Juli 2024. Acara ini berlangsung di Hotel Grand Rohan Jogja, Jalan Janti – Gedongkuning No.336, Banguntapan, Bantul, D.I. Yogyakarta, dengan dihadiri oleh para akademisi dan praktisi pendidikan dari berbagai perguruan tinggi.\n\nWorkshop ini bertujuan untuk menyusun kurikulum yang relevan dan adaptif sesuai dengan tuntutan zaman serta kebutuhan dunia kerja, khususnya dalam pendidikan Islam untuk anak usia dini. Pendekatan OBE dipilih untuk memastikan bahwa kurikulum yang dikembangkan berfokus pada capaian pembelajaran yang jelas, terukur, dan berorientasi pada hasil (outcomes).\n\nSalah satu yang menjadi sorotan dalam kegiatan ini adalah keterlibatan Ketua Program Studi Pendidikan Islam Anak Usia Dini dari Institut Islam Mambaul Ulum Surakarta, Elina Intan Apriliani, S.Pd., M.Pd. Sebagai alumni Universitas Islam Nusantara Sunan Kalijaga Yogyakarta, beliau diundang secara khusus untuk bergabung dalam tim pengembang kurikulum. Partisipasi beliau menjadi bukti kontribusi alumni dalam mendukung kemajuan institusi almamater dan pendidikan secara umum.\n\n“Workshop ini merupakan langkah strategis untuk menciptakan kurikulum yang tidak hanya relevan secara akademik, tetapi juga memberikan dampak nyata bagi perkembangan pendidikan Islam anak usia dini. Outcome-Based Education menjadi landasan penting dalam merancang capaian pembelajaran yang sesuai dengan kebutuhan generasi masa depan,” ungkap Elina Intan Apriliani.\n\nSelama dua hari pelaksanaan, para peserta workshop terlibat aktif dalam diskusi, presentasi, dan sesi brainstorming untuk mengidentifikasi kebutuhan kurikulum, menentukan profil lulusan, serta menyusun matriks capaian pembelajaran. Selain itu, tim juga membahas implementasi teknologi dalam pembelajaran dan pengintegrasian nilai-nilai keislaman dalam kurikulum berbasis OBE.', 5, '/api/v1/media/5be1a8c6-7e8d-4de6-97c5-7ffd1161a1c0', NULL, 'bottom', 1, 0, '2026-11-24 03:28:22', '2026-11-24 03:28:22'),
(15, 'Mukernas PD-PGMI Indonesia ke-10: Sinergi untuk Pendidikan Berkualitas', '18 Juli 2024', 1, 'Lailla Hidayatul Amin, M.Pd.I., CLSP., CBPA dari Institut Islam Mamba’ul ‘Ulum Surakarta turut serta dalam mendukung keberhasilan Mukernas (Musyawarah Kerja Nasional) PD-PGMI Indonesia ke-10 yang...', 'Lailla Hidayatul Amin, M.Pd.I., CLSP., CBPA dari Institut Islam Mamba’ul ‘Ulum Surakarta turut serta dalam mendukung keberhasilan Mukernas (Musyawarah Kerja Nasional) PD-PGMI Indonesia ke-10 yang diselenggarakan oleh Prodi PGMI UIN Raden Intan Lampung. Acara ini resmi dibuka pada Kamis, 18 Juli 2024, oleh Wakil Rektor Bidang I UIN Raden Intan Lampung, Prof. Dr. H. Alamsyah, M.Ag., dengan dihadiri 119 peserta dari 80 Program Studi Pendidikan Guru Madrasah Ibtidaiyah (PGMI) dari seluruh Indonesia.\n\nDalam sambutannya, Prof. Alamsyah menyampaikan rasa terima kasihnya atas pelaksanaan mukernas yang berfokus pada pemutakhiran kurikulum PGMI berbasis Outcome-Based Education (OBE) dan implementasi Permendikbud-Ristek No. 53 Tahun 2023. Beliau menegaskan bahwa pembaruan kurikulum ini sangat penting untuk menghadapi tantangan revolusi industri 4.0 dan mempersiapkan diri menuju masyarakat 5.0. Prof. Alamsyah berharap kegiatan ini tidak hanya menjadi acara seremonial, tetapi juga menghasilkan solusi konkret untuk kemajuan pendidikan di Indonesia.\n\nHari pertama Mukernas dimeriahkan dengan Seminar Nasional bertajuk “Peran Penting Kurikulum OBE Prodi PGMI Merujuk Permendikbud-Ristek Nomor 53 Tahun 2023 untuk Akreditasi LAMDIK (Lembaga Akreditasi Mandiri Kependidikan)”. Seminar ini menampilkan Prof. Dr. H. Fauzan, M.A., sebagai pembicara utama, yang dikenal sebagai pakar kurikulum pendidikan. Diskusi yang dipandu oleh Dr. Sigit Dwi Laksono, M.Pd., dosen Prodi PGMI FAI Universitas Muhammadiyah Ponorogo, membahas pentingnya adaptasi kurikulum OBE untuk meningkatkan kualitas dan akreditasi pendidikan PGMI di Indonesia. Kegiatan ini juga dilanjutkan dengan penandatanganan perjanjian kerjasama antara Prodi PGMI IIM Surakarta dengan beberapa perguruan tinggi lainnya, seperti UIN Raden Intan Lampung, IAIN Curup, Universitas Islam An Nur Lampung, dan UNU Purwokerto.\n\nAntusiasme dosen, akademisi, dan praktisi pendidikan dalam Mukernas ini mencerminkan komitmen kuat untuk memajukan kurikulum PGMI yang lebih relevan dan responsif terhadap perubahan zaman. Kolaborasi antara berbagai perguruan tinggi diharapkan membawa dampak positif yang signifikan bagi peningkatan mutu pendidikan dasar Islam di Indonesia.\n\nMukernas PD-PGMI Indonesia ke-10 diharapkan menjadi momen penting untuk membawa perubahan signifikan dalam dunia pendidikan, khususnya pada Program Studi PGMI. Dengan pemutakhiran kurikulum berbasis OBE dan implementasi Permendikbud-Ristek No. 53 Tahun 2023, para peserta berkomitmen untuk menciptakan kurikulum yang tidak hanya memenuhi standar akreditasi LAMDIK, tetapi juga mampu menghasilkan lulusan yang siap menghadapi tantangan global. Semangat dan optimisme yang terpancar selama tiga hari kegiatan ini menjadi langkah awal menuju pendidikan berkualitas di Indonesia.', 5, '/api/v1/media/84214e83-c44f-42d8-a519-b966d6e2f794', '[\"/api/v1/media/73028d63-4dcd-4aac-b9c4-1d327a4c1d6b\",\"/api/v1/media/e2ad981d-e889-438e-9e24-302402482da9\",\"/api/v1/media/95365ebe-7401-4e4b-b36d-d2f2aff71876\",\"/api/v1/media/7291c99a-fff5-4c4d-aefc-15b6bdbeb6b4\"]', 'bottom', 1, 0, '2026-11-24 03:29:51', '2026-11-24 03:29:51'),
(16, '258 Mahasiswa Baru Iim Surakarta Ikuti Mastaka 2024, Untuk Pengenalan Kampus Dan Pengkaderan Ormawa', '1 September 2024', 1, 'Institut Islam Mambaul Ulum (IIM) Surakarta menggelar kegiatan Masa Ta’aruf dan Keakraban (MASTAKA) 2024 bagi 214 mahasiswa baru. Acara yang berlangsung selama tiga hari ini dirancang sebagai...', 'Institut Islam Mambaul Ulum (IIM) Surakarta menggelar kegiatan Masa Ta’aruf dan Keakraban (MASTAKA) 2024 bagi 214 mahasiswa baru. Acara yang berlangsung selama tiga hari ini dirancang sebagai ajang pengenalan kampus sekaligus sarana pengkaderan Organisasi Mahasiswa (ORMAWA).\n\nMASTAKA 2024 dilaksanakan dengan format yang unik, yaitu satu hari di kampus pusat IIM Surakarta dan dua hari di Bumi Perkemahan Wahana New Sekipan Kalisoro Tawangmangu. Kegiatan ini menggabungkan unsur akademik, sosial, dan petualangan alam untuk memberikan pengalaman komprehensif bagi para mahasiswa baru.\n\nMukhlis FR, S.Ag. M.S.I., Wakil Rektor Bidang III Kemahasiswaan IIM Surakarta, menjelaskan, “MASTAKA bukan sekadar orientasi biasa. Ini adalah proses ta’aruf yang mendalam, di mana mahasiswa tidak hanya mengenal kampus, tetapi juga values dan semangat yang kami usung di IIM Surakarta.”\n\nBeberapa highlight dari kegiatan MASTAKA 2024 meliputi:\n\nHari Pertama (Kampus Pusat):\n\nPengenalan visi, misi, dan fasilitas kampus\nDiskusi Wawasan Kebangsaan\nKuliah umum dari pimpinan IIM Surakarta, akademik, Sarana Prasarana, Anggaran dan Sumber Daya manusia\nPelayanana adminitrasi akademik dan kemahasiswaan\nHari Kedua dan Ketiga (Bumi Perkemahan Wahana New Sekipan):\n\nOutbound dan team building\nSesi motivasi dan leadership\nPengenalan dan simulasi kegiatan ORMAWA\nMalam keakraban dan api unggun\nKegiatan ini menghadirkan narasumber dari internal IIM Surakarta maupun eksternal. “Kami mengundang para praktisi, motivator, Universitas Sebelas Maret dan Praktisi, salah satu Intitusi Pamerintah dalam hal ini Kesbanpol Kota Surakarta, Daryono, SE selaku Kabid Kesbangpol dalam uraian materinya tantangan kontemporer dalam pengamalan Pancasila. “Globalisasi dan revolusi digital membawa tantangan baru bagi implementasi Pancasila. Kita melihat meningkatnya polarisasi di media sosial, penyebaran informasi yang tidak bertanggung jawab, dan erosi nilai-nilai kebangsaan. Merawat Pancasila berarti juga menjaga ruang digital kita agar tetap sehat dan produktif,” jelasnya.\n\nSalah satu peserta, Ahmad (18), mahasiswa baru Fakultas Tarbiyah Prodi PAI, mengungkapkan antusiasmenya, “MASTAKA memberi kami kesempatan untuk mengenal kampus dan teman-teman baru dalam suasana yang menyenangkan. Saya jadi lebih bersemangat untuk memulai perkuliahan.”\nSementara itu, Ketua Badan Eksekutif Mahasiswa (BEM) IIM Surakarta, Rozin Arfianto, menekankan pentingnya MASTAKA untuk pengkaderan ORMAWA. “Melalui kegiatan ini, kami bisa mengenalkan berbagai organisasi mahasiswa dan menjaring bibit-bibit unggul untuk menjadi kader ORMAWA ke depannya,” ujarnya.\n\nDrs. H. Syamsudin, M.S.I., Ketua Senat IIM Surakarta, dalam sambutannya di hadapan mahasiswa baru dan rektor terpilih menyatakan, “MASTAKA bukan hanya tentang pengenalan kampus kepada mahasiswa baru, tapi juga momen penting bagi kita semua untuk meneguhkan komitmen dalam mewujudkan visi IIM Surakarta sebagai pusat keunggulan pendidikan tinggi Islam.”\n\nRektor Terpilih IIM Surakarta, Edy Muslimin, S.Ag. M.S.I., dalam sambutannya menyampaikan harapan agar MASTAKA dapat menjadi langkah awal yang baik bagi mahasiswa baru. “Semoga melalui MASTAKA ini, kalian tidak hanya siap secara akademis, tetapi juga memiliki semangat untuk berkontribusi aktif dalam kehidupan kampus dan masyarakat, mengutip Pernyataan pidato Bung Karno, “Berikan aku 10 pemuda, niscaya akan kuguncangkan dunia,” mengandung makna yang mendalam dan masih relevan hingga saat ini. Mari kita uraikan beberapa aspek penting dari ungkapan ini Kekuatan Pemuda, Bung Karno menekankan potensi luar biasa yang dimiliki oleh pemuda/mahasiswa. Ia percaya bahwa energi, idealisme, dan semangat pemuda atau mahasiswa dapat menjadi kekuatan penggerak perubahan yang signifikan” pesannya.\n\nKegiatan MASTAKA ditutup oleh Wakil Rektor Bidang Akademik Dr. Joko Subando, M.Pd. seklaigus memberikan arahandan berharap 258 mahasiswa baru IIM Surakarta telah siap untuk memulai perjalanan akademik mereka dengan semangat keislaman, keilmuan, dan kebangsaan yang menjadi ciri khas IIM Surakarta. Seusuai dengan tema Integrasi ilmu dan spiritual mewujudkan generasi rahmatan lil’alamin. Ujarnya.', 5, '/api/v1/media/e0aaf234-8bb6-465c-95ea-f97a4f155b8f', '[\"/api/v1/media/460fde25-19ed-4ca6-b3f9-0efa4e73e1ce\"]', 'bottom', 1, 0, '2026-11-24 03:32:10', '2026-11-24 03:32:10');
INSERT INTO `testimonials` (`id`, `name`, `job_title`, `category_id`, `quote`, `full_content`, `rating`, `avatar_url`, `gallery_urls`, `slideshow_position`, `is_visible`, `sort_order`, `created_at`, `updated_at`) VALUES
(17, 'PIAUD IIM Surakarta menjalin kerja sama dengan STAIN Sultan Abdurrahman Kepulauan Riau', '8 Mei 2025', 1, 'Dalam upaya memperkuat jejaring akademik dan meningkatkan kualitas pendidikan, Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta menjalin kerja...', 'Dalam upaya memperkuat jejaring akademik dan meningkatkan kualitas pendidikan, Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta menjalin kerja sama resmi dengan Sekolah Tinggi Agama Islam Negeri (STAIN) Sultan Abdurrahman Kepulauan Riau.\n\nPenandatanganan Memorandum of Understanding (MoU) dilaksanakan oleh Dekan Fakultas Tarbiyah IIM Surakarta, Dr. H. Muhammad Ja’far Nashir, S.Ag., M.Ag., bersama Zulfadhly Mukhtar, M.Pd., selaku perwakilan dosen dari STAIN Sultan Abdurrahman Kepulauan Riau. Kerja sama ini mencakup berbagai aspek pengembangan akademik, seperti pertukaran dosen dan mahasiswa, kolaborasi dalam penelitian dan publikasi ilmiah, penyelenggaraan seminar dan pelatihan bersama, serta kegiatan pengabdian kepada masyarakat di bidang Pendidikan Islam Anak Usia Dini.\n\nDalam sambutannya, Dr. H. Muhammad Ja’far Nashir menyampaikan harapannya bahwa kerja sama ini dapat menjadi langkah strategis dalam peningkatan mutu pendidikan anak usia dini berbasis Islam. “Kami menyambut baik kerja sama ini sebagai bentuk sinergi antar lembaga dalam menjawab tantangan pendidikan anak usia dini yang semakin kompleks,” ujarnya.\n\nSementara itu, Zulfadhly Mukhtar, M.Pd. mengungkapkan bahwa kerja sama ini merupakan wujud nyata komitmen STAIN Sultan Abdurrahman dalam membangun jejaring dengan berbagai institusi pendidikan tinggi Islam di Indonesia. “Kami optimis bahwa kolaborasi ini akan memberikan dampak positif tidak hanya bagi kedua institusi, tetapi juga bagi pengembangan keilmuan PIAUD secara nasional,” ungkapnya.\n\nPenandatanganan MoU ini juga menjadi momentum penting dalam mempererat hubungan kelembagaan antarperguruan tinggi Islam, sekaligus membuka peluang untuk berbagai inisiatif kolaboratif ke depan.', 5, '/api/v1/media/e1134cac-4bd3-4767-a0c4-5304435472c4', '[\"/api/v1/media/bf45267c-00f9-4bf9-a083-d6ef73bcc2d2\",\"/api/v1/media/7bb30ae4-8a00-43e0-bb2d-c6a414f09d27\"]', 'bottom', 1, 0, '2026-11-24 03:38:54', '2026-11-24 03:38:54'),
(18, 'PGMI UIN Banten dan PGMI IIM Surakarta Gelar Seminar Kolaboratif: Perkuat Tradisi Ilmiah Mahasiswa Lewat Penulisan Karya', '4 Juli 2025', 1, 'Suasana hangat penuh semangat menyelimuti aula Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta saat Program Studi PGMI IIM Surakarta menyambut kunjungan akademik dari Program Studi PGMI UIN Sultan...', 'Suasana hangat penuh semangat menyelimuti aula Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta saat Program Studi PGMI IIM Surakarta menyambut kunjungan akademik dari Program Studi PGMI UIN Sultan Maulana Hasanuddin Banten. Kegiatan ini dikemas dalam bentuk seminar kolaborasi pendidikan bertema “Penguatan Penulisan Karya Ilmiah bagi Mahasiswa Pendidikan”, sebagai bentuk sinergi antar perguruan tinggi Islam dalam membangun budaya literasi ilmiah di kalangan mahasiswa.\n\nSebanyak 52 mahasiswa dan 6 dosen pendamping dari UIN Banten disambut hangat oleh tim hadroh IIM Surakarta, menambah nuansa religius dan kekeluargaan dalam kegiatan yang berlangsung pada Jumat pagi, 4 Juli 2025. Turut hadir pimpinan institusi, dosen, dan mahasiswa dari kedua kampus.\n\nAcara dipandu secara khidmat oleh petugas protokoler Viki Bayu Mahendra, M.Pd, yang juga merupakan dosen Fakultas Tarbiyah IIM Surakarta. Pembukaan acara oleh ibu Praptiningsih, M.Pd.I selaku MC diawali dengan menyanyikan lagu Indonesia Raya dan Mars IIM, serta penampilan seni budaya oleh mahasiswa dari kedua kampus.\n\nRektor IIM Surakarta, Bpk. Edi Muslimin, S.Ag., M.Si, membuka kegiatan secara resmi dan menyampaikan sambutan penuh apresiasi atas terselenggaranya kolaborasi ini. Disusul sambutan dari perwakilan Kaprodi PGMI UIN Banten, Ibu Fitri Meiliawati, M.Sn, selaku Sekprodi yang mengungkapkan pentingnya membangun koneksi akademik lintas institusi sebagai bagian dari peningkatan mutu pembelajaran dan publikasi ilmiah mahasiswa.\n\nDalam sesi inti seminar, dua narasumber berbagi wawasan dan pengalaman. Ibu Lailla Hidayatul Amin, M.Pd.I dari IIM Surakarta membahas secara mendalam karakteristik dan pemilihan metode penelitian dalam karya tulis ilmiah, sementara Ibu Imroatun, M.Ag dari UIN Banten menyampaikan materi tentang struktur dan strategi publikasi karya ilmiah mahasiswa. Keduanya berhasil membangkitkan antusiasme peserta melalui diskusi interaktif dan inspiratif.\n\nSeminar ini dimoderatori oleh Ibu Iffah Muhlisah, M.Pd., dosen PGMI IIM Surakarta. Sebagai bentuk apresiasi, panitia menyerahkan sertifikat dan cendera mata kepada para narasumber.\n\nSeluruh rangkaian kegiatan disiapkan dan dilaksanakan oleh mahasiswa BEM Fakultas Tarbiyah IIM Surakarta, yang bertugas sebagai panitia pelaksana. Dengan semangat kolaboratif dan profesionalisme, para mahasiswa berhasil menjalankan tugas dengan baik dan menjadi tuan rumah yang membanggakan.\n\nKegiatan ditutup dengan doa bersama yang dipimpin oleh Bpk. Alfian Eko Rochmawan, M.Pd.I, dan dilanjutkan dengan sesi foto bersama serta ramah tamah antar peserta dan dosen dari kedua institusi.\n\nSeminar kolaborasi ini tidak hanya menjadi ajang bertukar ilmu, tetapi juga mempererat hubungan antarlembaga dalam semangat pengembangan pendidikan Islam yang unggul, ilmiah, dan integratif. Rencana tindak lanjut berupa kerja sama penulisan artikel dan seminar daring bersama pun mengemuka dalam diskusi informal antar dosen setelah acara.', 5, '/api/v1/media/520430ed-bb1b-4822-b59e-2749d0535b76', '[\"/api/v1/media/a4082369-0da0-4465-beda-f7f20d775cd4\",\"/api/v1/media/c833d0f1-78f2-4b7c-9e47-1fd6ad91e56b\"]', 'middle', 1, 0, '2026-11-24 03:42:48', '2026-11-24 03:42:48'),
(19, 'Mahasiswa Prodi PIAUD IIM Surakarta Gelar Drama Musikal Bersama Anak RA Amanah Ummah', '22 Juli 2025', 1, 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mambaul Ulum (IIM) Surakarta sukses menggelar kegiatan Drama Musikal yang melibatkan mahasiswa dan anak-anak dari RA Amanah...', 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mambaul Ulum (IIM) Surakarta sukses menggelar kegiatan Drama Musikal yang melibatkan mahasiswa dan anak-anak dari RA Amanah Ummah Surakarta. Kegiatan ini merupakan bagian dari implementasi mata kuliah Pendidikan Seni untuk Anak Usia Dini yang diampu oleh dosen Elina Intan Apriliani, M.Pd.\n\nDrama musikal ini tidak hanya menjadi ajang unjuk kreativitas mahasiswa, namun juga menjadi sarana interaksi edukatif antara mahasiswa dan anak-anak usia dini. Berbagai cerita anak yang mendidik dibawakan dengan konsep teater musikal, lengkap dengan kostum, musik, gerak, dan tari yang menarik perhatian anak-anak.\n\nDalam sambutannya, Elina Intan Apriliani, M.Pd. menyampaikan bahwa kegiatan ini bertujuan untuk melatih mahasiswa dalam mengembangkan kreativitas seni sekaligus mempraktikkan metode pembelajaran yang sesuai untuk anak usia dini. “Melalui drama musikal, mahasiswa tidak hanya belajar teori, tapi juga langsung menerapkan pendekatan bermain dan berkesenian yang menyenangkan bagi anak-anak,” ujarnya.\n\nKegiatan ini disambut antusias oleh para guru dan anak-anak dari RA Amanah Ummah. Anak-anak terlihat sangat menikmati pertunjukan, bahkan beberapa di antaranya ikut menari dan bernyanyi bersama para mahasiswa.\n\nKepala Prodi PIAUD IIM Surakarta mengapresiasi terselenggaranya kegiatan ini sebagai bentuk nyata sinergi antara kampus dan lembaga pendidikan anak usia dini. “Kegiatan seperti ini memperkuat kompetensi mahasiswa sekaligus menjadi kontribusi positif bagi dunia pendidikan anak,” tuturnya.\n\nDrama musikal ini menjadi bukti komitmen Prodi PIAUD IIM Surakarta dalam menciptakan calon pendidik anak usia dini yang kreatif, inovatif, dan berjiwa seni.', 5, '/api/v1/media/ab02074a-9ba7-4ea6-ba37-2f16bbaa5b2e', NULL, 'bottom', 1, 0, '2026-11-24 03:43:20', '2026-11-24 03:43:20'),
(20, 'Tiga Dosen IIM Surakarta Ikuti Pelatihan Peningkatan Kompetensi Dosen Pemula (PKDP)', '5 Agustus 2025', 1, 'Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta kembali menorehkan langkah strategis dalam penguatan mutu sumber daya manusia. Tiga dosen dari berbagai fakultas di IIM Surakarta mengikuti kegiatan...', 'Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta kembali menorehkan langkah strategis dalam penguatan mutu sumber daya manusia. Tiga dosen dari berbagai fakultas di IIM Surakarta mengikuti kegiatan Peningkatan Kompetensi Dosen Pemula (PKDP) yang diselenggarakan oleh Pusat Pengembangan Pendidikan (PTP) UIN Raden Mas Said Surakarta, bekerja sama dengan Direktorat Jenderal Pendidikan Islam, Kementerian Agama RI.\n\nPelatihan ini dilaksanakan selama enam hari, sejak 28 Juli hingga 2 Agustus 2025, dengan dua hari pelatihan luring yang bertempat di Hotel Syariah Solo, dan empat hari pelatihan daring yang diikuti secara aktif oleh para peserta.\n\nAdapun tiga dosen IIM Surakarta yang mengikuti kegiatan tersebut adalah:\n\n– Ibu Izzun Khoirun Nissa, SE., MEK (Fakultas Syariah dan Ekonomi Islam)\n\n– Bapak Ngatmin Abbas, M.PI., M.Pd (Fakultas Tarbiyah)\n\n– Bapak Fatchurrohman, M.Ag (Fakultas Dakwah dan Komunikasi)\n\nKetiganya menunjukkan antusiasme dan dedikasi tinggi dalam mengikuti setiap sesi pelatihan, yang meliputi materi strategis seperti metode pembelajaran aktif, riset integratif, penguatan kepribadian akademik, serta pengembangan karier dosen berbasis tridarma perguruan tinggi.\n\n“Kegiatan PKDP ini sangat bermanfaat dalam membentuk mindset dosen pemula yang reflektif dan adaptif, khususnya dalam mendesain pembelajaran yang transformatif,” ungkap salah satu peserta saat diwawancarai seusai sesi pelatihan daring.\n\nPihak IIM Surakarta menyampaikan apresiasi kepada penyelenggara dan mengharapkan kegiatan semacam ini dapat terus berlanjut untuk mendukung pengembangan kapasitas dosen muda secara berkelanjutan.\n\nMelalui partisipasi aktif dalam program nasional ini, IIM Surakarta menegaskan komitmennya untuk terus meningkatkan mutu tenaga pendidik sebagai langkah nyata mewujudkan visi kampus: “World Class Islamic Institute”.', 5, '/api/v1/media/0401da2c-5ffd-4e9f-8b57-b5d97188b9e1', NULL, 'bottom', 1, 0, '2026-11-24 03:44:22', '2026-11-24 03:44:22'),
(21, 'IIM Surakarta Gelar Workshop Laporan Pertanggungjawaban Fakultas dan Lembaga Tahun 2024', '6 Agustus 2025', 1, 'Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta menyelenggarakan Workshop Laporan Pertanggungjawaban Fakultas dan Lembaga Tahun 2024 bertempat di Ruang Pascasarjana Lantai 1. Kegiatan ini diikuti...', 'Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta menyelenggarakan Workshop Laporan Pertanggungjawaban Fakultas dan Lembaga Tahun 2024 bertempat di Ruang Pascasarjana Lantai 1. Kegiatan ini diikuti oleh seluruh pimpinan fakultas, sekolah pascasarjana, serta pimpinan lembaga di lingkungan IIM Surakarta, 6 Agustus 2025.\n\nAcara workshop dibuka secara resmi oleh Edy Muslimin, S.Ag, M.S.I, Rektor Institut Islam Mambau’ul ’Ulum Surakarta dengan penekanan pentingnya akuntabilitas, transparansi, dan profesionalitas dalam tata kelola perguruan tinggi. Workshop ini menjadi forum strategis bagi pimpinan fakultas dan lembaga untuk menyampaikan capaian program kerja, evaluasi kinerja, serta perencanaan pengembangan di tahun mendatang.\n\n\nDr. Joko Subando, M.Pd. Selaku Warek 1 Bidang Akademik mengatakan Melalui forum ini, kita berharap dapat memperoleh gambaran menyeluruh mengenai capaian akademik, penelitian, pengabdian masyarakat, serta penguatan mutu yang telah dilakukan selama tahun 2024. Selain itu, laporan ini akan menjadi tolak ukur keberhasilan sekaligus pijakan bagi peningkatan kualitas IIM Surakarta di masa mendatang. tegasnya\n\nPemaparan laporan dimulai dari Fakultas Syariah dan Ekonomi Islam, disampaikan Dr. H. Isfihani, M.Ag, Selaku Dekan yang menyoroti peningkatan mutu akademik, penguatan kerja sama mitra, serta pengembangan program studi berbasis kebutuhan masyarakat. Selanjutnya, Mukhlis FR, S.Ag, M.S.I Plt. Dekan Fakultas Dakwah dan Komunikasi Penyiaran Islam menyampaikan capaian di bidang dakwah digital, publikasi ilmiah, dan penguatan literasi keagamaan di masyarakat.\n\nBerikutnya, Dekan Fakultas Tarbiyah Dr. HM. Jafar Nashir, M.Ag. memaparkan hasil capaian pada peningkatan kualitas pembelajaran, inovasi kurikulum, serta kegiatan pengembangan dosen dan mahasiswa. Dr. Sukari, M.Pd.I, Direktur Sekolah Pascasarjana melaporkan perkembangan akademik, kolaborasi riset, dan penguatan jejaring internasional.\n\n\nSelain fakultas, workshop juga diisi dengan laporan dari Lembaga Penelitian dan Pengabdian kepada Masyarakat (LPPM) Drs. Arif Effendi, M.H. yang menekankan peningkatan jumlah riset dan kegiatan pengabdian berbasis kebutuhan masyarakat. Kemudian, Septian Nur Ika T, M.Pd, Kepala Lembaga Penjaminan Mutu (LPM) menyampaikan evaluasi terhadap standar mutu akademik dan non-akademik yang telah dilaksanakan selama tahun 2024.\n\nDalam sambutannya, pimpinan IIM Surakarta memberikan apresiasi kepada seluruh fakultas dan lembaga yang telah melaksanakan tugas dengan penuh tanggung jawab. “Laporan pertanggungjawaban ini menjadi tolok ukur keberhasilan kinerja kita di tahun 2024 sekaligus pijakan untuk perbaikan dan penguatan program kerja di tahun berikutnya,” tegasnya.\n\nWorkshop ini ditutup dengan sesi diskusi dan masukan dari peserta, sehingga diharapkan mampu menghasilkan rekomendasi strategis untuk meningkatkan mutu akademik, tata kelola kelembagaan, serta kontribusi nyata IIM Surakarta dalam bidang pendidikan, penelitian, dan pengabdian kepada masyarakat.', 5, '/api/v1/media/f8dd753a-cb8a-458f-9b3e-277bde4cb254', NULL, 'bottom', 1, 0, '2026-11-24 03:45:35', '2026-11-24 03:45:35'),
(22, 'Sosialisasi Visi, Misi, Tujuan dan Strategi di Fakultas Syariah dan Ekonomi Islam IIM Surakarta', '11 September 2025', 1, 'Dalam rangka memperkuat pemahaman dan komitmen bersama terhadap arah pengembangan institusi, Fakultas Syariah dan Ekonomi Islam (FSEI) Institut Ilmu Islam dan Masyarakat (IIM) Surakarta...', 'Dalam rangka memperkuat pemahaman dan komitmen bersama terhadap arah pengembangan institusi, Fakultas Syariah dan Ekonomi Islam (FSEI) Institut Ilmu Islam dan Masyarakat (IIM) Surakarta menyelenggarakan kegiatan Sosialisasi Visi, Misi, Tujuan, dan Strategi (VMTS) pada Selasa (09/09) di ruang Zoom Meeting.\n\nKegiatan ini dihadiri oleh dosen, tenaga kependidikan, perwakilan mahasiswa, serta para stakeholder internal fakultas. Hadir pula Dekan FSEI, Dr. H. Isfihani, M.Ag., yang sekaligus membuka dan memberikan sambutan dalam acara tersebut.\n\n“Sosialisasi ini bukan sekadar formalitas, melainkan upaya kita bersama untuk menyatukan visi dalam membangun Fakultas Syariah dan Ekonomi Islam yang unggul dan berdaya saing, baik di tingkat nasional maupun internasional,” ujar Dr. Isfihani, M.Ag dalam sambutannya.\n\nPemaparan Visi dan Strategi Pencapaian\nDalam pemaparannya, Wakil Dekan Bidang Akademik, Izzun Khoirun Nissa, SE., MEK., AWP menjelaskan bahwa Visi FSEI IIM Surakarta adalah “Menjadi Fakultas yang Unggul dalam penyelenggaraan tridharma Perguruan Tinggi bidang Hukum Keluarga dan Ekonomi berbasis Islam Rahmatan Lil’alamin di tahun 2035.”\n\nMisi fakultas mencakup Menyelenggarakan pembelajaran guna membentuk mahasiswa yang memiliki kedalaman spiritual, keluhuran akhlak dan keluasan ilmu, Mengembangkan ketrampilan dalam penerapan teori hukum keluarga dan Ekonomi Islam, Melakukan Penelitian dan Pengabdian dalam bidang Hukum Keluarga dan Ekonomi Islam.\n\nKomitmen Bersama Sivitas Akademika, salah satu sesi menarik dalam kegiatan ini adalah penandatanganan komitmen bersama dari seluruh elemen fakultas. Perwakilan dosen, mahasiswa, dan tendik secara simbolis menandatangani spanduk VMTS sebagai bentuk dukungan dan partisipasi aktif dalam mewujudkan cita-cita fakultas.\n\nKegiatan sosialisasi ini juga dilengkapi dengan sesi diskusi interaktif, di mana peserta menyampaikan masukan dan harapan terkait implementasi strategi fakultas di masa mendatang.\n\nDengan terselenggaranya kegiatan ini, FSEI IIM Surakarta berharap seluruh sivitas akademika memiliki persepsi yang selaras terhadap arah dan kebijakan pengembangan fakultas. Kegiatan ini juga menjadi bagian dari penguatan tata kelola institusi serta salah satu upaya persiapan akreditasi program studi dan fakultas.', 5, '/api/v1/media/d12d8752-e9b5-4668-8d76-302c420c6b27', NULL, 'bottom', 1, 0, '2026-11-24 03:47:30', '2026-11-24 03:56:10'),
(23, 'Program Studi PIAUD Institut Islam Mambaul Ulum Surakarta Gelar Sarasehan Bersama Mahasiswa dan Dosen', '30 Oktober 2025', 1, 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mambaul Ulum Surakarta menyelenggarakan sarasehan pada Senin, 30 September 2025, bertempat di laboratorium Prodi PIAUD IIM...', 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mambaul Ulum Surakarta menyelenggarakan sarasehan pada Senin, 30 September 2025, bertempat di laboratorium Prodi PIAUD IIM Surakarta. Acara dimulai pukul 13.00 WIB hingga selesai dan dihadiri oleh mahasiswa serta dosen PIAUD.\n\nKegiatan ini dibuka dengan sambutan dari Dekan Fakultas Tarbiyah, Dr. M. Jafar Nashir, M.Ag, yang menekankan pentingnya kegiatan akademik dan nonakademik sebagai ruang silaturahmi, diskusi, dan penguatan visi keilmuan di lingkungan kampus.\n\nSambutan berikutnya disampaikan oleh Ketua Program Studi PIAUD, Iffah Mukhlisah, M.Pd, yang mengapresiasi kehadiran seluruh mahasiswa dan dosen. Beliau juga menekankan bahwa sarasehan ini menjadi momen penting untuk menyatukan komitmen dalam mengembangkan mutu pendidikan anak usia dini, khususnya di bawah naungan Prodi PIAUD.\n\nSarasehan berlangsung hangat dengan dialog interaktif antara mahasiswa dan dosen. Berbagai aspirasi, gagasan, serta rencana pengembangan kegiatan akademik maupun organisasi mahasiswa PIAUD dibahas dalam forum tersebut.\n\nDengan adanya kegiatan ini, diharapkan terjalin komunikasi yang lebih erat antara mahasiswa dan dosen, serta tercipta suasana akademik yang kondusif, kolaboratif, dan mendukung tercapainya tujuan pendidikan di Institut Islam Mambaul Ulum Surakarta.', 5, '/api/v1/media/3a5ae9f5-11a4-4a8d-b1b7-0969d3830616', NULL, 'bottom', 1, 0, '2026-11-24 03:52:38', '2026-11-24 03:55:30'),
(24, 'Penguatan Implementasi SPMI, Institut Islam Mamba’ul Ulum Surakarta Kirim GPM Ikuti Pelatihan Audit Mutu Internal (AMI)', '14 November 2025', 1, 'Institut Islam Mamba’ul Ulum Surakarta melalui Lembaga Penjamin Mutu (LPM) menugaskan Praptiningsih, M.Pd.I, yang merupakan anggota Gugus Penjamin Mutu (GPM) Fakultas Tarbiyah, untuk...', 'Institut Islam Mamba’ul Ulum Surakarta melalui Lembaga Penjamin Mutu (LPM) menugaskan Praptiningsih, M.Pd.I, yang merupakan anggota Gugus Penjamin Mutu (GPM) Fakultas Tarbiyah, untuk berpartisipasi dalam Pelatihan Audit Mutu Internal (AMI). Pelatihan ini diselenggarakan oleh Best-Q Institut pada tanggal 14–16 November 2025 secara daring melalui Zoom Meeting, berlangsung dari pukul 08.00 hingga 16.00 WIB.\n\nAcara ini menghadirkan enam narasumber ahli, di antaranya Yunuf Nalim, M.Si, Prof. Dr. H. Fajri Ismail, M.Pd.I, Helmi Syaifuddin, M.Fi.L.I, Prof. Dr. Muh Nasriruddin, M.Ag, Roshihan Aslihudin, M.A.B, dan Dr. Indrawati, M.Pd., dengan Hadi Putra sebagai moderator. Materi yang diterima Praptiningsih meliputi pedoman AMI sesuai regulasi pemerintah, peningkatan kompetensi dan teknik auditor (termasuk audit dokumen dan lapangan), praktik simulasi audit, serta cara menyusun formulir dan laporan AMI berbasis standar. Selain itu, peserta juga mendapatkan informasi terkini mengenai kebijakan pemerintah terkait penjaminan mutu dan akreditasi perguruan tinggi.\n\nPelatihan ini bertujuan untuk memperkuat penerapan Sistem Penjaminan Mutu Internal (SPMI) di Institut Islam Mamba’ul Ulum Surakarta dan meningkatkan kemampuan profesional auditor internal demi tercapainya peningkatan mutu yang berkelanjutan.', 5, '/api/v1/media/0ad95246-ac0f-46ae-b7ec-e48b703f71dc', NULL, 'bottom', 1, 0, '2026-11-24 03:55:00', '2026-11-24 03:55:00'),
(25, 'Kaprodi PGMI IIM Surakarta Ikuti Workshop Nasional Penyusunan Laporan Evaluasi CPL Mengacu IAPS LAMDIK 3.0', '2 Maret 2026', 6, 'Dalam rangka memperkuat komunikasi kelembagaan dan membangun sinergi strategis di bidang pendidikan tinggi, jajaran Rektorat Institut Islam Mamba’ul ’Ulum (IIM) Surakarta yang dipimpin langsung...', 'Dalam rangka memperkuat komunikasi kelembagaan dan membangun sinergi strategis di bidang pendidikan tinggi, jajaran Rektorat Institut Islam Mamba’ul ’Ulum (IIM) Surakarta yang dipimpin langsung oleh Rektor, Dr. Edy Muslimin, S.Ag., MSI., melaksanakan kunjungan silaturahmi kepada Dr. Abdul Kharis Almasyhari, anggota Dewan Perwakilan Rakyat Republik Indonesia (DPR RI) yang juga menjabat sebagai Ketua Fraksi Partai Keadilan Sejahtera (PKS).\n\nKunjungan ini menjadi momentum penting untuk mempererat hubungan silaturahmi sekaligus membuka ruang komunikasi dan kolaborasi antara perguruan tinggi dengan pemangku kebijakan di tingkat nasional, khususnya dalam mendukung pengembangan pendidikan tinggi Islam yang berkualitas, berdaya saing, dan berkontribusi nyata bagi masyarakat.\n\nDalam pertemuan tersebut, Rektor IIM Surakarta, Dr. Edy Muslimin, S.Ag., MSI., menyampaikan pentingnya membangun komunikasi yang konstruktif dengan berbagai elemen bangsa, termasuk para wakil rakyat, guna memperkuat peran perguruan tinggi dalam menjalankan Tridharma Perguruan Tinggi, yang meliputi pendidikan dan pengajaran, penelitian, serta pengabdian kepada masyarakat.\n\nMenurutnya, perguruan tinggi tidak hanya berperan sebagai lembaga penyelenggara pendidikan, tetapi juga memiliki tanggung jawab strategis dalam mencetak sumber daya manusia yang unggul, mengembangkan ilmu pengetahuan, serta menghadirkan solusi atas berbagai persoalan sosial dan keumatan.\n\n“Silaturahmi ini menjadi bagian dari ikhtiar kami untuk memperkuat komunikasi, memperluas jejaring kelembagaan, dan membangun peluang kerja sama yang dapat memberikan manfaat bagi pengembangan pendidikan tinggi, khususnya pendidikan Islam,” demikian pesan yang ingin ditegaskan melalui kunjungan tersebut.\n\nSalah satu agenda penting yang turut disampaikan dalam pertemuan ini adalah ikhtiar pengembangan kelembagaan IIM Surakarta menuju alih status menjadi universitas. Langkah strategis tersebut merupakan bagian dari upaya institusi untuk memperluas kontribusi akademik, meningkatkan kualitas tata kelola, mengembangkan bidang keilmuan, serta memperkuat kapasitas institusi dalam menjawab tantangan pendidikan tinggi pada masa mendatang.\n\nDalam konteks tersebut, jajaran Rektorat IIM Surakarta juga memohon doa dan restu agar proses alih status menuju universitas dapat berjalan lancar, memperoleh kemudahan, serta memenuhi seluruh persyaratan dan ketentuan yang berlaku. Transformasi ini diharapkan menjadi tonggak penting bagi IIM Surakarta untuk terus berkembang sebagai perguruan tinggi Islam yang adaptif, progresif, dan berorientasi pada peningkatan mutu.\n\nKunjungan silaturahmi ini sekaligus menegaskan komitmen IIM Surakarta untuk membangun kemitraan yang lebih luas dengan berbagai pihak, baik pemerintah, legislatif, dunia usaha, lembaga pendidikan, maupun masyarakat. Sinergi lintas sektor diharapkan dapat membuka peluang kolaborasi konkret dalam pengembangan pendidikan, penelitian, publikasi ilmiah, dan program pengabdian kepada masyarakat.\n\nBagi IIM Surakarta, penguatan komunikasi kelembagaan merupakan bagian dari langkah strategis untuk mewujudkan institusi yang semakin maju dan mampu memberikan kontribusi lebih besar bagi umat, bangsa, dan negara. Dengan dukungan serta doa dari berbagai pihak, proses pengembangan institusi diharapkan dapat berjalan optimal dan memberikan dampak positif bagi masa depan pendidikan Islam.\n\nMelalui silaturahmi ini, IIM Surakarta meneguhkan semangat untuk terus bergerak maju, memperkuat kolaborasi, dan mempersiapkan transformasi kelembagaan menuju universitas. Ikhtiar tersebut bukan sekadar perubahan status, melainkan juga komitmen untuk meningkatkan kualitas pendidikan, memperluas manfaat Tridharma Perguruan Tinggi, dan menghadirkan kontribusi yang lebih luas bagi masyarakat.', 5, '/api/v1/media/10e5c42b-7195-4b9c-99c5-fdebaf0a6123', '[\"/api/v1/media/fa0118be-be36-4a6c-a824-82d750a9dc7f\",\"/api/v1/media/fff9dddd-7d32-4621-bf3c-8459d195625e\"]', 'bottom', 1, 0, '2026-11-24 03:59:02', '2026-11-24 03:59:02'),
(26, 'Perkuat Sinergi Pendidikan, Prodi PIAUD IIM Surakarta Berkontribusi Aktif dalam Rakerwil PPIAUD Jawa Tengah dan DIY', '16 April 2026', 1, 'Komitmen untuk memajukan pendidikan anak usia dini terus ditunjukkan oleh Program Studi (Prodi) Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mamba’ul Ulum (IIM) Surakarta. Pada Selasa,...', 'Komitmen untuk memajukan pendidikan anak usia dini terus ditunjukkan oleh Program Studi (Prodi) Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mamba’ul Ulum (IIM) Surakarta. Pada Selasa, 16 April 2026, jajaran pimpinan prodi hadir secara daring untuk mengikuti Rapat Kerja Wilayah (Rakerwil) Perkumpulan Pendidikan Islam Anak Usia Dini (PPIAUD) wilayah Jawa Tengah dan Daerah Istimewa Yogyakarta.\n\nKegiatan yang berlangsung mulai pukul 19.30 WIB ini menjadi ajang strategis bagi para pengelola prodi PIAUD se-Jateng dan DIY untuk merumuskan masa depan organisasi. Dalam forum tersebut, Prodi PIAUD IIM Surakarta diwakili langsung oleh Kaprodi, Iffah Mukhlisah, M.Pd., serta Sekprodi, Elina Intan Apriliani, M.Pd.\n\nMembangun Rancangan Program Berkelanjutan\n\nFokus utama dalam Rakerwil kali ini adalah pembahasan mendalam mengenai rancangan program kerja pengurus wilayah PPIAUD untuk periode mendatang. Iffah Mukhlisah dan Elina Intan Apriliani turut memberikan kontribusi pemikiran yang konstruktif dalam penyusunan agenda-agenda strategis, khususnya yang berkaitan dengan penguatan kemitraan dan kualitas pendidikan.\n\n“Partisipasi aktif dalam Rakerwil ini adalah bentuk nyata keterlibatan IIM Surakarta dalam jaringan akademik yang lebih luas. Kami berharap, program-program yang disusun bersama ini dapat memberikan dampak positif, baik bagi pengembangan kualitas prodi di daerah masing-masing maupun bagi kemajuan PPIAUD secara nasional,” ujar Iffah Mukhlisah.\n\nSinergi untuk Pendidikan Anak Usia Dini Kehadiran prodi dalam forum ini tidak hanya sebatas menghadiri rapat, namun juga mempertegas posisi IIM Surakarta sebagai institusi yang aktif berkolaborasi. Sebagai bukti nyata dedikasi tersebut, nama Kaprodi Iffah Mukhlisah, M.Pd. juga tercatat dalam jajaran pengurus wilayah PPIAUD Jawa Tengah dan DIY periode 2026-2029 pada Bidang Kerjasama Dalam dan Luar Negeri dan Kemitraan.\n\nMelalui sinergi dalam Rakerwil ini, diharapkan PPIAUD Jawa Tengah dan DIY dapat menjadi wadah yang solid bagi para akademisi untuk saling berbagi praktik terbaik, memperkuat riset, serta melakukan pengabdian masyarakat yang inovatif.\n\nLangkah kolaboratif ini menjadi pijakan penting bagi Prodi PIAUD IIM Surakarta untuk terus bertumbuh dan memberikan kontribusi terbaik bagi pengembangan pendidikan Islam anak usia dini di Indonesia, selaras dengan visi institusi untuk menjadi World Class Islamic Institut.', 5, '/api/v1/media/590dd85d-ca15-4eca-873b-ac45eb5ec35e', NULL, 'bottom', 1, 0, '2026-11-24 04:00:00', '2026-11-24 04:00:00'),
(27, 'Prodi PGMI IIM Surakarta Tingkatkan Kapasitas Pengembangan Kurikulum Berbasis OBE', '26 Agustus 2026', 1, 'Program Studi Pendidikan Guru Madrasah Ibtidaiyah (PGMI) Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta terus memperkuat komitmennya dalam meningkatkan kualitas pengelolaan dan pengembangan...', 'Program Studi Pendidikan Guru Madrasah Ibtidaiyah (PGMI) Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta terus memperkuat komitmennya dalam meningkatkan kualitas pengelolaan dan pengembangan kurikulum. Komitmen tersebut diwujudkan melalui keikutsertaan Lailla Hidayatul Amin, S.Pd., M.Pd.I., CLSP., CBPA., selaku perwakilan Prodi PGMI IIM Surakarta dalam kegiatan Workshop Master Kurikulum Berbasis Outcome-Based Education (OBE), RPS OBE, dan Laporan Evaluasi CPL yang diselenggarakan oleh Pengurus Pusat Perkumpulan Dosen Pendidikan Guru Madrasah Ibtidaiyah (PD-PGMI) Indonesia.\n\nKegiatan tersebut dilaksanakan pada 27–29 Agustus 2026 di University Hotel, Yogyakarta. Workshop mengangkat tema “Master Kurikulum OBE Mengacu Permendiktisaintek Nomor 39 Tahun 2025 dan Nomor 10 Tahun 2026.” Kegiatan ini dirancang untuk memberikan pemahaman sekaligus pengalaman praktis kepada peserta dalam menyusun dan mengembangkan dokumen kurikulum berbasis luaran, Rencana Pembelajaran Semester (RPS) berbasis OBE, serta laporan evaluasi Capaian Pembelajaran Lulusan (CPL).\n\nSelama kegiatan, peserta mendapatkan materi yang cukup komprehensif, mulai dari penyusunan visi, misi, tujuan, dan profil lulusan; perumusan CPL dan pemetaan CPL dengan profil lulusan; penyusunan bahan kajian dan pengemasan mata kuliah; penyebaran CPL per mata kuliah dan semester; penyusunan peta kurikulum; hingga penyusunan RPS OBE dan laporan evaluasi CPL.\n\nSalah satu penekanan penting dalam workshop adalah keterkaitan antara profil lulusan, CPL, bahan kajian, mata kuliah, proses pembelajaran, dan asesmen. Materi workshop juga menempatkan evaluasi CPL sebagai bagian penting dalam memastikan ketercapaian kompetensi lulusan. Dalam kegiatan workshop ditegaskan bahwa pengukuran CPL perlu dilakukan secara tepat dan hasilnya ditindaklanjuti untuk perbaikan mutu pembelajaran.\n\nSelain aspek teknis penyusunan dokumen, kegiatan juga menekankan pentingnya Continuous Quality Improvement (CQI) atau peningkatan mutu secara berkelanjutan. Hasil pengukuran capaian pembelajaran diposisikan sebagai dasar empiris bagi dosen dan pengelola program studi untuk melakukan perbaikan pada materi, strategi pembelajaran, maupun fasilitas pendukung.\n\nBagi Prodi PGMI IIM Surakarta, keikutsertaan Lailla Hidayatul Amin dalam workshop ini diharapkan dapat memberikan kontribusi terhadap proses review, pengembangan, dan penyempurnaan kurikulum PGMI agar semakin selaras dengan pendekatan OBE serta tuntutan regulasi dan kebutuhan kompetensi lulusan. Materi workshop juga memberikan penguatan terhadap pemahaman bahwa kurikulum tidak hanya berorientasi pada proses pembelajaran, tetapi harus mampu memastikan luaran dan kompetensi yang dapat ditunjukkan mahasiswa setelah menyelesaikan studi.\n\nKeikutsertaan tersebut sekaligus menjadi bagian dari upaya Prodi PGMI IIM Surakarta untuk terus beradaptasi terhadap dinamika pendidikan tinggi dan tuntutan penjaminan mutu. Dengan pemahaman yang diperoleh melalui workshop, diharapkan proses pengembangan kurikulum, penyusunan RPS, serta evaluasi ketercapaian CPL di lingkungan Prodi PGMI dapat dilakukan secara lebih sistematis, terukur, dan berkelanjutan.\n\n“Penguatan kurikulum berbasis OBE menjadi langkah strategis untuk memastikan proses pendidikan di Prodi PGMI tidak hanya berorientasi pada apa yang diajarkan, tetapi juga pada kompetensi dan capaian yang dihasilkan oleh mahasiswa.” Kegiatan workshop ditutup dengan closing ceremony dan pembagian piagam penghargaan pada Sabtu, 29 Agustus 2026.', 5, '/api/v1/media/121a979c-0309-446f-9130-b01bffe096e7', NULL, 'bottom', 1, 0, '2026-11-24 04:03:11', '2026-11-24 04:03:11'),
(28, 'Dari MoU ke Aksi Nyata, PGMI IIM Surakarta dan STAISMAN Pandeglang Bersinergi dalam Pengabdian kepada Masyarakat', '2 September 2026', 1, 'Program Studi Pendidikan Guru Madrasah Ibtidaiyah (PGMI) Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta dan Program Studi PGMI Sekolah Tinggi Agama Islam Syekh Manshur (STAISMAN) Pandeglang...', 'Program Studi Pendidikan Guru Madrasah Ibtidaiyah (PGMI) Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta dan Program Studi PGMI Sekolah Tinggi Agama Islam Syekh Manshur (STAISMAN) Pandeglang memperkuat sinergi antarlembaga melalui kegiatan Pengabdian kepada Masyarakat (PkM) sebagai tindak lanjut perjanjian kerja sama yang dilaksanakan pada Selasa, 1 September 2026.\n\nImplementasi kerja sama tersebut diwujudkan melalui keterlibatan dosen dalam kegiatan In House Training (IHT) bertajuk “Pemanfaatan AI untuk Penguatan SDM Guru dalam Penyusunan Kurikulum Berbasis Cinta” yang diselenggarakan di MA Muhammadiyah Bekonang, Kabupaten Sukoharjo, pada Rabu, 2 September 2026.\n\nKaprodi PGMI IIM Surakarta, Lailla Hidayatul Amin, S.Pd., M.Pd.I., bersama Kaprodi PGMI STAISMAN Pandeglang, Desyi Rosita, S.Pd.I., M.Pd., berkontribusi sebagai narasumber dalam kegiatan tersebut. Keduanya berbagi pengetahuan dan pengalaman mengenai pemanfaatan kecerdasan buatan (Artificial Intelligence/AI) untuk mendukung pengembangan kompetensi guru dalam menyusun kurikulum dan perangkat pembelajaran yang bermakna serta berorientasi pada nilai-nilai kemanusiaan. Dalam kegiatan tersebut, ikut terlibat didalamnya salah satu dosen PGMI IIM Surakarta, Alfian Eko Rochmawan, M.Pd.I selaku moderator.\n\nMateri pelatihan menekankan pentingnya menempatkan AI sebagai mitra kerja guru dalam proses perencanaan pembelajaran. Teknologi AI dapat dimanfaatkan untuk membantu menyusun modul ajar, mengembangkan variasi asesmen, merancang media pembelajaran, serta menghasilkan alternatif strategi pembelajaran yang memperhatikan kebutuhan murid. Meskipun demikian, guru tetap memegang peran utama dalam menentukan keputusan pedagogis, menjaga etika, memverifikasi informasi, dan membangun hubungan yang hangat dengan murid.\n\nKurikulum Berbasis Cinta menjadi salah satu penekanan dalam kegiatan ini. Pendekatan tersebut mendorong guru untuk menghadirkan pembelajaran yang menumbuhkan cinta ilmu, cinta sesama, cinta lingkungan, dan cinta nilai-nilai luhur. Pemanfaatan AI diharapkan dapat membantu guru mengembangkan pembelajaran yang lebih kreatif dan adaptif tanpa mengurangi sentuhan kemanusiaan dalam proses pendidikan.\n\nBagi PGMI IIM Surakarta dan PGMI STAISMAN Pandeglang, kegiatan ini merupakan bentuk nyata tindak lanjut kerja sama antarlembaga melalui pelaksanaan tridarma perguruan tinggi, khususnya pengabdian kepada masyarakat. Kolaborasi tersebut juga menjadi ruang berbagi keahlian, memperluas jejaring akademik, serta memperkuat kontribusi perguruan tinggi terhadap peningkatan kualitas pendidikan.\n\nSinergi antara kedua program studi diharapkan tidak berhenti pada penandatanganan perjanjian kerja sama dan satu kegiatan bersama, tetapi berkembang menjadi program kolaboratif yang berkelanjutan dalam bidang pendidikan, penelitian, dan pengabdian kepada masyarakat.\n\nMelalui kegiatan ini, PGMI IIM Surakarta dan PGMI STAISMAN Pandeglang menegaskan komitmen untuk menghadirkan kolaborasi akademik yang produktif, responsif terhadap perkembangan teknologi, serta tetap berlandaskan nilai-nilai kemanusiaan dan pendidikan Islam.\n\nKolaborasi perguruan tinggi bukan sekadar membangun kesepakatan, melainkan menghadirkan kontribusi nyata bagi penguatan kompetensi guru dan kemajuan pendidikan.', 5, '/api/v1/media/b72c8f7f-7773-49f7-b9cb-23c8d9201316', '[\"/api/v1/media/be7a0f32-9754-4610-9c39-d10644436315\",\"/api/v1/media/cf15035d-2870-488f-ac3e-056caf70b7ce\"]', 'bottom', 1, 0, '2026-11-24 04:04:10', '2026-11-24 04:04:10'),
(29, 'PKN-K PIAUD IIM Surakarta: Kenalkan Pengelolaan Sampah melalui Proyek Bank Sampah di KB Ceria Margosari', '7 Oktober 2026', 1, 'Mahasiswa Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta melaksanakan salah satu Program Kerja (Proker) Praktik Kuliah Nyata (PKN) berupa kegiatan edukasi pengelolaan sampah melalui proyek...', 'Mahasiswa Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta melaksanakan salah satu Program Kerja (Proker) Praktik Kuliah Nyata (PKN) berupa kegiatan edukasi pengelolaan sampah melalui proyek pembuatan bank sampah di KB Ceria Margosari, Polokarto. Kegiatan tersebut diikuti oleh 26 anak, 4 guru, dan 13 mahasiswa IIM Surakarta, serta dihadiri oleh Dosen Pembimbing Lapangan.\n\nKegiatan ini bertujuan mengenalkan kepada anak usia dini tentang pentingnya menjaga kebersihan lingkungan serta membedakan sampah organik dan anorganik melalui kegiatan bermain yang menyenangkan dan bermakna. Anak-anak tidak hanya mendapatkan penjelasan secara sederhana, tetapi juga terlibat langsung dalam berbagai aktivitas praktik.\n\nKegiatan diawali dengan apersepsi mengenai tata tertib dan aturan membuang sampah. Anak-anak diajak memahami pentingnya membuang sampah pada tempatnya serta mengenali berbagai jenis sampah yang ada di lingkungan sekitar.\n\nSelanjutnya, anak-anak mengikuti kegiatan kolase gambar tempat sampah dengan menggunakan kombinasi bahan alam dan kertas. Melalui kegiatan ini, anak diberikan kesempatan untuk berkreasi sekaligus mengembangkan kemampuan motorik halus, kreativitas, dan kepedulian terhadap lingkungan.\n\nKegiatan kemudian dilanjutkan dengan permainan memasukkan sampah organik dan anorganik ke tempat yang sesuai melalui rintangan. Anak-anak melewati rintangan sambil membawa benda yang telah disiapkan, kemudian memilah dan memasukkannya ke dalam tempat sampah sesuai jenisnya. Aktivitas tersebut dikemas dalam suasana bermain sehingga anak belajar memilah sampah secara aktif dan menyenangkan.\n\nSebagai kegiatan akhir, anak-anak diajak memanfaatkan galon bekas menjadi tempat sampah. Galon bekas dihias dan dicat dengan berbagai kreasi menarik oleh anak-anak. Kegiatan ini sekaligus mengenalkan konsep pemanfaatan kembali barang bekas atau reuse, serta menumbuhkan kreativitas dan rasa memiliki terhadap lingkungan.\n\nDPL Annafi’ Nurul ‘Ilmi Azizah, M.Pd. turut hadir dan mendampingi pelaksanaan kegiatan sebagai bentuk dukungan terhadap mahasiswa dalam mengimplementasikan program kerja PKN di masyarakat, khususnya melalui kegiatan edukatif di satuan PAUD.\n\nMelalui Proker PKN ini, mahasiswa IIM Surakarta diharapkan mampu memberikan kontribusi nyata bagi masyarakat sekaligus memperoleh pengalaman dalam merancang dan melaksanakan kegiatan pembelajaran yang sesuai dengan karakteristik anak usia dini.\n\nKegiatan proyek bank sampah di KB Ceria Margosari diharapkan dapat menjadi langkah awal dalam menanamkan karakter peduli lingkungan sejak usia dini. Kebiasaan sederhana seperti membuang dan memilah sampah sesuai jenisnya diharapkan dapat diterapkan anak dalam kehidupan sehari-hari, baik di sekolah maupun di lingkungan keluarga.', 5, '/api/v1/media/82fd257f-0a5b-4ec3-aaa0-8ec1164ac35d', NULL, 'bottom', 1, 0, '2026-11-24 04:04:42', '2026-11-24 04:04:42'),
(31, 'PKN-K Prodi PIAUD IIM Surakarta Gelar Parenting Berbasis Hak Anak di KB Ceria Desa Polokarto', '17 Oktober 2026', 1, 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mambaul Ulum (IIM) Surakarta menyelenggarakan kegiatan parenting dalam rangka PKN-K dengan mengusung tema “Parenting Berbasis...', 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mambaul Ulum (IIM) Surakarta menyelenggarakan kegiatan parenting dalam rangka PKN-K dengan mengusung tema “Parenting Berbasis Hak Anak sebagai Strategi Pendidikan Keluarga dalam Pencegahan Kekerasan dan Eksploitasi Anak.” Kegiatan ini dilaksanakan pada Sabtu, 17 Oktober 2026, bertempat di KB Ceria, Desa Polokarto.\n\nKegiatan parenting ini menghadirkan Aditya Fajri Kurnia Pradhana, S.Sy., M.H. sebagai narasumber. Acara tersebut turut dihadiri oleh Kepala Desa Polokarto, Suharno, S.E.; Ketua Program Studi PIAUD IIM Surakarta, Iffah Mukhlisah, S.Pd., M.Pd.; serta Kepala KB Ceria, Ibu Puji Hastuti., S.Pd. Kehadiran para pemangku kepentingan tersebut menjadi bentuk dukungan terhadap penguatan pendidikan keluarga dan perlindungan anak di lingkungan masyarakat.\n\nPemilihan tema parenting berbasis hak anak dilatarbelakangi oleh pentingnya peran keluarga dalam menjamin terpenuhinya hak-hak anak serta menciptakan lingkungan pengasuhan yang aman, nyaman, dan mendukung tumbuh kembang anak secara optimal. Keluarga merupakan lingkungan pendidikan pertama bagi anak sehingga orang tua memiliki peran strategis dalam membangun pola pengasuhan yang positif, menghargai martabat anak, serta bebas dari kekerasan dan eksploitasi.\n\nDalam pemaparannya, Aditya Fajri Kurnia Pradhana, S.Sy., M.H., membahas pentingnya pemahaman orang tua mengenai hak-hak anak, penerapan pola pengasuhan yang menghargai kebutuhan dan pendapat anak, serta upaya pencegahan berbagai bentuk kekerasan dan eksploitasi anak. Melalui pemahaman tersebut, orang tua diharapkan mampu mengenali risiko yang dapat mengancam keselamatan anak dan mengambil langkah pencegahan melalui komunikasi yang baik, pengawasan yang tepat, serta pemberian perlindungan sesuai kebutuhan dan tahap perkembangan anak.\n\nKegiatan ini juga menekankan bahwa pengasuhan bukan sekadar memenuhi kebutuhan fisik anak, tetapi mencakup pemenuhan kebutuhan emosional, sosial, moral, dan intelektual. Orang tua perlu membangun hubungan yang hangat dengan anak, memberikan batasan secara proporsional, menghindari hukuman yang merendahkan martabat anak, serta menyediakan ruang bagi anak untuk tumbuh dan berkembang dalam lingkungan yang mendukung.\n\nKehadiran Kepala Desa Polokarto, Suharno, S.E., menunjukkan keterlibatan pemerintah desa dalam mendukung upaya peningkatan kesadaran masyarakat terhadap pentingnya pendidikan keluarga dan perlindungan anak. Sementara itu, kehadiran Ketua Prodi PIAUD IIM Surakarta, Iffah Mukhlisah, S.Pd., M.Pd., menjadi bagian dari dukungan institusi terhadap pelaksanaan kegiatan pengabdian dan penguatan peran perguruan tinggi dalam memberikan kontribusi nyata bagi masyarakat. Dukungan dari pihak KB Ceria juga menjadi bagian penting dalam membangun sinergi antara lembaga pendidikan anak usia dini, keluarga, dan masyarakat.\n\nMelalui kegiatan PKN-K ini, Prodi PIAUD IIM Surakarta berupaya memperkuat hubungan antara dunia akademik dan kebutuhan masyarakat, khususnya dalam bidang pendidikan anak usia dini dan pengasuhan keluarga. Kegiatan ini diharapkan dapat meningkatkan pemahaman orang tua mengenai pentingnya pengasuhan berbasis hak anak serta mendorong terbentuknya lingkungan keluarga dan satuan PAUD yang lebih aman, ramah anak, dan responsif terhadap kebutuhan perkembangan anak.\n\nPenyelenggaraan parenting ini sekaligus menegaskan pentingnya kolaborasi antara perguruan tinggi, pemerintah desa, lembaga PAUD, dan keluarga dalam mencegah kekerasan serta eksploitasi anak. Dengan pengasuhan yang berorientasi pada pemenuhan hak anak, diharapkan anak-anak dapat tumbuh dalam lingkungan yang melindungi martabatnya, mendukung potensinya, dan memberikan kesempatan untuk berkembang secara optimal.\nProdi PIAUD IIM Surakarta berkomitmen untuk terus mendorong kegiatan edukatif dan pengabdian kepada masyarakat sebagai bagian dari upaya mewujudkan pendidikan anak usia dini yang berkualitas, inklusif, dan berorientasi pada kepentingan terbaik bagi anak.', 5, '/api/v1/media/ee40a164-8c30-4363-9dac-433a42be496e', NULL, 'bottom', 1, 0, '2026-11-24 04:06:02', '2026-11-24 04:06:02'),
(32, 'Tari Kesatria IIM Surakarta Meriahkan Gelar Senja 2026', '21 Oktober 2026', 1, 'Sebanyak 18 mahasiswa Institut Islam Mamba’ul Ulum (IIM) Surakarta dari Program Studi Pendidikan Islam Anak Usia Dini (PIAUD), Pendidikan Agama Islam (PAI), dan Pendidikan Guru Madrasah Ibtidaiyah...', 'Sebanyak 18 mahasiswa Institut Islam Mamba’ul Ulum (IIM) Surakarta dari Program Studi Pendidikan Islam Anak Usia Dini (PIAUD), Pendidikan Agama Islam (PAI), dan Pendidikan Guru Madrasah Ibtidaiyah (PGMI) berpartisipasi dalam agenda Gelar Senja Kwartir Ranting 02 Serengan Tahun 2026 melalui penampilan tari bertajuk “Tari Kesatria”. Kegiatan yang dijadwalkan berlangsung pada Rabu, 21 Oktober 2026, di halaman Balai Kota Surakarta ini menjadi salah satu wadah bagi mahasiswa untuk menampilkan kreativitas, keterampilan seni, serta semangat kebersamaan dalam kegiatan kepramukaan.\n\nPenampilan Tari Kesatria didampingi oleh empat dosen pembina dan pendamping, yaitu Elina Intan Aprilliani, M.Pd., Iffah Mukhlisah, M.Pd., Anita Wardani, M.Pd., dan Annafi Nurul Ilmi Azizah, M.Pd.I. Kolaborasi mahasiswa lintas program studi ini menunjukkan keterlibatan mahasiswa dalam kegiatan pengembangan bakat dan minat sekaligus memperkuat pengalaman belajar di luar ruang perkuliahan.\n\nTari Kesatria mengangkat nuansa kepahlawanan melalui gerakan yang tegas, formasi yang terkoordinasi, serta penggunaan kostum bernuansa tradisional dengan dominasi warna merah dan hitam serta ornamen keemasan. Perpaduan gerak, ekspresi, dan properti tari menjadi bagian penting dalam membangun penampilan yang mencerminkan keberanian, kedisiplinan, tanggung jawab, dan kekompakan.\n\nKeterlibatan mahasiswa dari tiga program studi menjadi nilai tersendiri dalam kegiatan ini. Persiapan dan latihan tari menuntut koordinasi, komitmen, serta kerja sama antarpeserta agar setiap gerakan dan perubahan formasi dapat ditampilkan secara selaras. Pendampingan dosen turut berperan dalam mengarahkan proses persiapan dan membantu mahasiswa mengembangkan potensi seni serta keterampilan bekerja dalam tim.\n\nMelalui partisipasi dalam Gelar Senja, mahasiswa diharapkan dapat berkontribusi dalam pelestarian seni budaya, meningkatkan rasa percaya diri, dan mengembangkan karakter positif melalui kegiatan yang edukatif dan kolaboratif. Kegiatan ini juga menjadi kesempatan untuk memperkenalkan potensi mahasiswa IIM Surakarta kepada masyarakat melalui penampilan seni yang kreatif dan berkarakter.\n\nKamabigus Institut Islam Mambaul Ulum Surakarta Dr. Edy Muslimin, S.Ag,M.S.I sangat mendukung kegiatan para mahasiswa dalam berpartisipasi Gelar Senja 2026, beliau menegaskan bahwa pendidikan tinggi tidak hanya berorientasi pada penguasaan pengetahuan akademik, tetapi juga pada pengembangan keterampilan, karakter, kreativitas, dan kepedulian terhadap budaya. Melalui Tari Kesatria, mahasiswa IIM Surakarta membawa semangat kebersamaan dan nilai-nilai kepahlawanan ke dalam ruang aktualisasi seni dan kegiatan kemasyarakatan.', 5, '/api/v1/media/21299b1a-dc51-4655-8b52-f76e6cdf9b8c', NULL, 'bottom', 1, 0, '2026-11-24 04:06:34', '2026-11-24 04:06:34');
INSERT INTO `testimonials` (`id`, `name`, `job_title`, `category_id`, `quote`, `full_content`, `rating`, `avatar_url`, `gallery_urls`, `slideshow_position`, `is_visible`, `sort_order`, `created_at`, `updated_at`) VALUES
(33, 'Perkuat Fondasi Keilmuan dan Kurikulum OBE, Kaprodi PAI IIM Surakarta Ikuti Workshop Nasional Strategi Menuju Akreditasi', '27 Oktober 2026', 1, 'Dalam rangka memperkuat kualitas tata kelola akademik dan meningkatkan daya saing program studi menuju akreditasi unggul, Program Studi Pendidikan Agama Islam (PAI) Fakultas Tarbiyah Institut...', 'Dalam rangka memperkuat kualitas tata kelola akademik dan meningkatkan daya saing program studi menuju akreditasi unggul, Program Studi Pendidikan Agama Islam (PAI) Fakultas Tarbiyah Institut Islam Mamba’ul ’Ulum (IIM) Surakarta terus berkomitmen mengembangkan kualitas kurikulum berbasis keilmuan yang kokoh, adaptif, dan berorientasi pada capaian pembelajaran.\n\nKomitmen tersebut diwujudkan melalui keikutsertaan Ketua Program Studi (Kaprodi) PAI IIM Surakarta, Viki Bayu Mahendra, dalam kegiatan Workshop Nasional Penguatan Body of Knowledge: Fondasi Kurikulum OBE dan Strategi Melampaui Standar Menuju Akreditasi Unggul LAMGAMA. Kegiatan ini berlangsung selama tiga hari, pada 27–29 Oktober 2026, bertempat di Hotel Platinum Yogyakarta.\n\nWorkshop nasional tersebut menghadirkan sejumlah akademisi dan pakar pendidikan tinggi yang memiliki kompetensi serta pengalaman dalam pengembangan keilmuan Pendidikan Agama Islam dan peningkatan mutu akreditasi program studi. Para narasumber yang hadir meliputi Prof. Eva Latifah, Ketua Perkumpulan Program Studi Pendidikan Agama Islam Indonesia sekaligus Guru Besar UIN Sunan Kalijaga Yogyakarta; Prof. Suyadi, Guru Besar Universitas Ahmad Dahlan (UAD) Yogyakarta; serta Prof. Fihris, Guru Besar UIN Walisongo Semarang.\n\nKegiatan ini menjadi forum strategis bagi para pengelola program studi PAI dari berbagai perguruan tinggi untuk memperdalam pemahaman mengenai urgensi penguatan Body of Knowledge (BoK) sebagai fondasi utama dalam pengembangan kurikulum. Penguatan BoK tidak sekadar berkaitan dengan penyusunan struktur mata kuliah, tetapi juga menyangkut kejelasan identitas keilmuan, kedalaman substansi kajian, keterkaitan antardisiplin ilmu, serta relevansinya dengan kebutuhan masyarakat dan perkembangan zaman.\n\nSalah satu fokus utama workshop adalah pengembangan kurikulum berbasis Outcome-Based Education (OBE). Pendekatan ini menempatkan capaian pembelajaran lulusan sebagai orientasi utama dalam seluruh proses pendidikan, mulai dari perumusan profil lulusan, penetapan Capaian Pembelajaran Lulusan (CPL), pengembangan Capaian Pembelajaran Mata Kuliah (CPMK), implementasi pembelajaran, hingga sistem evaluasi dan penjaminan mutu akademik.\n\nSelain itu, peserta juga memperoleh penguatan strategi dalam memenuhi bahkan melampaui standar akreditasi LAMGAMA. Hal ini menjadi penting karena pencapaian akreditasi unggul tidak cukup hanya dibuktikan melalui kelengkapan dokumen administratif, tetapi harus tercermin dalam kualitas penyelenggaraan pendidikan, keunggulan tata kelola, produktivitas tridarma perguruan tinggi, inovasi pembelajaran, serta keberhasilan lulusan.\n\nBagi Program Studi PAI IIM Surakarta, keikutsertaan dalam workshop ini menjadi momentum penting untuk melakukan refleksi, evaluasi, dan pengembangan kurikulum agar semakin relevan dengan tantangan pendidikan Islam kontemporer. Penguatan Body of Knowledge diharapkan mampu mempertegas karakteristik dan diferensiasi keilmuan PAI IIM Surakarta, sekaligus menjadi pijakan dalam menghasilkan lulusan yang memiliki kompetensi keislaman, profesionalitas akademik, integritas kepribadian, wawasan global, serta kecakapan dalam memanfaatkan perkembangan teknologi.\n\nViki Bayu Mahendra menyampaikan bahwa kegiatan ini memberikan perspektif dan wawasan strategis bagi pengembangan Program Studi PAI, khususnya dalam membangun kurikulum yang tidak hanya memenuhi tuntutan regulasi dan standar akreditasi, tetapi juga memiliki kekuatan filosofis, epistemologis, dan praktis.\n\nMenurutnya, penguatan Body of Knowledge harus menjadi titik awal dalam membangun identitas dan keunggulan program studi. Kurikulum OBE juga perlu diterjemahkan secara konsisten dalam proses pembelajaran, budaya akademik, penelitian, pengabdian kepada masyarakat, serta pengembangan kompetensi mahasiswa.\n\n“Pengembangan program studi tidak cukup hanya berorientasi pada pemenuhan dokumen akreditasi. Kita harus membangun fondasi keilmuan yang kuat, memiliki diferensiasi yang jelas, serta memastikan seluruh proses pendidikan benar-benar menghasilkan lulusan sesuai dengan profil dan capaian pembelajaran yang telah ditetapkan. Akreditasi unggul seharusnya menjadi konsekuensi dari budaya mutu yang dibangun secara berkelanjutan,” ungkapnya.\n\nLebih lanjut, hasil dan pengalaman dari workshop nasional ini diharapkan dapat ditindaklanjuti melalui evaluasi kurikulum, penguatan peta keilmuan PAI, penyelarasan CPL dan CPMK, peningkatan kualitas pembelajaran, serta pengembangan program akademik yang inovatif dan responsif terhadap kebutuhan masyarakat.\n\nKeikutsertaan Kaprodi PAI IIM Surakarta dalam kegiatan nasional ini sekaligus menegaskan komitmen Fakultas Tarbiyah IIM Surakarta untuk terus melakukan transformasi akademik dan memperkuat budaya mutu. Langkah tersebut menjadi bagian dari ikhtiar institusi dalam meningkatkan kualitas pendidikan tinggi Islam serta mewujudkan visi perguruan tinggi yang berdaya saing dan berorientasi pada standar internasional.\n\nDengan fondasi keilmuan yang kuat, kurikulum yang terukur, dan budaya mutu yang berkelanjutan, Program Studi PAI IIM Surakarta optimistis melangkah menuju program studi yang unggul, kompetitif, dan mampu memberikan kontribusi nyata bagi pengembangan pendidikan Islam di Indonesia.', 5, '/api/v1/media/1c3fbc61-9e1e-4f9a-ba00-49000c6cd5d3', NULL, 'bottom', 1, 0, '2026-11-24 04:07:21', '2026-11-24 04:07:21'),
(34, 'Satu Bulan Mengabdi, Mahasiswa PIAUD IIM Surakarta Resmi Ditarik dari Kelurahan Polokarto', '29 Oktober 2026', 1, 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mambaul Ulum (IIM) Surakarta melaksanakan kegiatan penarikan mahasiswa Praktik Kerja Nyata Khusus (PKN-K) di Kelurahan...', 'Program Studi Pendidikan Islam Anak Usia Dini (PIAUD) Institut Islam Mambaul Ulum (IIM) Surakarta melaksanakan kegiatan penarikan mahasiswa Praktik Kerja Nyata Khusus (PKN-K) di Kelurahan Polokarto pada Kamis, 29 Oktober 2026. Kegiatan ini menandai berakhirnya pelaksanaan PKN-K yang telah berlangsung selama satu bulan dengan berbagai program pemberdayaan dan edukasi masyarakat.\n\nKegiatan penarikan dilaksanakan dalam suasana khidmat dan penuh keakraban. Acara diawali dengan sambutan dari Ibu Iffah Mukhlisah, M.Pd. Dalam sambutannya, beliau menyampaikan apresiasi dan ucapan terima kasih kepada Pemerintah Kelurahan Polokarto beserta seluruh masyarakat yang telah menerima, mendampingi, dan memberikan kesempatan kepada mahasiswa PIAUD IIM Surakarta untuk melaksanakan berbagai program kegiatan selama menjalani PKN-K.\n\nBeliau juga menyampaikan bahwa Praktik Kerja Nyata Khusus (PKN-K) merupakan salah satu bentuk pembelajaran lapangan yang memberikan kesempatan kepada mahasiswa untuk mengimplementasikan ilmu pengetahuan dan keterampilan yang diperoleh selama perkuliahan. Melalui kegiatan ini, mahasiswa diharapkan mampu memperoleh pengalaman nyata, meningkatkan kemampuan beradaptasi, membangun komunikasi dengan masyarakat, serta mengembangkan kepedulian sosial.\n\nSelama satu bulan pelaksanaan PKN-K, mahasiswa PIAUD IIM Surakarta telah melaksanakan sejumlah program yang melibatkan partisipasi masyarakat. Program tersebut meliputi edukasi dan pengelolaan limbah sampah sebagai upaya meningkatkan kesadaran masyarakat terhadap kebersihan dan kelestarian lingkungan. Mahasiswa juga melaksanakan kunjungan ke sejumlah pelaku Usaha Mikro, Kecil, dan Menengah (UMKM) di wilayah Kelurahan Polokarto sebagai bentuk pengenalan potensi ekonomi lokal. Kegiatan ini dilengkapi dengan pembuatan banner sebagai media informasi dan promosi UMKM desa.\n\nSelain program lingkungan dan pemberdayaan ekonomi, mahasiswa juga menyelenggarakan kegiatan parenting dengan menghadirkan Aditya Fajri Kusuma Pradhana, S.Sy., M.H. sebagai narasumber. Kegiatan parenting ini menjadi salah satu bentuk kontribusi mahasiswa dalam memberikan edukasi kepada masyarakat, khususnya orang tua, mengenai pentingnya pengetahuan dan keterlibatan keluarga dalam mendukung tumbuh kembang serta pendidikan anak.\n\nProgram lainnya adalah kegiatan senam sehat untuk ibu dan anak. Kegiatan ini dilaksanakan sebagai upaya menumbuhkan kesadaran masyarakat tentang pentingnya menjaga kesehatan dan kebugaran tubuh sejak dini. Melalui kegiatan tersebut, mahasiswa turut mendorong terciptanya aktivitas positif yang melibatkan ibu dan anak sekaligus mempererat kebersamaan di lingkungan masyarakat.\n\nSelanjutnya, kegiatan penarikan mahasiswa PKN-K secara resmi dilakukan oleh Bapak Ngatmin Abbas, M.Pd. sebagai perwakilan dari pihak IIM Surakarta. Setelah prosesi penarikan, mahasiswa secara resmi diserahkan kembali kepada pihak kampus oleh Bapak Suharno, S.E., selaku Lurah Polokarto. Prosesi tersebut menjadi simbol berakhirnya pelaksanaan tugas mahasiswa PKN-K di Kelurahan Polokarto setelah menjalani berbagai kegiatan selama satu bulan.\n\nMelalui berbagai program yang telah dilaksanakan, mahasiswa memperoleh pengalaman dan pembelajaran secara langsung di tengah masyarakat. Kegiatan ini menjadi sarana untuk mengembangkan kompetensi diri, melatih tanggung jawab, meningkatkan keterampilan sosial, serta memahami kebutuhan dan potensi masyarakat secara lebih dekat.\n\nProgram Studi PIAUD IIM Surakarta berharap pengalaman selama mengikuti PKN-K dapat menjadi bekal berharga bagi mahasiswa dalam mengembangkan kompetensi akademik maupun keterampilan praktis. Selain itu, kegiatan ini diharapkan mampu membentuk calon pendidik anak usia dini yang profesional, mandiri, komunikatif, kreatif, dan memiliki kepedulian terhadap lingkungan sosial.\n\nPihak IIM Surakarta menyampaikan terima kasih dan penghargaan kepada Pemerintah Kelurahan Polokarto, khususnya Bapak Suharno, S.E., beserta seluruh perangkat kelurahan dan masyarakat yang telah memberikan dukungan serta kerja sama selama pelaksanaan PKN-K.\n\nBerakhirnya kegiatan PKN-K ini diharapkan tidak menjadi akhir dari hubungan baik yang telah terjalin, melainkan menjadi awal dari keberlanjutan kerja sama antara Program Studi PIAUD IIM Surakarta dengan Pemerintah Kelurahan Polokarto dalam mendukung pengembangan pendidikan, kesehatan keluarga, kepedulian lingkungan, dan pemberdayaan masyarakat.', 5, '/api/v1/media/47b7fb76-4ef6-4e0e-99fa-9064ed3bed95', NULL, 'bottom', 1, 0, '2026-11-24 04:08:01', '2026-11-24 04:08:01'),
(35, 'Stadium General Fakultas Tarbiyah Tahun Akademik 2023/2024', '9 September 2023', 1, 'Stadium General Fakultas Tarbiyah 2023 merupakan salah satu Rangkaian dari kegiatan MASTAKA (Masa Ta’aruf dan Keakraban). Sabtu, 9 September 2023 di Gedung Dakwah KH. Hasyim Cholil yang menjadi...', 'Stadium General Fakultas Tarbiyah 2023 merupakan salah satu Rangkaian dari kegiatan MASTAKA (Masa Ta’aruf dan Keakraban). Sabtu, 9 September 2023 di Gedung Dakwah KH. Hasyim Cholil yang menjadi saksi dari suksesnya kegiatan Stadium General Fakultas Tarbiyah Institut Islam Mamba’ul ‘Ulum Surakarta dan Diseminasi Kolaborasi Penelitian dan Pengabdian kepada Masyarakat (PKM) secara offline maupun online. Stadium General Fakultas Tarbiyah 2023 mengambil tema “Mencari Model Penyiapan Guru: Belajar dari Perguruan Tinggi Dalam & Luar Negeri” dengan Keynote speaker oleh Prof. Dr. Muhammad Munadi, M.Pd, beliau merupakan Guru Besar dari UIN Raden Mas Said Surakarta didampingi serta dimoderatori oleh Viki Bayu Mahendra, M.Pd (Dosen IIM Surakarta). Acara ini dihadiri oleh kurang lebih 369 mahasiswa baru-mahasiswa lama, dosen, dan para peserta diseminasi penelitian dari internal kampus maupun eksternal kampus yang tertarik untuk mencari inspirasi dan contoh terbaik dalam penyiapan guru.\n\nDi awal penyampaian materi stadium general, terdapat pembahasan menarik dari keynote speaker bahwa menjadi seorang guru inspiratif peserta dapat belajar melalui dari 3 novel yang kita kenal, beliau memilih contoh peran guru dari beberapa novel yang tayang di layar lebar seperti Laskar Pelangi, Negeri 5 Menara, dan Guru Aini. Keynote Speaker berbagi pengetahuan tentang aspek-aspek penting dalam mempersiapkan guru yang berkualitas. Beliau menyampaikan berbagai isu-isu pendidikan guru, model dan jenis pendidikan guru, serta penguraian input, proses, output sampai dengan outcome problem pendidikan guru.\n\nSedangkan, pada presentasi Diseminasi Kolaborasi Penelitian dan Pengabdian kepada Maryarakat oleh 11 kelompok baik dari internal dan eksternal kampus yang di moderatori oleh Septian Nur Ika Trisnawati, M.Pd (Dosen IIM Surakarta) juga berjalan lancar walaupun secara hybrid. Adapun presenter Penelitiaan dan Pengabdian kepada Maryarakat dalam acara diseminasi, anggota terdapat dari berbagai institusi yakni: STPI Bina Insan Mulia Yogyakarta, Universitas Sains Al-Qur’an, Institut Islam Mamba’ul ‘Ulum Surakarta, Universitas Islam Al-Ihya Kuningan, dan IAI Nahdhatul Ulama Kebumen.\n\nDiskusi antara peserta acara juga menjadi highlight dalam kegiatan ini. Pertanyaan yang menantang dan pandangan yang beragam ini menghasilkan pemikiran kritis dan refleksi yang mendalam tentang penyiapan guru di masa depan. Para peserta juga memiliki kesempatan untuk bertukar ide dan saling belajar dari pengalaman masing-masing serta membangun jejaring yang kuat dalam hal penelitian dan pengembangan pendidikan.\n\nMelalui kegiatan ini, Fakultas Tarbiyah Institut Islam Mamba’ul ‘Ulum Surakarta tidak hanya berupaya untuk memperkaya pengetahuan dan pemahaman tentang penyiapan guru, tetapi juga memberikan kontribusi nyata dalam pengembangan pendidikan di Indonesia. Diharapkan bahwa ide-ide dan pengetahuan ilmu dalam acara ini akan menginspirasi praktisi pendidikan dan meningkatkan kualitas pengajaran di berbagai lingkup pendidikan di Indonesia.', 5, '/api/v1/media/cb8a5cad-a4d9-4b59-8a59-24975f1d4023', NULL, 'bottom', 1, 0, '2026-11-24 04:11:18', '2026-11-24 04:11:18'),
(36, 'Pembekalan PPL Fakultas Tarbiyah : Mewujudukan Pendidik Kreatif, Inovatif, dan Profesional dalam Membangun Karakter Bang', '29 Juni 2024', 1, 'Di Gedung Dakwah Kyai Hj. Hasyim Cholil, telah terlaksana kegiatan Pembekalan Mahasiswa Praktik Pengalaman Lapangan (PPL) Fakultas Tarbiyah yang sukses dan penuh inspirasi, dengan tema Mewujudukan...', 'Di Gedung Dakwah Kyai Hj. Hasyim Cholil, telah terlaksana kegiatan Pembekalan Mahasiswa Praktik Pengalaman Lapangan (PPL) Fakultas Tarbiyah yang sukses dan penuh inspirasi, dengan tema Mewujudukan Pendidik Kreatif, Inovatif, dan Profesional dalam Membangun Karakter Bangsa. Kegiatan ini dihadiri oleh sekitar 300 mahasiswa dan 26 Dosen Pembimbing Lapangan. \n\nPembukaan kegiatan pembekalan PPL ini diawali dengan sambutan oleh Dr. Joko Subando sebagai Wakil Rektor I. Dilanjutkan dengan pemaparan materi oleh pemateri utama yaitu Drs. Priyono, S. Pd. M. Pd selaku Kasi Kurikulum Dikdas SD Dinas pendidikan Kota Surakarta memberikan pembahasan mengenai KOSP (Kurikulum Operasional Satuan Pendidikan) sebagai Penerapan Kurikulum Merdeka Belajar di Sekolah dan Strategi Pembelajaran Kreatif dan Inovatif pada Kurikulum Merdeka. Menurut beliau pentingnya bagi mahasiswa untuk memiliki kemampuan memahami Kurikulum Merdeka dan mampu mengaplikasikannya dengan kreativitas dan inovasi. Sehingga, mahasiswa dapat menjadi guru yang profesional yang mampu membangun karakter bangsa melalui pendidikan yang berkualitas dan relevan dengan tuntutan zaman.\n\nPemaparan materi kedua oleh Iffah Mukhlisah, M.Pd selaku Dosen Fakultas Tarbiyah dan Lailla Hidayatul Amin, S.Pd., M.Pd.I. selaku Ketua Program Studi (Kaprodi) Pendidikan Guru Madrasah Ibtidaiyah yang juga menjadi Ketua Panitia PPL. Keduanya memberikan pengantar dan menjelaskan mekanisme PPL kepada para peserta. Informasi tersebut mencakup langkah-langkah pelaksanaan PPL, peran dan tanggung jawab mahasiswa. Serta memberikan panduan tentang teknik penyusunan laporan PPL dan luaran, penyusunan laporan yang baik akan membantu dalam memantau dan mengevaluasi perkembangan mahasiswa selama PPL.\n\nMelalui kegiatan pembekalan ini, diharapkan para mahasiswa yang akan menjalani PPL dapat memahami pentingnya penerapan kurikulum merdeka dan mampu mengaplikasikan pembelajaran yang kreatif dan inovatif. Dari pembekalan ini, diharapkan muncul semangat yang kuat dan komitmen yang tinggi, supaya mahasiswa dapat menjadi agen perubahan yang mampu menjadikan sistem pendidikan menjadi lebih baik dan memajukan bangsa. Mahasiswa berkemauan untuk terus belajar dan berkembang dalam menghadapi tantangan zaman.', 5, '/api/v1/media/26ef827e-5e4c-49a4-a4cc-f6820c2eca89', '[\"/api/v1/media/773c3aba-f700-425b-957a-a38af588de54\",\"/api/v1/media/7abe55b3-55f1-41ae-b770-f4cfa894033e\",\"/api/v1/media/7106befb-f596-446e-9f92-ad8d5a870787\"]', 'middle', 1, 0, '2026-11-24 04:12:13', '2026-11-24 04:12:13'),
(37, 'Persamaan Persepsi dengan Guru Pamong dan Tindaklanjut dengan MoU antara Fakultas Tarbiyah dan mitra Penyelenggaraan PPL', '22 Juli 2024', 1, 'Fakultas Tarbiyah Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta menyelenggarakan kegiatan Persamaan Persepsi dengan Guru Pamong dan tindak lanjut berupa penandatanganan MoU antara Fakultas...', 'Fakultas Tarbiyah Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta menyelenggarakan kegiatan Persamaan Persepsi dengan Guru Pamong dan tindak lanjut berupa penandatanganan MoU antara Fakultas Tarbiyah dan sekolah tempat Praktik Pengalaman Lapangan (PPL). Kegiatan ini dibuka Sambutan oleh Ibu Dra. Hj. Nur Hidayah, MSI (Dekan Fakultas), dan inti materi disampaikan oleh Ibu Lailla Hidayatul Amin, S.Pd., M.Pd.I. (Wakil Dekan Fakultas) didampingi oleh Ibu Iffah Mukhlisah, M.Pd. (Koordinator Pembekalan PPL). Tujuan daripada kegiatan persamaan persepsi guru pamong ini diantaranya untuk menyamakan Persepsi dan Pendekatan Pembelajaran, Memperkuat Kerjasama dan Kolaborasi, Memastikan Kualitas Pelaksanaan PPL, Meningkatkan Profesionalisme Mahasiswa dengan bimbingan guru pamong, Mengembangkan Jaringan Kemitraan, dan Menjamin Kepatuhan terhadap Standar Akademik dan Pendidikan.\n\nFakultas Tarbiyah menghadirkan guru pamong dan menjadikan mitra Sekolah/Madrasah sebagai tempat Praktik Pengalaman Lapangan (PPL) 2024 oleh Mahasiswa sebagai berikut: MTs Negeri 1 Surakarta, SMP Al Islam Surakarta, SMP Muhammadiyah 5 Surakarta, SMP IT Insan Kamil Karanganyar, SMA Muhammadiyah 3 Surakarta, MTS Negeri 6 Sragen, SMP TA’MIRUL ISLAM SURAKARTA, MTs Muhammadiyah Blimbing Wonorejo Polokarto, SMA Islam 1 Surakarta, SMP IT Insan Mulia, SMP Al Firdaus, SMP Muhammadiyah Imam Syuhodo, MTS Negeri 2 Sukoharjo, SMP Muhammadiyah 1 Sukoharjo, MTS Al-Islam Jamsaren, MI Al-Islam Jamsaren Surakarta, SMA Jajar Islamic Center Cab. Surakarta, Cab. Mayang Sukoharjo, Cab. Sambi Boyolali, SMA Karya Dharma Veteran Sambi , SMPIT Ar-Risalah Sukoharjo, MTs Baitul Hikmah Sukoharjo, SMP Budi Utomo Surakarta, MTs Muhammadiyah Grogol Sukoharjo, dan Madrasah Tsanawiyah Darul Falah. Kegiatan PPL di Sekolah/Madrasah tidak lepas dari Dosen Pembimbing Lapangan yang sudah dikelompokkan oleh Fakultas.\n\nSecara keseluruhan, kegiatan Persamaan Persepsi dengan Guru Pamong dan penandatanganan MoU ini merupakan langkah strategis dari Fakultas Tarbiyah IIM Surakarta untuk meningkatkan kualitas pendidikan dan memastikan kesiapan mahasiswa dalam menghadapi dunia profesional sebagai pendidik.\n\n.', 5, '/api/v1/media/3a5b712f-b21a-4d60-96ab-016eec82a440', '[\"/api/v1/media/4e42d30d-4915-43a5-81bd-b20c2fa1772a\",\"/api/v1/media/9c9c461c-dc26-4855-bf4e-2149c7994aa1\"]', 'middle', 1, 0, '2026-11-24 04:13:07', '2026-11-24 04:13:07'),
(38, 'Fakultas Tarbiyah Lakukan Monitoring Mahasiswa PPL ke Sekolah Menengah/Madrasah di Karesidenan Surakarta', '13 Agustus 2024', 1, 'Panitia Praktek Pengalaman Lapangan (PPL) Fakultas Tarbiyah Institut Islam Mamba’ul ’Ulum (IIM) Surakarta melakukan kunjungan monitoring ke SMP Insan Kamil Karanganyar, Pondok Pesantren MTA...', 'Panitia Praktek Pengalaman Lapangan (PPL) Fakultas Tarbiyah Institut Islam Mamba’ul ’Ulum (IIM) Surakarta melakukan kunjungan monitoring ke SMP Insan Kamil Karanganyar, Pondok Pesantren MTA Karanganyar pada Selasa (13/8/2024). Kegiatan ini bertujuan untuk memantau perkembangan dan kinerja mahasiswa yang sedang menjalani PPL di sekolah tersebut.\n\nTim monitoring yang dipimpin oleh Dekan Fakultas Tarbiyah Dra. Hj. Nurhidayah, MSi., Di dampingi Gugus Penjamin Mutu Fakultas Tarbiyah Iffah Mukhlisah, MPd,. Selaku Ketua Panitia PPL Fakultas Tarbiyah IIM Surakarta, disambut hangat oleh pihak SMP Insan Kamil. Kepala Sekolah SMP Insan Kamil, dalam hal ini diwakili Koordinator Guru Pamong Hasan Basri, S.Pd., beserta para guru pamong lainnya turut hadir dalam pertemuan tersebut.\n\n“Kami sangat mengapresiasi kerjasama yang terjalin antara IIM Surakarta dengan SMP Insan Kamil. PPL ini memberikan pengalaman berharga bagi mahasiswa kami dalam mengaplikasikan ilmu yang telah dipelajari,” ujar Hasan Basri, S.Pd.\n\nSelama kunjungan, tim panitia PPL melakukan beberapa kegiatan, antara lain:\n1. Observasi langsung proses pembelajaran yang dilakukan oleh mahasiswa PPL di kelas.\n2. Diskusi dengan guru pamong mengenai perkembangan dan kinerja mahasiswa PPL.\n3. Evaluasi bersama mahasiswa PPL terkait kendala dan pencapaian selama masa praktik.\n4. Koordinasi dengan pihak sekolah untuk peningkatan kualitas program PPL.\n\nHasan Basri menyampaikan apresiasi atas kontribusi mahasiswa PPL IIM Surakarta. “Para mahasiswa PPL telah menunjukkan dedikasi dan kreativitas yang baik dalam mengajar. Mereka membawa suasana baru yang positif bagi siswa-siswa kami,” tuturnya.\n\nSalah satu mahasiswa PPL, Imron Wahyu Saputro, mengungkapkan pengalamannya, “PPL di SMP Insan Kamil memberikan kami wawasan baru tentang pendidikan berbasis pesantren. Kami belajar banyak dari para ustadz dan ustadzah di sini.”\n\nSecara terpisah Tim Monitoring lain yang di Ketua Wakil Dekan Fakultas Tarbiyah Laila Hidayatul Amin, S.Pd., M.Pd,I, beserta Gugus Penjamin Mutu PIAUD Erlina Intan Apriliani, M.Pd. melakukan kunjungan ke MTs Darul Falah, MTSN 6 Sragen serta SMA Muhammadyah 3 Surakarta.\n\nProgram PPL ini merupakan bagian integral dari kurikulum Fakultas Tarbiyah IIM Surakarta yang bertujuan mempersiapkan calon guru profesional. Melalui PPL, mahasiswa diharapkan dapat mengembangkan kompetensi pedagogik, kepribadian, sosial, dan profesional sebagai calon pendidik.\n\nTim monitoring juga memberikan masukan dan arahan kepada mahasiswa PPL untuk terus meningkatkan kualitas pengajaran dan interaksi dengan siswa. Kunjungan ini diharapkan dapat memperkuat hubungan kerjasama antara IIM Surakarta dengan Sekolah Menengah/Madrasah di Wilayah Subosukowonosraten di masa mendatang.\n\nPPL Fakultas Tarbiyah IIM Surakarta di SMP Insan Kamil akan berlangsung hingga akhir Agustus 2024. Panitia PPL berencana melakukan evaluasi akhir dan penarikan mahasiswa pada minggu terakhir bulan tersebut.', 5, '/api/v1/media/438b5516-1da3-4b75-9ce7-619f1814d4ab', '[\"/api/v1/media/60a97d9b-c0fc-4040-a19e-63bccd2505dd\"]', 'bottom', 1, 0, '2026-11-24 04:14:19', '2026-11-24 04:14:19'),
(39, 'Stadium General Fakultas Tarbiyah: Membentuk Guru yang Adaptif di Era Disrupsi Teknologi', '9 September 2024', 1, 'Fakultas Tarbiyah sukses menyelenggarakan Stadium General yang bertajuk “Membentuk Guru yang Adaptif di Era Disrupsi Teknologi” Acara yang diadakan di Gedung Dakwah Kyai Haji Hasyim Kholil di...', 'Fakultas Tarbiyah sukses menyelenggarakan Stadium General yang bertajuk “Membentuk Guru yang Adaptif di Era Disrupsi Teknologi” Acara yang diadakan di Gedung Dakwah Kyai Haji Hasyim Kholil di Mojosongo Surakarta ini dihadiri oleh Rektor IIM Surakarta Bapak Edy Muslimin, M.S.I, Wakil Rektor I Dr. Joko Subando, M.Pd, Wakil Rektor II Ibu , Dr. Meti Fatimah, M.Pd.I, Wakil Rektor III Bapak Mukhlis Fathurrohman, M.S.I, Dekan Fakultas Tarbiyah beserta staff dan seluruh dosen Fakultas Tarbiyah serta ratusan mahasiswa Fakultas Tarbiyah IIM Surakarta.\n\nStadium general kali ini menghadirkan pembicara utama Prof. Dr. H. Nizar Ali, M.Ag Rektor UIN Walisongo Semarang, seorang pakar pendidikan Islam Ilmu Hadist. Dalam pemaparannya, Prof. Nizar Ali membahas tentang tantangan guru di era digital dimana guru menghadapi 5 tantangan utama yaitu: (1) integrasi teknologi dalam pembelajaran, (2) ketidaksetaraan akses teknologi di kalangan siswa, (3) mengelola ketergantungan siswa pada teknologi, (4) menyaring dan menilai Informasi dari sumber digital dan (5) memelihara keseimbangan antara penggunaan teknologi dan Interaksi manusia. Beliau menggarisbawahi bahwa para pendidik harus mampu beradaptasi dengan perubahan teknologi dan tren global dengan tetap mempertahankan nilai-nilai luhur pendidikan.\n\nAcara ini juga menjadi ajang diskusi antara mahasiswa IIM Surakarta dengan pemateri berkaitan topik tersebut. Para mahasiswa sangat antusias mengikuti sesi tanya jawab, di mana berbagai pertanyaan kritis terkait praktik pendidikan masa kini diajukan kepada pembicara.\nSelain itu Prof. Dr. H. Nizar Ali, M.Ag beserta Rektor dan jajaran Wakil Rektor berkesempatan memberikan piala juara 1 Lomba Futsal, Juara 1 bulutangkis, MQK dan Pencak Silat dalam ajang The 6th Internasional Sports and Arts Festival 2024 yang diikuti para mahasiswa IIM Surakarta.\n\nDekan Fakultas Tarbiyah, Dr. H. M. Ja’far Nashir, S.Ag., M.Ag dengan jajaran Wakil Dekan I Bidang Akademi Lailla Hidayatul Amin, S.Pd., M.Pd.I, Wakil Dekan II Bidang Keuangan Dra. Hj Nur Hidayah, M.S.I dan Wakil Dekan III Bidang Kemahasiswaan Elina Intan Apriliani, S.Pd., M.Pd dalam sambutannya menyampaikan Informasi Fakultas terkait Akademik, Keuangan dan Kemahasiswaan.\n\nAcara ini ditutup dengan pengumuman Lomba Video Dokumenter PPL Fakultas Tarbiyah 2024 oleh Bapak Alfian Eko Rochmawan, S.Pd.I, M.Pd.I serta pemberian apresiasi video Terbaik terhadap Lomba Video PPL oleh Dekan Fakultas Tarbiyah, serta foto bersama seluruh peserta. Kegiatan stadium general ini diharapkan dapat menjadi inspirasi bagi seluruh peserta untuk terus berinovasi dan berkontribusi dalam dunia pendidikan, sesuai dengan visi dan misi Fakultas Tarbiyah.', 5, '/api/v1/media/c8b1cc11-ae35-412e-b6e6-ef99b2ef565b', NULL, 'bottom', 1, 0, '2026-11-24 06:31:51', '2026-11-24 06:31:51'),
(40, 'Fakultas Tarbiyah IIM Surakarta Satukan Persepsi DPL dan Guru Pamong dalam PPL 2025, Tandatangani MoU Kemitraan Sekolah', '14 Juli 2025', 1, 'Fakultas Tarbiyah Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta menggelar kegiatan Persamaan Persepsi Calon Dosen Pembimbing Lapangan (DPL) dan Guru Pamong untuk pelaksanaan Program Pengalaman...', 'Fakultas Tarbiyah Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta menggelar kegiatan Persamaan Persepsi Calon Dosen Pembimbing Lapangan (DPL) dan Guru Pamong untuk pelaksanaan Program Pengalaman Lapangan (PPL) 2025, pada Senin (14/7) bertempat di Ruang Aula IIM Surakarta. Kegiatan ini sekaligus menjadi momentum penting bagi penandatanganan nota kesepahaman (MoU) antara kampus dan sekolah mitra.\n\nAcara dimulai pukul 08.45 WIB dengan registrasi peserta, yang terdiri dari para calon DPL, koordinator guru pamong dari berbagai sekolah mitra, serta jajaran panitia pelaksana PPL. Acara dibuka oleh MC Fenti Fiqri F., S.E., yang dilanjutkan dengan sambutan oleh Dr. H. M. Ja’far Nashir, S.Ag., M.Ag., mewakili unsur pimpinan IIM.\n\nDalam sambutannya, Dr. Ja’far menegaskan pentingnya membangun persepsi yang sama antara dosen pembimbing dan guru pamong untuk menjamin mutu pelaksanaan PPL. “PPL bukan hanya tentang praktik, melainkan pembentukan karakter pendidik yang utuh. Untuk itu, diperlukan sinergi yang kuat antara kampus dan sekolah agar proses pembimbingan berjalan selaras,” ujarnya.\n\nSetelah sesi pembukaan, kegiatan berlanjut dengan pemaparan materi oleh Ketua Panitia PPL, Lailla Hidayatul Amin, S.Pd., M.Pd.I., mengenai mekanisme teknis penyelenggaraan PPL, termasuk alur penempatan mahasiswa, pembagian peran DPL dan guru pamong, sistem pelaporan, hingga prinsip-prinsip pendampingan yang menjunjung tinggi etika akademik dan profesionalitas. Dalam sesi ini, para peserta juga mendapatkan pemahaman lebih dalam terkait pola penilaian mahasiswa, sistem pelaporan terintegrasi, hingga kerangka kerja sama yang menekankan penguatan mutu lulusan berbasis pengalaman lapangan. Sesi ini dipandu oleh moderator Septian Nur Ika T., M.Pd., CLSP, yang juga memberikan ruang diskusi kepada para peserta untuk menyampaikan tanggapan, pertanyaan, dan masukan demi kelancaran pelaksanaan program.\n\nKegiatan ditutup dengan prosesi penyerahan dan penandatanganan Memorandum of Understanding (MoU) antara Fakultas Tarbiyah IIM Surakarta dengan sekolah mitra yang diwakili oleh koordinator guru pamong. Penandatanganan dilakukan oleh Dr. H. M. Ja’far Nashir, S.Ag., M.Ag. dan Lailla Hidayatul Amin, S.Pd., M.Pd.I., menandai dimulainya kerja sama resmi antara lembaga perguruan tinggi dan mitra sekolah dalam pelaksanaan PPL. Penandatanganan MoU ini menjadi simbol komitmen bersama untuk menjamin mutu pelaksanaan PPL yang profesional, kolaboratif, dan selaras dengan arah pengembangan pendidikan yang berorientasi pada pembelajaran mendalam.', 5, '/api/v1/media/f7d263ee-4b02-496d-8840-32871eff3ad3', '[\"/api/v1/media/d2288d76-9722-42a9-9f54-ff245ae86298\"]', 'bottom', 1, 0, '2026-11-24 06:35:18', '2026-11-24 06:35:18'),
(41, 'Sebanyak 273 Mahasiswa Fakultas Tarbiyah IIM Surakarta Ikuti Pembekalan PPL 2025', '21 Juli 2025', 1, 'Sebanyak 273 mahasiswa dari Fakultas Tarbiyah Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta mengikuti kegiatan Pembekalan Program Pengalaman Lapangan (PPL) Tahun 2025 yang diselenggarakan pada...', 'Sebanyak 273 mahasiswa dari Fakultas Tarbiyah Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta mengikuti kegiatan Pembekalan Program Pengalaman Lapangan (PPL) Tahun 2025 yang diselenggarakan pada Senin (21/7) di Gedung Dakwah Kyai H. Hasyim Cholil, Jebres, Surakarta. Kegiatan ini menjadi langkah awal yang penting sebelum para mahasiswa diterjunkan langsung ke sekolah-sekolah mitra sebagai bentuk penguatan kompetensi profesional kependidikan.\n\nAcara dimulai sejak pukul 07.30 WIB dengan sesi registrasi peserta, yang dikoordinasikan oleh tim panitia dan perwakilan Badan Eksekutif Mahasiswa (BEM). Suasana pembekalan tampak tertib dan penuh antusias. Tepat pukul 08.00 WIB, acara dibuka secara resmi oleh MC, Fenti Fiqri F., S.E., yang kemudian mengajak seluruh peserta menyanyikan lagu kebangsaan Indonesia Raya dan Mars IIM Surakarta, sebagai simbol nasionalisme dan loyalitas terhadap almamater.\n\nDalam sambutannya, Rektor IIM Surakarta, Edy Muslimin, S.Ag., M.S.I., menekankan pentingnya integritas dan profesionalisme mahasiswa dalam menjalankan PPL sebagai salah satu bentuk pengabdian di masyarakat. “PPL bukan hanya ajang praktik, tetapi juga representasi kualitas lulusan Fakultas Tarbiyah IIM Surakarta di dunia pendidikan,” ujarnya.\n\nRangkaian acara kemudian dilanjutkan dengan sosialisasi dari BPJS Ketenagakerjaan Surakarta, yang memberikan wawasan penting mengenai perlindungan sosial dan hak mahasiswa selama menjalani praktik di sekolah. Mahasiswa diajak untuk memahami pentingnya keamanan dan kenyamanan kerja, termasuk selama menjalankan tugas sebagai praktikan di lingkungan pendidikan.\n\nSalah satu sesi inti pembekalan adalah materi bertajuk “Kurikulum Deep Learning di Sekolah” yang disampaikan oleh Dr. H. M. Ja’far Nashir, S.Ag., M.Ag. Dalam pemaparannya, ia mengenalkan konsep Pembelajaran Mendalam (Deep Learning) yang kini menjadi arah transformasi pendidikan nasional. Pendekatan ini menekankan pada pengalaman belajar yang berkesadaran, bermakna, dan menggembirakan, melalui pengembangan potensi peserta didik secara holistik: olah pikir, olah hati, olah rasa, dan olah raga.\n\nKetua Panitia PPL, Lailla Hidayatul Amin, S.Pd., M.Pd.I., dalam sesi selanjutnya memaparkan mekanisme teknis pelaksanaan PPL tahun 2025. Dalam paparannya, ia menjelaskan tata cara penempatan, peran DPL, serta prosedur pelaporan mahasiswa selama kegiatan berlangsung.\n\nMemasuki sesi berikutnya, Ketua Panitia PPL, Lailla Hidayatul Amin, S.Pd., M.Pd.I., menyampaikan materi tentang mekanisme teknis pelaksanaan PPL 2025, yang mencakup penempatan lokasi praktik, pembagian peran antara mahasiswa dan guru pamong, hingga sistem pelaporan dan penilaian yang harus dilalui oleh setiap peserta.\n\nPembekalan ditutup dengan koordinasi antara mahasiswa dan Dosen Pembimbing Lapangan (DPL). Dalam sesi ini, mahasiswa dan dosen melakukan diskusi intensif guna menyamakan persepsi, menjalin komunikasi awal, serta memastikan kesiapan seluruh pihak sebelum pelaksanaan PPL dimulai di lapangan.', 5, '/api/v1/media/d079796a-a477-4def-a167-9b352514ae31', NULL, 'bottom', 1, 0, '2026-11-24 06:35:57', '2026-11-24 06:35:57'),
(42, 'Direktur Pascasarjana dan Dekan Fakultas Tarbiyah IIM Surakarta Saksikan Deklarasi Pembangunan Zona Integritas MAN 1 Kar', '16 Agustus 2025', 1, 'Madrasah Aliyah Negeri (MAN) 1 Karanganyar resmi mendeklarasikan Pembangunan Zona Integritas menuju Wilayah Bebas dari Korupsi (WBK) dan Wilayah Birokrasi Bersih Melayani (WBBM). Acara ini...', 'Madrasah Aliyah Negeri (MAN) 1 Karanganyar resmi mendeklarasikan Pembangunan Zona Integritas menuju Wilayah Bebas dari Korupsi (WBK) dan Wilayah Birokrasi Bersih Melayani (WBBM). Acara ini berlangsung pada Sabtu, 16 Agustus 2025 di Aula Kampus 1 MAN 1 Karanganyar dengan dihadiri seluruh guru dan tenaga kependidikan.\n\nDalam acara tersebut, hadir pula Dr. Sukari, S.Pd.I, M.Pd.I, Direktur Pascasarjana IIM Surakarta beserta Dr. HM. Jafar Nashir, M.Ag. Dekan Fakultas Tarbiyah IIM Surakarta yang turut menyaksikan jalannya deklarasi. Kehadiran kedua pimpinan perguruan tinggi ini menjadi bentuk dukungan nyata dalam upaya mewujudkan tata kelola pendidikan yang bersih, transparan, dan akuntabel.\n\nKepala MAN 1 Karanganyar Dr. H, Sumiran, S.Pd., M.Pd., dalam sambutannya menegaskan bahwa pembangunan zona integritas ini merupakan komitmen kuat madrasah untuk meningkatkan kualitas layanan pendidikan sekaligus menjawab tuntutan masyarakat terhadap birokrasi yang bersih dari praktik korupsi.\n\n“Deklarasi ini bukan hanya seremonial, tetapi menjadi langkah nyata MAN 1 Karanganyar dalam mengedepankan integritas, profesionalitas, dan pelayanan prima bagi peserta didik maupun masyarakat,” ujarnya.\n\nDirektur Pascasarjana Institut Islam Mamba’ul ’Ulum Surakarta dalam kesempatan tersebut menyampaikan apresiasi tinggi terhadap komitmen MAN 1 Karanganyar.\n\nMenurutnya, pembangunan zona integritas di lingkungan pendidikan adalah pondasi penting dalam mencetak generasi yang tidak hanya cerdas secara intelektual, tetapi juga berakhlak mulia dan menjunjung tinggi kejujuran.\n\nSementara itu, Dekan Fakultas Tarbiyah IIM Surakarta menambahkan bahwa keberhasilan implementasi WBK dan WBBM membutuhkan sinergi antara seluruh guru, tenaga kependidikan, serta dukungan dari masyarakat.\n\n“Kami meyakini bahwa pendidikan yang bersih dari korupsi akan melahirkan peradaban yang lebih baik,” tegasnya.\n\nAcara ditutup dengan penandatanganan komitmen bersama oleh seluruh jajaran guru dan tenaga kependidikan MAN 1 Karanganyar sebagai wujud nyata pelaksanaan pembangunan zona integritas.\n\nDengan deklarasi ini, MAN 1 Karanganyar meneguhkan diri sebagai madrasah yang siap menjadi teladan dalam mewujudkan layanan publik yang bersih, transparan, bebas dari korupsi, serta berorientasi pada pelayanan prima.', 5, '/api/v1/media/9ebe2d19-dacc-4d39-a619-0d2d6f5aaae4', NULL, 'bottom', 1, 0, '2026-11-24 06:36:31', '2026-11-24 06:36:31'),
(43, 'Pelantikan Ormawa Fakultas Tarbiyah KM-IIM Surakarta, Perkuat Sinergi dan Solidaritas Mahasiswa', '14 Oktober 2026', 1, 'Organisasi Mahasiswa (Ormawa) Fakultas Tarbiyah Keluarga Mahasiswa Institut Islam Mamba’ul ‘Ulum (KM-IIM) Surakarta resmi melaksanakan pelantikan pengurus di Aula Kampus Institut Islam Mamba’ul...', 'Organisasi Mahasiswa (Ormawa) Fakultas Tarbiyah Keluarga Mahasiswa Institut Islam Mamba’ul ‘Ulum (KM-IIM) Surakarta resmi melaksanakan pelantikan pengurus di Aula Kampus Institut Islam Mamba’ul ‘Ulum Surakarta.\n\nPelantikan tersebut mencakup empat organisasi mahasiswa, yaitu Badan Eksekutif Mahasiswa Fakultas Tarbiyah (BEM FT KM-IIM), Himpunan Mahasiswa Program Studi Pendidikan Agama Islam (HMPS PAI), Himpunan Mahasiswa Program Studi Pendidikan Guru Madrasah Ibtidaiyah (HMPS PGMI), dan Himpunan Mahasiswa Program Studi Pendidikan Islam Anak Usia Dini (HMPS PIAUD).\n\nKegiatan ini menjadi momentum awal bagi para pengurus untuk mengemban amanah dan tanggung jawab organisasi selama satu periode ke depan. Pelantikan tidak hanya menjadi bentuk pengesahan kepengurusan, tetapi juga menjadi langkah awal dalam membangun komitmen, meningkatkan kualitas kepemimpinan, serta memperkuat peran mahasiswa dalam mendukung kemajuan Fakultas Tarbiyah.\n\nMelalui kepengurusan yang baru, seluruh organisasi diharapkan mampu membangun komunikasi yang baik, menjalin kerja sama, serta saling mendukung dalam menjalankan program kerja. Sinergi antara BEM FT KM-IIM, HMPS PAI, HMPS PGMI, dan HMPS PIAUD menjadi hal penting untuk menciptakan lingkungan organisasi yang solid, aktif, progresif, dan berorientasi pada kemaslahatan mahasiswa.\n\nPelantikan ini juga menjadi pengingat bahwa organisasi bukan sekadar tempat menjalankan program kerja, melainkan ruang untuk belajar memimpin, membangun karakter, menumbuhkan kepedulian, dan menguatkan semangat pengabdian. Setiap pengurus diharapkan mampu menjalankan amanah dengan penuh tanggung jawab, menjunjung tinggi nilai-nilai keislaman, serta memberikan kontribusi nyata bagi mahasiswa dan institusi.\n\nDengan semangat kebersamaan dan kolaborasi, Ormawa Fakultas Tarbiyah KM-IIM Surakarta diharapkan mampu membawa perubahan positif serta mewujudkan fakultas yang semakin maju, berprestasi, dan berdaya saing.\n\nPelantikan adalah awal dari sebuah amanah. Melalui komunikasi, kolaborasi, dan solidaritas, mari bersama-sama mengukir perjuangan dan membawa Fakultas Tarbiyah KM-IIM Surakarta menuju arah yang lebih baik.', 5, '/api/v1/media/af6a71ab-2632-4278-881c-4c80f617afad', NULL, 'bottom', 1, 0, '2026-11-24 06:38:48', '2026-11-24 06:38:48'),
(44, 'Perkuat Kolaborasi Tridarma, Fakultas Tarbiyah IIM Surakarta Jalin Kerja Sama dengan FTIK UIN Gus Dur Pekalongan', '21 Oktober 2026', 1, 'Fakultas Tarbiyah Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta memperluas jejaring akademik melalui kerja sama dengan Fakultas Tarbiyah dan Ilmu Keguruan (FTIK) UIN K.H. Abdurrahman Wahid...', 'Fakultas Tarbiyah Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta memperluas jejaring akademik melalui kerja sama dengan Fakultas Tarbiyah dan Ilmu Keguruan (FTIK) UIN K.H. Abdurrahman Wahid Pekalongan. Kegiatan yang dilaksanakan pada Rabu, 21 Oktober 2026, ini menjadi langkah strategis dalam meningkatkan mutu pendidikan, penelitian, pengabdian kepada masyarakat, serta penguatan tata kelola kelembagaan.\n\nKerja sama tersebut melibatkan Dekan Fakultas Tarbiyah IIM Surakarta, Lailla Hidayatul Amin, S.Pd., M.Pd.I., Direktur Pasca Sarjana Dr. H. M. Ja’far Nashir, M.Ag dan Kepala Lembaga Penjaminan Mutu (LPM) IIM Surakarta, Septian Nur Ika Trisnawati, M.Pd bersama salah satu staf keuangan Tiya Maryani, A.Md. Rombongan disambut oleh Dekan FTIK UIN K.H. Abdurrahman Wahid Pekalongan, Prof. Dr. H. Muhlisin, M.Ag.\n\nKegiatan ini merupakan bagian dari upaya mempererat hubungan kelembagaan sekaligus menjajaki peluang kolaborasi dalam pengembangan program studi dan pelaksanaan tridarma perguruan tinggi. Melalui kerja sama ini, kedua institusi berkomitmen membangun kemitraan yang tidak hanya bersifat administratif, tetapi juga diwujudkan melalui program akademik yang berkelanjutan.\n\nDalam kesepakatan kerja sama tersebut, kedua lembaga menetapkan sejumlah bidang kolaborasi, meliputi visiting lecturer atau dosen tamu, keterlibatan dosen sebagai penguji eksternal bagi mahasiswa, penelitian bersama (joint research), pengabdian kepada masyarakat (PKM) bersama, serta publikasi ilmiah bersama.\n\nProgram visiting lecturer diharapkan dapat memperluas pertukaran pengetahuan dan pengalaman pembelajaran antardosen. Sementara itu, keterlibatan penguji eksternal diharapkan dapat memperkaya perspektif akademik dalam proses evaluasi mahasiswa. Kolaborasi penelitian, PKM, dan publikasi ilmiah juga diarahkan untuk memperkuat produktivitas akademik serta memperluas kontribusi perguruan tinggi bagi masyarakat.\n\nKegiatan tersebut turut melibatkan unsur pimpinan dan perwakilan program studi di lingkungan FTIK UIN K.H. Abdurrahman Wahid Pekalongan. Program studi yang terlibat meliputi Pendidikan Agama Islam (PAI), Pendidikan Bahasa Arab (PBA), Pendidikan Guru Madrasah Ibtidaiyah (PGMI), Pendidikan Islam Anak Usia Dini (PIAUD), Tadris Bahasa Inggris (TBI/TBIG), Tadris Matematika, Tadris Bahasa Indonesia, serta Pendidikan Profesi Guru (PPG). Kehadiran para ketua program studi, sekretaris program studi, staf perwakilan, dan ketua BAU diharapkan memperkuat koordinasi dalam pelaksanaan kerja sama lintas program studi.\n\nKedua fakultas berkomitmen menindaklanjuti kesepakatan tersebut melalui pelaksanaan program-program kolaboratif pada tahun akademik 2026/2027. Dengan demikian, kerja sama diharapkan dapat menghasilkan kegiatan nyata yang mendukung peningkatan kualitas pembelajaran, pengembangan kompetensi dosen, produktivitas penelitian, serta pelaksanaan pengabdian kepada masyarakat.\n\nPerkuat Penjaminan Mutu melalui Kunjungan ke LPM UIN Gus Dur\n\nSelain menjalin kerja sama dengan FTIK, rombongan Fakultas Tarbiyah IIM Surakarta juga melaksanakan kunjungan ke Lembaga Penjaminan Mutu (LPM) UIN K.H. Abdurrahman Wahid Pekalongan yang diketuai oleh Dr. Hj. Sopiah, M.Ag.\n\nKunjungan tersebut difokuskan pada pertukaran informasi mengenai pelaksanaan tugas dan fungsi LPM, khususnya dalam mendukung penjaminan mutu perguruan tinggi. Melalui kegiatan berbagi informasi ini, IIM Surakarta berupaya memperoleh wawasan dan pengalaman yang dapat menjadi bahan penguatan sistem penjaminan mutu internal.\n\nPertukaran informasi antarlembaga penjaminan mutu menjadi bagian penting dalam pengembangan tata kelola perguruan tinggi. Penguatan penjaminan mutu diperlukan untuk memastikan pelaksanaan pendidikan, penelitian, pengabdian kepada masyarakat, serta layanan akademik berjalan secara terencana dan berorientasi pada peningkatan kualitas berkelanjutan.\n\nMelalui kunjungan tersebut, diharapkan terbangun komunikasi dan hubungan kelembagaan yang dapat dilanjutkan dengan pertukaran pengalaman serta praktik baik dalam pelaksanaan penjaminan mutu.\n\nKomitmen Mewujudkan Kerja Sama Berkelanjutan\n\nRangkaian kegiatan kerja sama dengan FTIK dan kunjungan ke LPM UIN K.H. Abdurrahman Wahid Pekalongan menunjukkan komitmen Fakultas Tarbiyah IIM Surakarta untuk terus mengembangkan kemitraan strategis dengan perguruan tinggi lain.\n\nKolaborasi akademik dan penguatan penjaminan mutu merupakan dua aspek yang saling mendukung dalam upaya meningkatkan kualitas penyelenggaraan pendidikan tinggi. Kerja sama yang dirancang melalui program-program konkret diharapkan dapat memberikan manfaat bagi dosen, mahasiswa, program studi, dan institusi secara keseluruhan.\n\nDengan rencana implementasi pada tahun akademik 2026/2027, Fakultas Tarbiyah IIM Surakarta berharap kemitraan ini menjadi awal dari kolaborasi yang produktif, berkelanjutan, dan berorientasi pada peningkatan mutu tridarma perguruan tinggi.', 5, '/api/v1/media/c9efdc10-8a8e-4c5c-b69f-e54402566708', '[\"/api/v1/media/07af478c-63cd-4e59-bb4e-a253d31e6b59\",\"/api/v1/media/b858cdee-3590-4065-9392-e54a930346f7\",\"/api/v1/media/ec22201c-2883-4183-824f-ed998f1dd3b6\",\"/api/v1/media/6aaea067-9bb5-4eba-bbeb-2f93d6c301f9\"]', 'middle', 1, 0, '2026-11-24 06:40:01', '2026-11-24 06:40:01'),
(45, 'Dosen Fakultas Tarbiyah IIM Surakarta Menjadi Presenter pada ICIEI 2026', '22 Oktober 2026', 1, 'Dosen Fakultas Tarbiyah Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta berpartisipasi sebagai presenter dalam 4th International Conference on Islamic Education and Instruction (ICIEI) 2026 yang...', 'Dosen Fakultas Tarbiyah Institut Islam Mamba’ul ‘Ulum (IIM) Surakarta berpartisipasi sebagai presenter dalam 4th International Conference on Islamic Education and Instruction (ICIEI) 2026 yang diselenggarakan pada Kamis, 22 Oktober 2026. Konferensi internasional ini mengangkat tema besar tentang transformasi pendidikan yang berpusat pada manusia, berkelanjutan, dan didukung oleh kecerdasan buatan (Artificial Intelligence/AI).\n\nDalam konferensi tersebut, tim dosen mempresentasikan artikel ilmiah berjudul “Empowering Student Autonomy Through AI-Supported, Human-Centric, and Inclusive Learning” atau Memberdayakan Otonomi Mahasiswa melalui Pembelajaran Inklusif yang Berpusat pada Manusia dan Didukung AI.\n\nArtikel ini ditulis secara kolaboratif oleh Lailla Hidayatul Amin, Alfian Eko Rochmawan, Iffah Mukhlisah, Desy Rosita, dan Deliya Rahmawati. Penelitian tersebut mengangkat isu penting mengenai pemberdayaan otonomi mahasiswa melalui pemanfaatan teknologi kecerdasan buatan yang tetap menempatkan manusia sebagai pusat pembelajaran serta memperhatikan prinsip inklusivitas.\n\nPartisipasi dalam ICIEI 2026 menjadi kesempatan bagi dosen IIM Surakarta untuk mempresentasikan gagasan akademik di forum internasional, memperluas jejaring ilmiah, serta memperoleh perspektif baru mengenai perkembangan pendidikan Islam di era transformasi digital. Pemanfaatan AI dalam pendidikan tidak hanya dipandang sebagai inovasi teknologi, tetapi juga sebagai sarana untuk mendukung kemandirian belajar, meningkatkan partisipasi mahasiswa, dan menciptakan pengalaman pembelajaran yang lebih adaptif terhadap keberagaman kebutuhan peserta didik.\n\nMelalui penelitian ini, tim penulis menekankan pentingnya keseimbangan antara pemanfaatan teknologi, penguatan peran pendidik, dan nilai-nilai kemanusiaan dalam proses pembelajaran. Teknologi AI diharapkan dapat menjadi pendukung pembelajaran yang memberdayakan mahasiswa untuk berpikir kritis, mengambil keputusan secara mandiri, dan bertanggung jawab atas proses belajarnya, tanpa mengesampingkan etika, interaksi sosial, dan prinsip pendidikan inklusif.\n\nKeikutsertaan dosen Fakultas Tarbiyah IIM Surakarta dalam konferensi internasional ini merupakan bagian dari upaya memperkuat budaya penelitian, publikasi ilmiah, dan kolaborasi akademik. Kegiatan tersebut juga diharapkan dapat mendorong pengembangan inovasi pembelajaran di lingkungan perguruan tinggi Islam yang responsif terhadap perkembangan teknologi sekaligus berlandaskan nilai-nilai pendidikan Islam.\n\nTentang ICIEI 2026\n\n4th International Conference on Islamic Education and Instruction (ICIEI 2026) merupakan forum akademik internasional yang diselenggarakan oleh Fakultas Ilmu Tarbiyah, UIN Raden Mas Said Surakarta. Konferensi ini menjadi ruang pertemuan akademisi dan peneliti untuk bertukar gagasan, mempresentasikan hasil penelitian, serta mendiskusikan arah pengembangan pendidikan Islam dan pembelajaran dalam menghadapi tantangan masa depan.', 5, '/api/v1/media/d99dc836-b1e6-4071-9b9b-b9d8129ca678', '[\"/api/v1/media/009af8f9-5454-4c4a-ae40-72fabb38b6ae\",\"/api/v1/media/3f5a4e30-8915-4c30-b415-75ffcc2ea8d8\",\"/api/v1/media/b53ff32d-1e60-460b-af62-ad344204598a\",\"/api/v1/media/4e57adf6-13c8-45e7-a764-2d5bc790aa18\"]', 'middle', 1, 0, '2026-11-24 06:41:29', '2026-11-24 06:41:29');

